    [data-theme='cyberpunk'] .kp-progressbar {
        --kp-progressbar-height: calc(0.875rem * var(--kp-progressbar-scale, 1));
        /* One pixel of the drawing at this bar's size: dash pitches, lane
           offsets and stream travel are counted in it so the bar grows as one
           drawing; 1-2px rules and frame lines stay the theme's line weight. */
        --kp-cp-px: calc(1px * var(--kp-progressbar-scale, 1));
        --kp-cp-void: var(--sidebar-background);
        --kp-cp-cut: var(--kp-progressbar-height);
    }

