            linear-gradient(var(--kp-scrollbar-emboss), var(--kp-scrollbar-emboss)) right calc(var(--kp-scrollbar-inset) + 7px) bottom
                calc(
                    var(--kp-scrollbar-inset) + min(16px, calc(50% + 0.5px - var(--kp-scrollbar-inset))) - 1px -
