            linear-gradient(var(--popover), var(--popover)) right var(--kp-scrollbar-inset) bottom
                calc(var(--kp-scrollbar-inset) + min(16px, calc(50% + 0.5px - var(--kp-scrollbar-inset))) - 1px) / 16px 1px no-repeat,
            linear-gradient(var(--popover), var(--popover)) right calc(var(--kp-scrollbar-inset) + 15px) bottom var(--kp-scrollbar-inset) / 1px
                min(16px, calc(50% - var(--kp-scrollbar-inset))) no-repeat,
            linear-gradient(var(--foreground), var(--foreground)) right var(--kp-scrollbar-inset) bottom var(--kp-scrollbar-inset) / 1px
                min(16px, calc(50% - var(--kp-scrollbar-inset))) no-repeat,
            linear-gradient(var(--foreground), var(--foreground)) right var(--kp-scrollbar-inset) bottom var(--kp-scrollbar-inset) / 16px 1px
                no-repeat,
            linear-gradient(var(--card), var(--card)) right var(--kp-scrollbar-inset) bottom
                calc(var(--kp-scrollbar-inset) + min(16px, calc(50% + 0.5px - var(--kp-scrollbar-inset))) - 2px) / 16px 1px no-repeat,
            linear-gradient(var(--card), var(--card)) right calc(var(--kp-scrollbar-inset) + 14px) bottom var(--kp-scrollbar-inset) / 1px
                min(16px, calc(50% - var(--kp-scrollbar-inset))) no-repeat,
            linear-gradient(var(--border), var(--border)) right calc(var(--kp-scrollbar-inset) + 1px) bottom var(--kp-scrollbar-inset) / 1px
                min(16px, calc(50% - var(--kp-scrollbar-inset))) no-repeat,
            linear-gradient(var(--border), var(--border)) right var(--kp-scrollbar-inset) bottom calc(var(--kp-scrollbar-inset) + 1px) / 16px 1px
                no-repeat,
            linear-gradient(var(--card), var(--card)) right var(--kp-scrollbar-inset) bottom var(--kp-scrollbar-inset) / 16px
                min(16px, calc(50% - var(--kp-scrollbar-inset))) no-repeat;
        --kp-scrollbar-track:
            linear-gradient(to left, transparent 0 calc(var(--kp-scrollbar-inset) + 16px), var(--popover) calc(var(--kp-scrollbar-inset) + 16px)),
            conic-gradient(var(--popover) 0 25%, var(--card) 0 50%, var(--popover) 0 75%, var(--card) 0) 0 0 / 2px 2px;
        --kp-scrollbar-thumb-paint:
            linear-gradient(var(--popover), var(--popover)) right var(--kp-scrollbar-inset) top var(--kp-scrollbar-thumb-top) / 16px 1px no-repeat,
            linear-gradient(var(--popover), var(--popover)) right calc(var(--kp-scrollbar-inset) + 15px) top var(--kp-scrollbar-thumb-top) / 1px
                var(--kp-scrollbar-thumb) no-repeat,
            linear-gradient(var(--foreground), var(--foreground)) right var(--kp-scrollbar-inset) top var(--kp-scrollbar-thumb-top) / 1px
                var(--kp-scrollbar-thumb) no-repeat,
            linear-gradient(var(--foreground), var(--foreground)) right var(--kp-scrollbar-inset) top
                calc(var(--kp-scrollbar-thumb-top) + var(--kp-scrollbar-thumb) - 1px) / 16px 1px no-repeat,
            linear-gradient(var(--card), var(--card)) right var(--kp-scrollbar-inset) top calc(var(--kp-scrollbar-thumb-top) + 1px) / 16px 1px
                no-repeat,
            linear-gradient(var(--card), var(--card)) right calc(var(--kp-scrollbar-inset) + 14px) top var(--kp-scrollbar-thumb-top) / 1px
                var(--kp-scrollbar-thumb) no-repeat,
            linear-gradient(var(--border), var(--border)) right calc(var(--kp-scrollbar-inset) + 1px) top var(--kp-scrollbar-thumb-top) / 1px
                var(--kp-scrollbar-thumb) no-repeat,
            linear-gradient(var(--border), var(--border)) right var(--kp-scrollbar-inset) top
                calc(var(--kp-scrollbar-thumb-top) + var(--kp-scrollbar-thumb) - 2px) / 16px 1px no-repeat,
            linear-gradient(var(--card), var(--card)) right var(--kp-scrollbar-inset) top var(--kp-scrollbar-thumb-top) / 16px
                var(--kp-scrollbar-thumb) no-repeat;
        scrollbar-width: none;
        background: var(--kp-scrollbar-up), var(--kp-scrollbar-down), var(--kp-scrollbar-track), var(--kp-scrollbar-ground);
    }

    /* A popover's bar sits inside its two-pixel bevel, and its words keep
       four pixels off the bar. A dialog's padding already has the room. */
    [data-theme='retro'] .kp-popover {
        --kp-scrollbar-inset: 2px;
        --kp-scrollbar-ground: var(--popover);
        padding-inline-end: calc(0.25rem + 18px);
    }

    /* A tooltip draws no bar, so it takes no room for one: the package's
       own end padding, as before the bar [scope-93]. */
    [data-theme='retro'] .kp-popover.kp-tooltip {
        padding-inline-end: 0.5rem;
    }

    [data-theme='retro'] .kp-dialog {
        --kp-scrollbar-inset: 0px;
        --kp-scrollbar-ground: var(--popover);
        --kp-retro-close-room: 0px;
    }

    /* The close button stands beside the bar, never on it [retro notes,
       2026-09-15, overlays--dialog-parts]. A dialog without a body draws its
       bar down the whole end edge of its padding box, from the very top, and
       the package pins the close button half a rem in from that same edge:
       the button's last 8px lay over the bar's up arrow. Here it moves in by
       the bar's width, and the title's room for it grows by the same. Reset
       to zero on every dialog above, so the value never inherits into a
       dialog inside this one. */
    [data-theme='retro'] .kp-dialog:not(:has(> .kp-dialog__body)):has(> .kp-dialog__close) {
        --kp-retro-close-room: var(--kp-scrollbar-size);
    }

    [data-theme='retro'] .kp-dialog > .kp-dialog__close {
        inset-inline-end: calc(var(--kp-space-sm, 0.5rem) + var(--kp-retro-close-room));
    }

    [data-theme='retro'] .kp-dialog__body {
        --kp-scrollbar-inset: 0px;
        --kp-scrollbar-ground: transparent;
        padding-inline-end: 20px;
    }

    /* The three windows whose only answer was that broken selector list.
       Square, as every window here is; their grounds stay the ones they were
       approved with. A menu is the popover's list and draws no bar of its
       own, a confirmation is a dialog and draws the dialog's, a toast
       never scrolls and draws none. */
    [data-theme='retro'] .kp-menu,
    [data-theme='retro'] .kp-confirm,
    [data-theme='retro'] .kp-toast {
        border-radius: 0;
    }

    [data-theme='retro'] :is(.kp-popover:not(.kp-tooltip), .kp-dialog:not(:has(> .kp-dialog__body)), .kp-dialog__body)::-webkit-scrollbar {
        display: none;
    }

    /* Enabled: ink arrows and the thumb. The thumb is at least eight pixels
       long, as the platform's is, and both lengths are whole pixels. */
    [data-theme='retro'] :is(.kp-popover:not(.kp-tooltip), .kp-dialog:not(:has(> .kp-dialog__body)), .kp-dialog__body)[data-kp-popover-overflowing] {
        --kp-scrollbar-ink: var(--foreground);
        --kp-scrollbar-emboss: transparent;
        --kp-scrollbar-thumb: round(
            down,
            max(8px, calc((var(--kp-scroll-view) - 2 * var(--kp-scrollbar-inset) - 32px) * var(--kp-scroll-ratio))),
            1px
        );
        --kp-scrollbar-thumb-top: round(
            calc(
                var(--kp-scrollbar-inset) + 16px + (var(--kp-scroll-view) - 2 * var(--kp-scrollbar-inset) - 32px - var(--kp-scrollbar-thumb)) *
                    var(--kp-scroll-progress)
            ),
            1px
        );
        background:
            var(--kp-scrollbar-up), var(--kp-scrollbar-down), var(--kp-scrollbar-thumb-paint), var(--kp-scrollbar-track), var(--kp-scrollbar-ground);
    }

    /* The combo button the demo paints [S49, A12]: `appearance: none` and
       a raised square with the ink arrow on it. KT8 kept the platform
       list themeable and refused this; Kenny chose the demo for this
       theme on 2026-09-08, and tests/fixtures.spec.mjs carries the
       exception with that reason. */
    [data-theme='retro'] select.kp-field__input {
        appearance: none;
        padding-inline-end: 2.1rem;
        background-image:
            linear-gradient(45deg, transparent 50%, var(--foreground) 50%), linear-gradient(135deg, var(--foreground) 50%, transparent 50%),
            linear-gradient(180deg, var(--popover) 0 2px, transparent 2px), linear-gradient(90deg, var(--popover) 0 2px, transparent 2px),
            linear-gradient(0deg, var(--border-strong) 0 2px, transparent 2px), linear-gradient(270deg, var(--border-strong) 0 2px, transparent 2px),
            linear-gradient(var(--card), var(--card));
        background-repeat: no-repeat;
        background-size:
            6px 6px,
            6px 6px,
            18px 18px,
            18px 18px,
            18px 18px,
            18px 18px,
            18px 18px;
        background-position:
            right 12px center,
            right 6px center,
            right 4px center,
            right 4px center,
            right 4px center,
            right 4px center,
            right 4px center;
    }

    /* Severity toasts [scope-60]. The plain toast above is repainted here in
       a later layer than kp.components, which swallowed every variant's
       plate; each is restated on the alert's token pair, as the severity
       badge wears it. */
    [data-theme='retro'] .kp-toast--success {
        background: var(--success);
        color: var(--success-foreground);
        border-color: var(--success);
    }

    [data-theme='retro'] .kp-toast--info {
        background: var(--info);
        color: var(--info-foreground);
        border-color: var(--info);
    }

    [data-theme='retro'] .kp-toast--warning {
        background: var(--warning);
        color: var(--warning-foreground);
        border-color: var(--warning);
    }

    [data-theme='retro'] .kp-toast--destructive,
    [data-theme='retro'] .kp-toast--error {
        background: var(--destructive);
        color: var(--destructive-foreground);
        border-color: var(--destructive);
    }

    [data-theme='retro'] :is(.kp-toast--success, .kp-toast--info, .kp-toast--warning, .kp-toast--destructive, .kp-toast--error) .kp-button--ghost {
        color: inherit;
    }

    /* A button hovered on a toast takes a shade of the toast's own plate
       (--kp-toast-button-hover, set in kp.components), not this theme's page hover (Kenny's second nostromo pass,
       2026-09-13). Restated here because this layer repaints the hover. */
    [data-theme='retro'] .kp-toast :is(.kp-button--ghost, .kp-icon-button):hover:not(:disabled) {
        background: var(--kp-toast-button-hover);
        color: inherit;
    }

    /* And the keyboard highlight is the selection bar, as it is on a
       mark: navy with white on it [S49, A12]. */
    [data-theme='retro'] .kp-combobox__option.is-active,
    [data-theme='retro'] .kp-palette__option.is-active,
    [data-theme='retro'] .kp-datepicker__day.is-active {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    [data-theme='retro'] .kp-combobox__list,
    [data-theme='retro'] .kp-palette,
    [data-theme='retro'] .kp-theme-menu__list {
        background: var(--background);
        color: var(--foreground);
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-raised), var(--kp-drop);
    }

    /* The wrapper round the theme picker's icon button is not a card: only its
       dropdown list is. */
    [data-theme='retro'] .kp-theme-menu {
        background: none;
        border: 0;
        box-shadow: none;
    }

    [data-theme='retro'] .kp-toasts {
        gap: 3px;
    }

    [data-theme='retro'] .kp-dialog__title {
        font-family: var(--theme-font-display);
        font-weight: 700;
        background: var(--kp-ramp);
        color: var(--primary-foreground);
        padding: 3px 0.5rem;
        margin: 0 0 0.75rem;
    }

    /* The title bar's words stop short of the close button [retro notes,
       2026-09-15, overlays--dialog-parts]. The `padding` above restates the
       inline end too, and this layer comes after the package's, so the
       package's room for the button (css/components.css, scope-60) was
       lost: the words ran 16px under the button. The plate itself still
       runs under the button, as a 1995 title bar does. */
    [data-theme='retro'] .kp-dialog:has(> .kp-dialog__close) > .kp-dialog__title {
        padding-inline-end: calc(var(--kp-dialog-close-size, 2.25rem) + var(--kp-space-sm, 0.5rem) + 0.5rem + var(--kp-retro-close-room, 0px));
    }

    /* The keyboard highlight is the selection bar with its own ink (KT8:
       the text keeps its colour where a bar is a wash; here the bar carries
       the ink). */
    [data-theme='retro'] .kp-menu__item:hover {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    /* The list highlight of a combobox or a palette stays the base layer's
       wash of the ink: KT8's review finding on this very theme (a highlight
       is not a plate, the text keeps its colour), held by the fixture test. */

    /* The plain alert only [gap-1, Kenny 2026-09-10]. This rule used to
       repaint the ground of EVERY alert, and `kp.register` is a later layer
       than `kp.components`, so it beat `.kp-alert--destructive`'s own plate
       while that variant's ink — `--destructive-foreground`, which is drawn
       to sit ON the plate — stayed. Measured in firefox on 2026-09-12:
       seventeen of the twenty-two themes carried a destructive alert whose
       text was unreadable, grotesk at 1.00 exactly, white on white.

       Kenny saw it in chassis-rs and said to write it down and touch
       nothing; this is the round he asked for it in. Same shape as fix-12,
       one property over: a register overriding half of a pair the base
       layer defines together. */
    [data-theme='retro'] .kp-alert:not([class*='kp-alert--']) {
        background: var(--popover);
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-sunken);
    }

    [data-theme='retro'] .kp-alert__label {
        font-family: var(--theme-font-display);
        font-weight: 700;
    }

    [data-theme='retro'] .kp-grid__tile,
    [data-theme='retro'] .kp-split__pane {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-raised);
    }

    [data-theme='retro'] .kp-grid {
        gap: 3px;
    }

    [data-theme='retro'] .kp-split {
        gap: 0;
    }

    [data-theme='retro'] .kp-split__separator {
        background: var(--background);
        inline-size: 4px;
        box-shadow: var(--kp-raised);
    }

    /* Top and bottom [gap-12]: the thickness above is an inline size, so
       a horizontal split takes the same value as a block size. */
    [data-theme='retro'] .kp-split[data-kp-orientation='horizontal'] > .kp-split__separator {
        inline-size: auto;
        block-size: 4px;
    }

    /* The footer: the chrome, and the fine print as a status bar. */
    [data-theme='retro'] .kp-footer {
        background: var(--background);
        color: var(--foreground);
        position: relative;
    }

    /* The resize grip in the corner of the status bar [S49, A2]: the
       three diagonal runs of pixels a 1995 window ends on. */
    [data-theme='retro'] .kp-footer::after {
        content: '';
        position: absolute;
        inset-inline-end: 3px;
        inset-block-end: 3px;
        inline-size: 13px;
        block-size: 13px;
        background-image:
            linear-gradient(135deg, transparent 0 46%, var(--popover) 46% 62%, var(--border-strong) 62% 78%, transparent 78%),
            linear-gradient(135deg, transparent 0 46%, var(--popover) 46% 62%, var(--border-strong) 62% 78%, transparent 78%),
            linear-gradient(135deg, transparent 0 46%, var(--popover) 46% 62%, var(--border-strong) 62% 78%, transparent 78%);
        background-repeat: no-repeat;
        background-size:
            5px 5px,
            9px 9px,
            13px 13px;
        background-position:
            right bottom,
            right bottom,
            right bottom;
    }

    [data-theme='retro'] .kp-footer h4 {
        font-family: var(--theme-font-display);
        font-weight: 700;
    }

    [data-theme='retro'] .kp-footer a {
        color: var(--foreground);
        font-size: 0.85rem;
        text-decoration: underline;
        text-decoration-color: var(--border);
        text-underline-offset: 2px;
    }

    [data-theme='retro'] .kp-footer a:hover,
    [data-theme='retro'] .kp-footer a:focus-visible {
        background: var(--primary);
        color: var(--primary-foreground);
        text-decoration-color: transparent;
    }

    [data-theme='retro'] .kp-footer .microlabel {
        display: block;
        color: var(--foreground);
        padding: 0.1rem 0.6rem;
        border: 1px solid var(--border-strong);
        box-shadow: var(--kp-sunken);
    }

    [data-theme='retro'] .kp-footer .microlabel::before,
    [data-theme='retro'] .kp-footer .microlabel::after {
        content: none;
    }

    /* ── Badges, tags, status: sunken panels ───────────────────────────── */

    [data-theme='retro'] .kp-badge,
    [data-theme='retro'] .kp-tag {
        border-radius: 0;
        border: 1px solid var(--border-strong);
        box-shadow: var(--kp-sunken);
        font-family: var(--kp-dos);
        letter-spacing: 0.04em;
    }

    /* The badge's type size is the package's [scope-87]; the tag keeps this register's. */
    [data-theme='retro'] .kp-tag {
        font-size: 0.95rem;
    }

    [data-theme='retro'] .kp-health {
        font-family: var(--kp-dos);
        font-size: 1rem;
    }

    [data-theme='retro'] .kp-health__dot {
        border-radius: 0;
        box-shadow: var(--kp-raised);
    }

    /* The 50% dither of a control still loading. */
    [data-theme='retro'] .kp-skeleton {
        background-color: var(--card);
        background-image: var(--kp-brush);
        background-size: 2px 2px;
        image-rendering: pixelated;
        border-radius: 0;
    }

    [data-theme='retro'] .kp-spinner {
        border-color: var(--border);
        border-top-color: var(--primary);
    }

    [data-theme='retro'] .kp-error {
        font-family: var(--kp-dos);
        font-size: 1rem;
        color: var(--destructive);
    }

    /* ── Text shapes: identifiers in the DOS face ──────────────────────── */

    [data-theme='retro'] .kp-id,
    [data-theme='retro'] .kp-url,
    [data-theme='retro'] .kp-numeric,
    [data-theme='retro'] .kp-timestamp,
    [data-theme='retro'] .kp-masked,
    [data-theme='retro'] .kp-copyable,
    [data-theme='retro'] .kp-truncate,
    [data-theme='retro'] .kp-cell-break,
    [data-theme='retro'] .kp-cell-truncate {
        font-family: var(--kp-dos);
        font-size: 1.05em;
        letter-spacing: 0.02em;
    }

    [data-theme='retro'] .kp-copyable__button {
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-raised);
    }

    /* The copy button's two states win over this register's own button
       rules [gap-12]: those paint in kp.register, which beats the states
       in kp.components, so copied lost its success plate and a refused
       copy looked idle. Restated token for token. */
    [data-theme='retro'] .kp-copyable .kp-copyable__button[data-kp-copied] {
        border-color: var(--success);
        color: var(--success-foreground);
        background: var(--success);
    }

    [data-theme='retro'] .kp-copyable .kp-copyable__button[data-kp-copy-failed] {
        border-color: var(--destructive);
        border-style: dashed;
        color: var(--destructive);
    }

    /* ── Data: Explorer's column headers are buttons ───────────────────── */

    [data-theme='retro'] .kp-table {
        border-collapse: separate;
        border-spacing: 0;
        background: var(--popover);
    }

    [data-theme='retro'] .kp-table th {
        background: var(--card);
        /* The reach above a sticky header paints this ground too [fix-32]. */
        --kp-datatable-head-ground: var(--card);
        border: 1px solid var(--border-strong);
        box-shadow: var(--kp-raised);
        font-weight: 600;
    }

    /* A sticky header keeps its raised edge and, while its box is scrolled,
 * the reach above it [fix-32, scope-90]; at rest the raised edge alone. */
    [data-theme='retro'] .kp-datatable[data-kp-max-height][data-kp-scrolled] .kp-table thead th {
        box-shadow: var(--kp-raised), var(--kp-datatable-head-reach);
    }

    [data-theme='retro'] .kp-table td {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='retro'] .kp-table tbody tr:hover {
        background: var(--card);
    }

    [data-theme='retro'] .kp-datatable {
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-sunken);
        background: var(--popover);
    }

    [data-theme='retro'] .kp-datatable__bar {
        background: var(--background);
        border-bottom: 1px solid var(--border);
    }

    [data-theme='retro'] .kp-datatable__sort[aria-sort] {
        color: var(--primary);
    }

    [data-theme='retro'] .kp-datatable__status,
    [data-theme='retro'] .kp-datatable__page {
        font-family: var(--kp-dos);
        font-size: 1rem;
    }

    [data-theme='retro'] .kp-diff {
        background: var(--popover);
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-sunken);
    }

    [data-theme='retro'] .kp-diff__line {
        font-family: var(--kp-dos);
        font-size: 1.05em;
    }

    [data-theme='retro'] .kp-timeline {
        border-inline-start: 2px groove var(--border);
    }

    [data-theme='retro'] .kp-timeline__marker {
        background: var(--primary);
        border-radius: 0;
        box-shadow: var(--kp-raised-navy);
    }

    [data-theme='retro'] .kp-timeline__when {
        font-family: var(--kp-dos);
        font-size: 1rem;
        color: var(--muted-foreground);
    }

    [data-theme='retro'] .kp-tree {
        font-family: var(--kp-dos);
        font-size: 1.05rem;
    }

    /* The accordion [gap-12]: the plain system weight of its category toggle, bold once open. */
    [data-theme='retro'] .kp-accordion__summary {
        font-weight: 500;
    }

    [data-theme='retro'] .kp-accordion__summary::marker {
        color: var(--foreground);
    }

    [data-theme='retro'] .kp-accordion__item[open] > .kp-accordion__summary {
        font-weight: 700;
    }

    [data-theme='retro'] .kp-reorder {
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-sunken);
        background: var(--popover);
    }

    /* ── Navigation and steps: the tab that lifts ──────────────────────── */

    /* 98.css's measured rule: the selected tab lifts two pixels and
       overhangs its neighbours by three. */
    [data-theme='retro'] .kp-tab {
        background: var(--background);
        color: var(--muted-foreground);
        border: 1px solid var(--border-strong);
        border-bottom: 0;
        border-radius: 0;
        box-shadow:
            inset 1px 1px 0 var(--popover),
            inset -1px 0 0 var(--border);
        padding-inline: 0.75rem;
    }

    [data-theme='retro'] .kp-tab[aria-selected='true'] {
        color: var(--foreground);
        font-weight: 600;
        margin-block-start: -2px;
        margin-inline-start: -3px;
        padding-inline: calc(0.75rem + 3px);
        position: relative;
        z-index: 2;
        background: var(--background);
    }

    [data-theme='retro'] .kp-tabs__list {
        border-bottom: 1px solid var(--border-strong);
        padding-inline-start: 0.4rem;
    }

    [data-theme='retro'] .kp-breadcrumb,
