        --kp-rp-block: calc(0.5rem * var(--kp-progressbar-scale, 1));
        --kp-rp-gap: calc(2px * var(--kp-progressbar-scale, 1));
        /* One dither cell of the indeterminate checker. */
        --kp-rp-dot: calc(2px * var(--kp-progressbar-scale, 1));
        --kp-rp-pitch: calc(var(--kp-rp-block) + var(--kp-rp-gap));
