        box-shadow: 0 -1px 4px hsl(from var(--accent) h s l / 0.6);
    }

    [data-theme='synthwave'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        --kp-sig-dur: 2600ms;
        position: relative;
        overflow: hidden;
        block-size: 0.9rem;
        border-radius: 2px;
        background:
            var(--kp-stripe) left bottom / 100% 2px no-repeat,
            var(--card);
        animation: none;
    }

    [data-theme='synthwave']
        .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)
        + .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        margin-block-start: 0.55rem;
    }

    [data-theme='synthwave'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)::after {
        content: '';
        position: absolute;
        inset-block: 0 2px;
        inset-inline-start: 0;
        inline-size: 40%;
        background: linear-gradient(90deg, transparent, hsl(from var(--primary) h s l / 0.22), transparent);
        transform: translateX(-100%);
    }

    [data-theme='synthwave'] .kp-switch {
        --kp-switch-radius: 2px;
        --kp-switch-thumb-radius: 1px;
    }

    [data-theme='synthwave'] .kp-switch__input {
        border: 1px solid var(--border-strong);
        background: var(--card);
    }

    [data-theme='synthwave'] .kp-switch__input::before {
        background: var(--muted-foreground);
    }

    [data-theme='synthwave'] .kp-switch__input:checked {
        border-color: var(--primary);
        background: linear-gradient(to right, hsl(from var(--primary) h s l / 0.55), hsl(from var(--accent) h s l / 0.55)), var(--card);
    }

    [data-theme='synthwave'] .kp-switch__input:checked::before {
        inset-inline-start: var(--kp-switch-inset, 0.125rem);
        background: var(--kp-core);
        box-shadow: var(--kp-tube-pink);
        transform: translateX(calc(var(--kp-switch-width, 2.5rem) - var(--kp-switch-height, 1.5rem)));
    }

    [data-theme='synthwave'] .kp-field__check {
        /* The tube strikes on in hard steps [G1: light switches]: three beats. */
        --kp-sig-dur: calc(3 * var(--kp-sw-beat));
        appearance: none;
        display: inline-grid;
        place-content: center;
        inline-size: 1.15rem;
        block-size: 1.15rem;
