        border-block-end: 2px solid var(--primary-foreground);
        transform: translateY(-1px) rotate(-45deg);
    }

    [data-theme='synthwave'] .kp-field__check[type='radio'] {
        border-radius: 50%;
    }

    [data-theme='synthwave'] .kp-field__check[type='radio']:checked {
        border-color: var(--primary);
    }

    [data-theme='synthwave'] .kp-field__check[type='radio']:checked::before {
        content: '';
        inline-size: 0.45rem;
        block-size: 0.45rem;
