    }

    [data-theme='synthwave']
        a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a):hover {
        background-size: 100% 3px;
        text-shadow: var(--kp-tube-pink);
    }

    @media (forced-colors: active) {
        [data-theme='synthwave'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a) {
