    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above are what they get. The
       durations are literal because check-motion.mjs computes DI5's rate
       from them; the matching --kp-* knobs are what js/effects.js reads. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='phantom'] [data-kp-reveal='headline'].is-words [data-word] {
            animation: kp-shout 620ms cubic-bezier(0.22, 1, 0.36, 1) both;
            animation-delay: calc(var(--kp-i, 0) * var(--kp-word-stagger));
        }

        [data-theme='phantom'] [data-kp-reveal='rule']::after {
            transition: background-position var(--kp-rail) linear;
        }

        [data-theme='phantom'] mark::before {
            transition: transform var(--kp-plate) var(--kp-cut);
        }

        /* The rectangle under the plate switches on after the slide, in no
           time at all: a size, not a colour, so KT8's mid-transition colour
           can never be read. */
        [data-theme='phantom'] mark {
            transition: background-size 0s linear var(--kp-plate);
        }

        [data-theme='phantom'] .kp-card[data-kp-reveal='emphasis'] mark::after {
            transition: transform var(--kp-wipe) var(--kp-cut);
        }

        [data-theme='phantom'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2)::after {
            transition-delay: var(--kp-redact-stagger);
        }

        [data-theme='phantom'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3)::after {
            transition-delay: calc(2 * var(--kp-redact-stagger));
        }

        [data-theme='phantom'] [data-kp-surface='hero']::after {
            transition: transform 900ms var(--kp-shove);
        }

        /* Width and transform only — no colour transition: a theme applied
           after first paint transitions every colour, and CI's chromium read
           a nav link halfway (KT8; flake named, rule 8a). */
        [data-theme='phantom'] .kp-nav__link::before,
        [data-theme='phantom'] .kp-nav__menu a::before,
        [data-theme='phantom'] .kp-footer a::before,
        [data-theme='phantom'] .kp-tab::before,
        [data-theme='phantom'] .kp-button::after {
            transition: width var(--fx-duration) var(--kp-cut);
        }

        [data-theme='phantom'] .kp-nav__link--cta,
        [data-theme='phantom'] .kp-button {
            transition: transform var(--fx-duration) var(--kp-cut);
        }

        /* The film cut: three steps, one monotonic change of opacity and
           saturation together. */
        [data-theme='phantom'] .kp-nav__menu {
            transition:
                opacity 180ms steps(3, end),
                translate 180ms steps(3, end),
                filter 180ms steps(3, end);
        }

        [data-theme='phantom'] .kp-toast {
            animation: kp-cut-in 180ms steps(3, end) 1;
        }

        [data-theme='phantom'] .kp-boot::before {
            animation: kp-bar-run 900ms var(--kp-out) both;
        }

        [data-theme='phantom'] .kp-boot.is-off {
            animation: kp-load-out 640ms var(--kp-shove) 1 forwards;
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* Every keyframe here has its row in TIMINGS (js/effects.js). */
    @keyframes kp-shout {
        0% {
            opacity: 0;
            transform: translateY(0.28em) skewX(-14deg);
        }

        100% {
            opacity: 1;
            transform: none;
        }
    }

    @keyframes kp-cut-in {
        0% {
            opacity: 0;
            filter: saturate(0) contrast(1.7);
        }

        60% {
            opacity: 0.6;
            filter: saturate(0.6) contrast(1.25);
        }

        100% {
            opacity: 1;
            filter: none;
        }
    }

    @keyframes kp-bar-run {
        from {
            transform: translateY(-50%) scaleX(0);
        }

        to {
            transform: translateY(-50%) scaleX(1);
        }
    }

    @keyframes kp-load-out {
        0% {
            transform: none;
        }

        50% {
            transform: skew(-20deg);
        }

        100% {
            transform: skew(-20deg) translateX(-115vw);
        }
    }

    /* The card's file code, in the red the plates wear [S49, A3]. */
    [data-theme='phantom'] .kp-nav__brand-tag {
        color: var(--primary);
        font-style: normal;
        letter-spacing: 0.2em;
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — the whole band a degree off square, inverted, in caps. */
    [data-theme='phantom'] .kp-marquee {
        background: var(--foreground);
        color: var(--background);
        transform: skewY(-1deg);
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: 0.06em;
        --kp-marquee: 22000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    /* A mega menu's group headings speak in the caption's voice [scope-48]. */
    [data-theme='phantom'] .kp-nav__menu[data-kp-menu-label]::before,
    [data-theme='phantom'] .kp-nav__menu--wide .kp-nav__menu-heading {
        background: var(--primary);
        color: var(--primary-foreground);
        transform: skewX(-8deg);
        border-block-end: 0;
    }

    /* ── The side navigation [feat-nav-3] ────────────────────────────
       The bar grows a plate out from behind the current item. Down the
       side it does the same thing sideways: the plate slides out of the
       edge the panel is attached to. */
    [data-theme='phantom'] .kp-sidenav {
        --kp-sidenav-surface: var(--card);
    }

    [data-theme='phantom'] .kp-sidenav__link,
    [data-theme='phantom'] .kp-sidenav__category-toggle {
        position: relative;
        z-index: 0;
        padding-inline: 0.95rem;
    }

    [data-theme='phantom'] .kp-sidenav__link::before {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        inline-size: 0;
        z-index: -1;
        background: var(--primary);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='phantom'] .kp-sidenav__link::before {
            transition: inline-size var(--fx-duration, 150ms) var(--fx-ease, ease);
        }
    }

    [data-theme='phantom'] .kp-sidenav__link:hover::before {
        inline-size: 0.35rem;
    }

    [data-theme='phantom'] .kp-sidenav__link[aria-current='page'] {
        color: var(--primary-foreground);
        background: none;
    }

    [data-theme='phantom'] .kp-sidenav__link[aria-current='page']::before {
        inline-size: 100%;
    }

    /* ── Back to top, and a picture [feat-page-1, feat-media-1] ──────
       The plate that slides out from behind things, held still: the frame
       is offset from its own shadow rather than bordered. */
    [data-theme='phantom'] .kp-to-top {
        box-shadow: 0.25rem 0.25rem 0 hsl(from var(--primary) h s l / 0.5);
    }

    [data-theme='phantom'] .kp-media {
        border: 1px solid var(--border-strong);
        box-shadow: 0.4rem 0.4rem 0 hsl(from var(--primary) h s l / 0.3);
    }

    [data-theme='phantom'] .kp-media-figure > figcaption {
        letter-spacing: 0.08em;
    }

    /* The figure carries the caption's voice, so the decision sits with
       the picture rather than with the words under it. */
    [data-theme='phantom'] .kp-media-figure {
        color: var(--muted-foreground);
    }

    /* ── The pressed state the register had been cancelling [fix-12] ───
       A layer beats a state: this register's hover background sits in
       kp.register, later than the kp.components rule that says what the
       button looks like while it is held down, so pressing it changed
       nothing. The base layer's own values, put back token for token. */

    [data-theme='phantom'] .kp-button--primary:active:not(:disabled) {
        background: var(--primary-active);
        border-color: var(--primary-active);
    }

    /* The primary's press [scope-80]. Every other variant is shoved 3px
       down and right when pressed; the primary already takes that shove on
       hover, so pressing it moved nothing (measured: `matrix(1, 0, 0, 1, 3,
       3)` hovered and pressed alike) — Kenny's "the primary needs an
       animation like the others when I click it". Pressed, it travels the
       rest of the way onto its own shadow: 5px, the shadow's full offset,
       with the shadow gone under it. */
    [data-theme='phantom'] .kp-button--primary:active:not(:disabled) {
        transform: translate(5px, 5px);
        filter: drop-shadow(0 0 0 var(--kp-red-deep));
    }

    /* ── Read-only fields [gap-11] ────────────────────────────────────── */

    /* A read-only field is a value on a record, not a box to type in. This
       register sets the field's border and ground in kp.register, which
       beats the read-only look in kp.components, so read-only painted like
       an editable field. The state is answered here, on top of the rest
       look, which stays as it was. */
    [data-theme='phantom'] .kp-field__input[readonly] {
        border-style: dashed;
        background-color: var(--muted);
    }

    /* ── The palette's trigger in the bar [scope-48, scope-80] ─────────── */

    /* In the voice of this register's own nav links (Kenny, 2026-09-14,
       search-voice "Per thema"): tall condensed display capitals in the full
       ink, and under the pointer the skewed red slash that sweeps in behind
       them. The link's typeface, case, spacing, shape and pointer answer are
       restated here, because the trigger is a button beside the list rather
       than a link in it. The underline a plain link carries is not: it says
       "this is a link", and the trigger is not one. */
    [data-theme='phantom'] .kp-nav__search .kp-nav__search-trigger {
        position: relative;
        z-index: 0;
        padding-inline: 0.95rem;
        font-family: var(--theme-font-display);
        font-weight: 700;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        border: 0;
        border-radius: 0;
        background: none;
        color: var(--foreground);
    }

    [data-theme='phantom'] .kp-nav__search .kp-nav__search-trigger:hover,
    [data-theme='phantom'] .kp-nav__search .kp-nav__search-trigger:focus-visible {
        color: var(--primary-foreground);
        background: none;
        box-shadow: none;
    }

    [data-theme='phantom'] .kp-nav__search .kp-nav__search-trigger::before {
        content: '';
        position: absolute;
        left: -4%;
        top: 14%;
        height: 72%;
        width: 0;
        background: var(--primary);
        transform: skewX(-16deg);
        z-index: -1;
    }

    [data-theme='phantom'] .kp-nav__search .kp-nav__search-trigger:hover::before,
    [data-theme='phantom'] .kp-nav__search .kp-nav__search-trigger:focus-visible::before {
        width: 108%;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='phantom'] .kp-nav__search .kp-nav__search-trigger::before {
            transition: width var(--fx-duration) var(--kp-cut);
        }
    }

    /* ── The alarm [scope-94] ──────────────────────────────────────────────
       A calling card: red, black and white only, the headline tilted, white bars and a white frame. Every colour is one of this theme's tokens. The
       button keeps this register's shape and takes the alarm's paint, on
       selectors long enough to outrank this register's own button states;
       the dialog takes no focus ring, because in the auto mode the whole
       screen is what has focus. */
    [data-theme='phantom'] .kp-alarm {
        --kp-alarm-ground: hsl(from var(--background) h s 3% / 0.96);
        --kp-alarm-ink: var(--destructive);
        --kp-alarm-soft: var(--foreground);
        --kp-alarm-split: var(--foreground);
        --kp-alarm-on-ink: var(--background);
        --kp-alarm-glow: hsl(from var(--destructive) h s l / 0.5);
        --kp-alarm-halo: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-scan: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-vignette: hsl(from var(--background) h s 1% / 0.8);
        --kp-alarm-stripe: var(--foreground);
        --kp-alarm-frame: 3px solid var(--foreground);
        --kp-alarm-title-tracking: 0;
    }

    [data-theme='phantom'] .kp-alarm:focus-visible {
        outline: none;
    }

    [data-theme='phantom'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack,
    [data-theme='phantom'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:hover:not(:disabled),
    [data-theme='phantom'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:active:not(:disabled) {
        border-color: var(--kp-alarm-ink);
        background: var(--kp-alarm-ink);
        color: var(--kp-alarm-on-ink);
        text-shadow: none;
    }

    [data-theme='phantom'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:is(:hover, :focus-visible):not(:disabled):not(:active) {
        background: var(--kp-alarm-on-ink);
        color: var(--kp-alarm-ink);
    }

    [data-theme='phantom'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep,
    [data-theme='phantom'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep:is(:hover, :focus-visible):not(:disabled) {
        border-color: currentColor;
        background: transparent;
        color: inherit;
        text-shadow: none;
    }

    [data-theme='phantom'] .kp-alarm__title {
        rotate: -3deg;
    }

    [data-theme='phantom'] .kp-alarm .kp-button.kp-alarm__ack::before {
        border-color: var(--kp-alarm-soft);
        background: var(--kp-alarm-ink);
    }

    [data-theme='phantom'] .kp-alarm .kp-button.kp-alarm__ack::after {
        background: var(--kp-alarm-soft);
    }

    /* A submenu item's mark [Kenny, 2026-09-20]: the block it marks its own alarms with. */
    [data-theme='phantom'] .kp-sidenav__submenu .kp-sidenav__link {
        --kp-sidenav-submenu-mark: '▮';
    }
}

/* ── Signature [scope-140] ─────────────────────────────────────────────── */
/* phantom's approved signature (Kenny, 2026-10-03, three review rounds): the
   progress bar and the ten elements (spinner, skeleton, switch, check and
   radio, toast, dialog, tooltip, wizard steps, empty state, link hover),
   ported once from research/progress-signature/themes/phantom.css and research/signature-elements/themes/phantom.css
   and maintained here from now on. In kp.signature, which css/themes.css
   orders after kp.register, so it draws over the register exactly as the
   approved demos did, whatever the weight of a register selector. */
@layer kp.signature {
    /* The link signature is for links in running text; a link in a navigation,
       a menu, a breadcrumb (a nav) or the footer keeps its own component's look
       (scope-93: no link colour in a navigation). */
    /* A shadow or outline the signature draws on a focusable control yields to
       the theme's focus ring while the control has focus (DI2). */
    [data-theme='phantom'] .kp-progressbar {
        --kp-progressbar-height: calc(1rem * var(--kp-progressbar-scale, 1));
        --kp-ps-slant: calc(0.375rem * var(--kp-progressbar-scale, 1));
        --kp-ps-shard: calc(0.3125rem * var(--kp-progressbar-scale, 1));
        --kp-ps-gap: calc(3px * var(--kp-progressbar-scale, 1));
        --kp-ps-dot: calc(5px * var(--kp-progressbar-scale, 1));
        --kp-ps-stripe: calc(6px * var(--kp-progressbar-scale, 1));
        --kp-ps-pitch: calc(13px * var(--kp-progressbar-scale, 1));
        --kp-ps-edge: calc(var(--kp-value) * (100% - var(--kp-ps-slant)));
        /* The cut's slant, full from the first two percent, none at zero, so an
           empty card shows no red at all. */
        --kp-ps-cut: calc(var(--kp-ps-slant) * min(1, var(--kp-value) * 50));
    }

    [data-theme='phantom'] .kp-progressbar__track {
        border-radius: 0;
        background: var(--border-strong);
        clip-path: polygon(var(--kp-ps-slant) 0, 100% 0, calc(100% - var(--kp-ps-slant)) 100%, 0 100%);
    }

    [data-theme='phantom'] .kp-progressbar__track::before {
        content: '';
        position: absolute;
        inset: 2px 2px 2px 2px;
        background:
            radial-gradient(
                    circle at center,
                    color-mix(in srgb, var(--foreground) 28%, transparent) calc(0.9px * var(--kp-progressbar-scale, 1)),
                    transparent calc(1px * var(--kp-progressbar-scale, 1))
                )
                0 0 / var(--kp-ps-dot) var(--kp-ps-dot),
            var(--background);
        clip-path: polygon(calc(var(--kp-ps-slant) - 1px) 0, 100% 0, calc(100% - var(--kp-ps-slant) + 1px) 100%, 0 100%);
    }

    [data-theme='phantom'] .kp-progressbar__track::after {
        content: '';
        position: absolute;
        inset: 0;
        z-index: 1;
        background: var(--kp-red-deep, var(--sidebar-background));
        clip-path: polygon(
            0 0,
            calc(var(--kp-ps-edge) + var(--kp-ps-cut) + var(--kp-ps-gap) * min(1, var(--kp-value) * 50)) 0,
            calc(var(--kp-ps-edge) + var(--kp-ps-gap) * min(1, var(--kp-value) * 50)) 100%,
            0 100%
        );
        transition: clip-path var(--fx-duration) var(--fx-ease);
    }

    [data-theme='phantom'] .kp-progressbar__fill {
        z-index: 2;
        clip-path: polygon(0 0, calc(var(--kp-ps-edge) + var(--kp-ps-cut)) 0, var(--kp-ps-edge) 100%, 0 100%);
        transition: clip-path var(--fx-duration) var(--fx-ease);
    }

    [data-theme='phantom'] .kp-progressbar__head {
        z-index: 3;
        inline-size: calc(var(--kp-ps-slant) + var(--kp-ps-shard));
        background: var(--foreground);
        clip-path: polygon(var(--kp-ps-slant) 0, 100% 0, var(--kp-ps-shard) 100%, 0 100%);
        transform: translateX(calc(var(--kp-value) * (100cqi - var(--kp-ps-slant)) + var(--kp-ps-gap) * 2 + 1px));
        transition: transform var(--fx-duration) var(--fx-ease);
    }

    [data-theme='phantom'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__track::after {
        display: none;
    }

    [data-theme='phantom'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
        inline-size: 34%;
        clip-path: polygon(var(--kp-ps-slant) 0, 100% 0, calc(100% - var(--kp-ps-slant)) 100%, 0 100%);
        box-shadow: none;
        animation: kp-progressbar-phantom-shove 1500ms var(--kp-shove, cubic-bezier(0.81, -0.01, 0, 1)) infinite;
    }

    @media (prefers-reduced-motion: reduce) {
        [data-theme='phantom'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
            inset-inline: 0;
            inline-size: auto;
            animation: none;
            transform: none;
            clip-path: none;
            background: repeating-linear-gradient(-69deg, var(--primary) 0 var(--kp-ps-stripe), transparent var(--kp-ps-stripe) var(--kp-ps-pitch));
        }
    }

    [data-theme='phantom'] {
        --kp-sig-ph-plate: var(--sidebar-background, var(--primary));
        --kp-sig-ph-cut: polygon(0 6%, 100% 0, 96% 100%, 3% 92%);
    }

    [data-theme='phantom'] .kp-spinner {
        --kp-sig-dur: 1200ms;
        position: relative;
        border: 0;
        border-radius: 0;
        background: none;
        animation: none;
    }

    [data-theme='phantom'] .kp-spinner::before,
    [data-theme='phantom'] .kp-spinner::after {
        content: '';
        position: absolute;
        inset: 0;
        clip-path: polygon(50% 0, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%);
    }

    [data-theme='phantom'] .kp-spinner::before {
        background: var(--primary);
        translate: 2px 2px;
    }

    [data-theme='phantom'] .kp-spinner::after {
        background: var(--foreground);
    }

    [data-theme='phantom'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        --kp-sig-dur: 1400ms;
        position: relative;
        overflow: hidden;
        block-size: 0.95rem;
        border-radius: 0;
        background:
            radial-gradient(circle, hsl(from var(--foreground) h s l / 0.32) 1px, transparent 1.4px) 0 0 / 5px 5px,
            var(--muted);
        clip-path: var(--kp-sig-ph-cut);
        animation: none;
    }

    [data-theme='phantom'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) + .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        margin-block-start: 0.55rem;
    }

    [data-theme='phantom'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)::after {
        content: '';
        position: absolute;
        inset: 0;
        background: var(--primary);
        clip-path: polygon(0.8rem 0, 2.6rem 0, 1.8rem 100%, 0 100%);
        transform: translateX(-2.8rem);
    }

    [data-theme='phantom'] .kp-switch {
        --kp-switch-radius: 0;
        --kp-switch-thumb-radius: 0;
    }

    [data-theme='phantom'] .kp-switch__input {
        border: 2px solid var(--foreground);
        background: var(--background);
    }

    [data-theme='phantom'] .kp-switch__input::before {
        inset-block: 1px;
        inline-size: calc(var(--kp-switch-height, 1.5rem) - 2px);
        background: var(--muted-foreground);
        clip-path: polygon(22% 0, 100% 0, 78% 100%, 0 100%);
    }

    [data-theme='phantom'] .kp-switch__input:checked {
        border-color: var(--foreground);
        background: var(--primary);
    }

    [data-theme='phantom'] .kp-switch__input:checked::before {
        inset-inline-start: var(--kp-switch-inset, 0.125rem);
        background: var(--foreground);
        transform: translateX(calc(var(--kp-switch-width, 2.5rem) - var(--kp-switch-height, 1.5rem) - 2px));
    }

    [data-theme='phantom'] .kp-field__check {
        --kp-sig-dur: 300ms;
        appearance: none;
        position: relative;
        display: inline-grid;
        place-content: center;
        inline-size: 1.15rem;
        block-size: 1.15rem;
        /* Room for the slant: skewed, the box reaches about 1.3px past each side. */
        margin: 0 2px;
        border: 2px solid var(--foreground);
        border-radius: 0;
        background: var(--background);
        transform: skewX(var(--kp-skew, -8deg));
    }

    [data-theme='phantom'] .kp-field__check:not(:focus-visible) {
        box-shadow: 3px 3px 0 var(--kp-sig-ph-plate);
    }

    [data-theme='phantom'] .kp-field__check:checked {
        border-color: var(--foreground);
        background: var(--foreground);
    }

    [data-theme='phantom'] .kp-field__check:checked:not(:focus-visible) {
        box-shadow: 3px 3px 0 var(--kp-sig-ph-plate);
    }

    [data-theme='phantom'] .kp-field__check[type='checkbox']:checked::before {
        content: '';
        position: absolute;
        inset-block-start: -0.42rem;
        inset-inline-start: 0.02rem;
        inline-size: 1.25rem;
        block-size: 1.05rem;
        background: var(--primary);
        clip-path: polygon(0 52%, 22% 38%, 40% 66%, 82% 0, 100% 14%, 42% 100%);
        filter: drop-shadow(1px 1px 0 var(--primary-foreground));
        transform: skewX(calc(var(--kp-skew, -8deg) * -1));
    }

    [data-theme='phantom'] .kp-field__check[type='radio'] {
        border-radius: 50%;
        transform: none;
    }

    [data-theme='phantom'] .kp-field__check[type='radio']:checked::before {
        content: '';
        inline-size: 0.85rem;
        block-size: 0.85rem;
        background: var(--primary);
        clip-path: polygon(50% 0, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%);
    }

    [data-theme='phantom'] .kp-toast {
        --kp-sig-dur: 380ms;
        border: 2px solid var(--foreground);
        border-radius: 0;
        background: var(--background);
        color: var(--foreground);
        box-shadow: 6px 6px 0 var(--kp-sig-ph-plate);
    }

    [data-theme='phantom'] .kp-toast--success {
        border-color: var(--success-foreground);
        background: var(--success);
        color: var(--success-foreground);
        box-shadow: 6px 6px 0 hsl(from var(--success) h s calc(l + 16));
    }

    [data-theme='phantom'] .kp-toast--info {
        border-color: var(--info-foreground);
        background: var(--info);
        color: var(--info-foreground);
        box-shadow: 6px 6px 0 hsl(from var(--info) h s calc(l + 16));
    }

    [data-theme='phantom'] .kp-toast--warning {
        border-color: var(--warning-foreground);
        background: var(--warning);
        color: var(--warning-foreground);
        box-shadow: 6px 6px 0 hsl(from var(--warning) h s calc(l + 16));
    }

    [data-theme='phantom'] :is(.kp-toast--destructive, .kp-toast--error) {
        border-color: var(--foreground);
        background: var(--destructive);
        color: var(--destructive-foreground);
        box-shadow: 6px 6px 0 var(--kp-sig-ph-plate);
    }

    [data-theme='phantom'] .kp-toast__body {
        font-family: var(--theme-font-display);
        font-size: 1.05rem;
        font-style: italic;
        font-weight: 800;
        letter-spacing: 0.02em;
        text-transform: uppercase;
    }

    [data-theme='phantom'] .kp-dialog::backdrop {
        background:
            radial-gradient(circle, hsl(from var(--primary) h s l / 0.45) 1.4px, transparent 1.9px) 0 0 / 8px 8px,
            var(--background);
    }

    [data-theme='phantom'] .kp-dialog {
        --kp-sig-dur: 420ms;
        border: 3px solid var(--foreground);
        border-radius: 0;
        background: var(--background);
        box-shadow: 10px 10px 0 var(--kp-sig-ph-plate);
        rotate: -1.5deg;
    }

    [data-theme='phantom'] .kp-dialog__title {
        /* The title at the package's metrics [scope-87]: Kenny chose the fixed size
           over the theme's own on 2026-10-03 (research/dialog-title). */
        font-family: var(--theme-font-display);
        font-style: italic;
        font-weight: 900;
        letter-spacing: 0.01em;
        text-transform: uppercase;
