    }

    [data-theme='terminal'] .kp-empty__title::after {
        content: '';
        display: inline-block;
        inline-size: 0.6em;
        block-size: 1.1em;
        margin-inline-start: 0.3ch;
        vertical-align: text-bottom;
        background: var(--primary);
        box-shadow: var(--kp-sig-tm-bloom);
    }

    [data-theme='terminal'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a) {
        text-decoration-style: dashed;
        text-decoration-thickness: 1px;
        text-underline-offset: 0.2em;
        -webkit-box-decoration-break: clone;
        box-decoration-break: clone;
    }

    [data-theme='terminal'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a):hover {
        box-shadow: 0 0 0 1px var(--ring);
        text-decoration-style: solid;
    }

    [data-theme='terminal']
        a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a):active {
        background: var(--primary);
        color: var(--primary-foreground);
        text-decoration-style: solid;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='terminal'] .kp-spinner::before {
            animation: kp-sig-terminal-tm-dot var(--kp-sig-dur) step-end infinite;
        }

        [data-theme='terminal'] .kp-spinner::after {
            animation:
                kp-sig-terminal-tm-trail var(--kp-sig-dur) step-end infinite,
                kp-sig-terminal-tm-decay calc(var(--kp-sig-dur) / 8) linear infinite;
        }

        [data-theme='terminal'] .kp-switch__input::before {
            transition: transform 200ms steps(4, jump-end);
        }

        [data-theme='terminal'] .kp-toast {
            animation: kp-sig-terminal-tm-type var(--kp-sig-dur) steps(20, jump-end) backwards;
        }

        [data-theme='terminal'] .kp-dialog {
            animation: kp-sig-terminal-tm-rows var(--kp-sig-dur) steps(6, jump-end) backwards;
        }

        [data-theme='terminal'] .kp-dialog::after {
            animation: kp-sig-terminal-tm-feed var(--kp-sig-dur) steps(6, jump-end) backwards;
        }

        [data-theme='terminal'] .kp-tooltip {
            animation: kp-sig-terminal-tm-type var(--kp-sig-dur) steps(12, jump-end) backwards;
        }

        [data-theme='terminal'] .kp-empty__title::after {
            animation: kp-sig-terminal-tm-blink 1000ms step-end 5;
        }
    }

    @keyframes kp-sig-terminal-tm-dot {
        0% {
            transform: translate(0%, 0%);
        }

        12.5% {
            transform: translate(100%, 0%);
        }

        25% {
            transform: translate(100%, 100%);
        }

        37.5% {
            transform: translate(100%, 200%);
        }

        50% {
            transform: translate(100%, 300%);
        }

        62.5% {
            transform: translate(0%, 300%);
        }

        75% {
            transform: translate(0%, 200%);
        }

        87.5% {
            transform: translate(0%, 100%);
        }

        100% {
            transform: translate(0%, 0%);
        }
    }

    @keyframes kp-sig-terminal-tm-trail {
        0% {
            transform: translate(0%, 100%);
        }

        12.5% {
            transform: translate(0%, 0%);
        }

        25% {
            transform: translate(100%, 0%);
        }

        37.5% {
            transform: translate(100%, 100%);
        }

        50% {
            transform: translate(100%, 200%);
        }

        62.5% {
            transform: translate(100%, 300%);
        }

        75% {
            transform: translate(0%, 300%);
        }

        87.5% {
            transform: translate(0%, 200%);
        }

        100% {
            transform: translate(0%, 100%);
        }
    }

    @keyframes kp-sig-terminal-tm-decay {
        from {
            opacity: 0.6;
        }

        to {
            opacity: 0.15;
        }
    }

    @keyframes kp-sig-terminal-tm-type {
        from {
            clip-path: inset(0 100% 0 0);
        }

        to {
            clip-path: inset(0);
        }
    }

    /* The first line is on the screen with its cursor, the rest are printed
       under it, one line a step. */
    @keyframes kp-sig-terminal-tm-rows {
        from {
            clip-path: inset(0 0 calc(100% - 1.25rem - 1.5em) 0);
        }

        to {
            clip-path: inset(0);
        }
    }

    @keyframes kp-sig-terminal-tm-feed {
        from {
            inset-block-start: 1.25rem;
            visibility: visible;
        }

        to {
            inset-block-start: calc(100% - 1.25rem - 1.2em);
            visibility: visible;
        }
    }

    @keyframes kp-sig-terminal-tm-blink {
        50% {
            opacity: 0;
        }
    }

    @keyframes kp-tp-caret {
        50% {
            opacity: 0;
        }
    }

    @keyframes kp-tp-walk {
        from {
            transform: translateX(0);
        }
        to {
            transform: translateX(calc(100cqi - 3ch));
        }
    }

    /* Leaving, this theme's way [scope-142; picked by Kenny on research/size-motion,
       2026-10-04]. js/motion.js marks what leaves `[data-kp-leaving]`, closes its space during
       the exit, and in a row of leaves starts the next one halfway through this one. */
    @media (prefers-reduced-motion: no-preference) {
        /* ── terminal: the block cursor glides back over the line, deleting it as it goes ── */
        /* Opening is closing turned around (Kenny's pick on research/open-reverse,
           2026-10-05): js/motion.js opens the dialog as its close played backwards,
           in the close's time, and lets what arrives play this leave backwards. */
        [data-theme='terminal'] {
            --kp-open: reverse-close;
        }

        /* One cell wide, the bloom of the phosphor in place of a glow; it runs
           from the part's end to its start in the writing direction (a page
           that reads right to left sweeps the other way). */
        [data-theme='terminal'] [data-kp-leaving] {
            position: relative;
            overflow: clip;
            animation: kp-sig-terminal-leave 480ms linear forwards;
        }

        [data-theme='terminal'] [data-kp-leaving]:dir(rtl) {
            animation-name: kp-sig-terminal-leave-rtl;
        }

        [data-theme='terminal'] [data-kp-leaving]::after {
            content: '';
            position: absolute;
            inset-block: 0;
            inset-inline-end: 0;
            inline-size: 1ch;
            pointer-events: none;
            z-index: 2;
            visibility: visible;
            background: var(--primary);
            box-shadow: var(--kp-bloom);
            animation: kp-sig-terminal-leave-2 480ms linear forwards;
        }

        @keyframes kp-sig-terminal-leave {
            from {
                clip-path: inset(0 0 0 0);
            }

            to {
                clip-path: inset(0 100% 0 0);
            }
        }

        @keyframes kp-sig-terminal-leave-rtl {
            from {
                clip-path: inset(0 0 0 0);
            }

            to {
                clip-path: inset(0 0 0 100%);
            }
        }

        @keyframes kp-sig-terminal-leave-2 {
            from {
                inset-inline-end: 0;
            }

            to {
                inset-inline-end: calc(100% - 1ch);
            }
        }
    }

    /* ── The meter with a mark, this theme's way [picked by Kenny on
       research/character-meter, round 3, 2026-10-05: shape 1, while
       loading 3, how the share arrives 3, when the tone changes 2,
       the mark past the end 2]. The package's own markup and states
       (setMeter(), js/kpi.js): the track on the meter, the share on ::before,
       the sign past the end or the loading picture on ::after, the mark
       `.kp-meter__mark`. Every animation and transition under
       prefers-reduced-motion: no-preference; still frames otherwise. ── */

    /* The shared part: room past the end, loading without the pulse, the mark
       centred on its width, the package's signs cleared for the shape's own.
       Under :where() so each picked rule below wins as it did in the demo. */
    :where([data-theme='terminal']) :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-room: 0.625rem;
        box-sizing: border-box;
    }

    :where([data-theme='terminal']) .kp-meter--inline {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-sig-meter-room));
    }

    /* Each character draws its own loading picture instead of the pulse. */
    :where([data-theme='terminal']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: clip;
        animation: none;
    }

    :where([data-theme='terminal']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    /* The mark is centred on its share, whatever its width. */
    :where([data-theme='terminal']) .kp-meter__mark {
        --kp-sig-meter-mw: 2px;
        box-sizing: border-box;
        inline-size: var(--kp-sig-meter-mw);
        inset-inline-start: calc(clamp(0, var(--kp-mark, 0), 1) * 100% - var(--kp-sig-meter-mw) / 2);
    }

    :where([data-theme='terminal']) .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - 0.75rem);
    }

    /* The sign past the end, cleared of the package's ▸ for each character
       to draw its own. */
    :where([data-theme='terminal']) :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '';
        position: absolute;
        inset: auto;
        translate: none;
        color: inherit;
        font-size: 0.75rem;
        line-height: 1;
        text-shadow: none;
        white-space: nowrap;
        pointer-events: none;
    }

    /* A mark past the end keeps the package's sign inside the bar's end, in
       each character's own glyph and ink. */
    :where([data-theme='terminal']) .kp-meter__mark[data-kp-over]::after {
        content: var(--kp-sig-meter-mo-sign, '▸');
        color: var(--kp-sig-meter-mo-ink, var(--foreground));
        font-family: var(--kp-sig-meter-mo-font, inherit);
        text-shadow:
            0 0 1px var(--kp-sig-meter-mo-halo, var(--card)),
            0 0 2px var(--kp-sig-meter-mo-halo, var(--card));
    }

    /* ── shape: option 1 ── */

    /* ── terminal · the htop meter ────────────────────────────────── */

    /* [||||||||        ]: square brackets in the dim phosphor, a dot in
       every empty cell; the run between them is the scale. */
    [data-theme='terminal'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-meter-height: 0.75rem;
        --kp-sig-meter-room: 0.75rem;
        --kp-sig-meter-cell: 0.375rem;
        --kp-sig-meter-mo-ink: var(--accent);
        --kp-sig-meter-mo-halo: var(--background);
        --kp-sig-meter-bracket: var(--muted-foreground);
        border-radius: 0;
        background:
            linear-gradient(var(--kp-sig-meter-bracket), var(--kp-sig-meter-bracket)) 0 0 / 1px 100% no-repeat,
            linear-gradient(var(--kp-sig-meter-bracket), var(--kp-sig-meter-bracket)) 0 0 / 3px 1px no-repeat,
            linear-gradient(var(--kp-sig-meter-bracket), var(--kp-sig-meter-bracket)) 0 100% / 3px 1px no-repeat,
            linear-gradient(var(--kp-sig-meter-bracket), var(--kp-sig-meter-bracket)) 100% 0 / 1px 100% no-repeat,
            linear-gradient(var(--kp-sig-meter-bracket), var(--kp-sig-meter-bracket)) 100% 0 / 3px 1px no-repeat,
            linear-gradient(var(--kp-sig-meter-bracket), var(--kp-sig-meter-bracket)) 100% 100% / 3px 1px no-repeat,
            radial-gradient(circle, hsl(from var(--muted-foreground) h s l / 0.5) 0 0.6px, transparent 1px) 3px 50% / var(--kp-sig-meter-cell) 100%
                repeat-x;
    }

    /* One phosphor bar per character cell, no glow: the bloom is for the
       cursor and bright text only (G5). */
    [data-theme='terminal'] :is(.kp-meter, .kp-kpi__meter)::before {
        inset-block: 2px;
        inset-inline-start: 3px;
        inline-size: calc(clamp(0, var(--kp-value, 0), 1) * (100% - 6px));
        border-radius: 0;
        background: linear-gradient(90deg, var(--kp-meter-fill-colour) 0 2px, transparent 2px) calc(var(--kp-sig-meter-cell) / 2 - 1px) 0 /
            var(--kp-sig-meter-cell) 100% repeat-x;
    }

    /* The block caret in the cell the mark stands in. It stands lit: nothing
       blinks at rest, only what waits (G16). */
    [data-theme='terminal'] .kp-meter__mark {
        --kp-sig-meter-mw: 0.375rem;
        inset-block: 0;
        inset-inline-start: calc(3px + clamp(0, var(--kp-mark, 0), 1) * (100% - 6px) - var(--kp-sig-meter-mw) / 2);
        border-radius: 0;
        background: var(--accent);
        box-shadow: 0 0 0 1px var(--background);
    }

    [data-theme='terminal'] .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - 0.75rem);
    }

    [data-theme='terminal'] :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '+';
        inset-inline-start: calc(100% + 3px);
        inset-block-start: 50%;
        translate: 0 -50%;
        color: var(--accent);
        font: 700 1rem/1 var(--theme-font-mono, monospace);
    }

    /* ── while loading: an htop row, the cursor its head ──────────────────
       The meter is the row already: its brackets and dim cells stand, the
       cells light in the ink one a step from the start, and the lit cell at
       the head is the block cursor, blinking on the slow clock; where it
       loops it empties the way it filled. round() makes the step one cell
       whatever the meter's width. */

    [data-theme='terminal'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        animation: none;
    }

    [data-theme='terminal'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::before {
        display: block;
        inline-size: calc(100% - 6px);
        background: linear-gradient(90deg, var(--foreground) 0 2px, transparent 2px) calc(var(--kp-sig-meter-cell) / 2 - 1px) 0 /
            var(--kp-sig-meter-cell) 100% repeat-x;
        clip-path: inset(0 calc(100% - round(down, var(--kp-sig-tm-k) * 100%, var(--kp-sig-meter-cell))) 0 0);
        transition: none;
    }

    [data-theme='terminal'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        all: unset;
        content: '';
        position: absolute;
        inset-block: 2px;
        inset-inline-start: calc(4px + max(0px, round(down, var(--kp-sig-tm-k) * (100% - 6px), var(--kp-sig-meter-cell)) - var(--kp-sig-meter-cell)));
        inline-size: calc(var(--kp-sig-meter-cell) - 2px);
        background: var(--primary);
        opacity: var(--kp-sig-tm-head);
        pointer-events: none;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='terminal'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::before,
        [data-theme='terminal'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
            animation:
                kp-sig-terminal-tm-fill var(--kp-sig-tm-slow) linear infinite alternate,
                kp-sig-terminal-tm-head var(--kp-sig-tm-slow) steps(1, jump-end) infinite;
        }
    }

    /* ── how the share arrives: typed out, the cursor at its head ──────────
       The share is written from its start, a cell a step (32 cells take
       1088 ms; a longer one sends its cells faster, so it too lands in
       1088 ms), the block cursor on the cell being written; it goes when
       the line lands. A value that changes is typed to its new width. */

    [data-theme='terminal'] :is(.kp-meter, .kp-kpi__meter):not([data-kp-loading], [data-kp-over])::after {
        content: '';
        position: absolute;
        inset-block: 2px;
        inset-inline-start: calc(
            4px +
                min(
                    clamp(0, var(--kp-value, 0), 1) * (100% - 6px),
                    round(down, var(--kp-sig-tm-k) * clamp(0, var(--kp-value, 0), 1) * (100% - 6px), var(--kp-sig-meter-cell)) +
                        var(--kp-sig-meter-cell)
                ) -
                var(--kp-sig-meter-cell)
        );
        inline-size: calc(var(--kp-sig-meter-cell) - 2px);
        background: var(--primary);
        box-shadow: var(--kp-bloom);
        visibility: hidden;
        pointer-events: none;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='terminal'] :is(.kp-meter, .kp-kpi__meter):not([data-kp-loading])::before {
            clip-path: inset(
                0 calc(100% - min(100%, round(down, var(--kp-sig-tm-k) * 100%, var(--kp-sig-meter-cell)) + var(--kp-sig-meter-cell))) 0 0
            );
            animation: kp-sig-terminal-tm-k calc(32 * var(--kp-sig-tm-cell)) linear backwards;
            transition: inline-size calc(32 * var(--kp-sig-tm-cell)) steps(32);
        }

        [data-theme='terminal'] :is(.kp-meter, .kp-kpi__meter):not([data-kp-loading], [data-kp-over])::after {
            animation: kp-sig-terminal-tm-k calc(32 * var(--kp-sig-tm-cell)) linear backwards;
        }
    }

    /* ── when the tone changes: the share blinks three times ───────────────
       A change blinks (G9), between the bright phosphor and the dim; the
       meter's own cells stay put. A new tone is a new name, so it plays
       again; going back to no tone plays nothing. */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='terminal'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='warning']:not([data-kp-loading])::before {
            animation:
                kp-sig-terminal-tm-k calc(32 * var(--kp-sig-tm-cell)) linear backwards,
                kp-sig-terminal-meter-tone-w var(--kp-sig-tm-change) steps(1, jump-end);
        }

        [data-theme='terminal'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='destructive']:not([data-kp-loading])::before {
            animation:
                kp-sig-terminal-tm-k calc(32 * var(--kp-sig-tm-cell)) linear backwards,
                kp-sig-terminal-meter-tone-d var(--kp-sig-tm-change) steps(1, jump-end);
        }
    }

    /* ── the mark past the end: option 2 ── */

    [data-theme='terminal'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-mo-sign: '>';
    }

    [data-theme='terminal'] .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% + 3px);
    }

    [data-theme='terminal'] .kp-meter__mark[data-kp-over]::after {
        inset-inline-start: calc(100% + 2px);
    }

    /* The mark moves a cell a step: eight cells in 272 ms. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='terminal'] .kp-meter__mark {
            transition: inset-inline-start calc(8 * var(--kp-sig-tm-cell)) steps(8, jump-end);
        }
    }

    /* ── Loading is an htop row [G10; Kenny, 2026-10-07 on research/terminal-
       character: "an htop row, the cursor its head"]. Wherever a part waits
       and has room for a row, one row stands where its reading will be
       written: a square bracket at each end and the cells between them, dim;
       the cells light in the ink one a step from the start and the cell at
       the head is the block cursor, blinking on the slow clock; where it
       loops (1000 ms) it empties the way it filled, a cell a step. The
       spinner (the braille cell) and the busy bar (`<=>`) are approved and
       stay; a waiting button, with no room for a row, shows the cursor alone.
       Standing still, the row is full and the cursor lit. ── */

    [data-theme='terminal'] {
        --kp-sig-tm-w: 16;
        --kp-sig-tm-row: 0.9rem;
    }

    [data-theme='terminal'] :is(.kp-skeleton, .kp-datatable__busy-panel, .kp-calendar--busy-whole > .kp-calendar__busy) {
        position: relative;
    }

    [data-theme='terminal']
        :is(
            .kp-skeleton,
            .kp-datatable__busy-panel,
            .kp-calendar--busy-whole > .kp-calendar__busy,
            .kp-card[aria-busy='true']:not(:has(.kp-skeleton), [data-kp-label]),
            .kp-kpi[aria-busy='true']:not(:has(.kp-skeleton))
        )::before,
    [data-theme='terminal'] .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading]::after {
        content: '';
        box-sizing: border-box;
        inline-size: calc(var(--kp-sig-tm-w) * 1ch + 8px);
        max-inline-size: 100%;
        pointer-events: none;
        background:
            linear-gradient(var(--primary), var(--primary))
                calc(4px + max(0px, round(down, var(--kp-sig-tm-k) * var(--kp-sig-tm-w) * 1ch, 1ch) - 1ch)) 3px /
                calc(var(--kp-sig-tm-head) * (1ch - 2px)) calc(100% - 6px) no-repeat,
            repeating-linear-gradient(90deg, var(--foreground) 0 calc(1ch - 2px), transparent calc(1ch - 2px) 1ch) 4px 3px /
                round(down, var(--kp-sig-tm-k) * var(--kp-sig-tm-w) * 1ch, 1ch) calc(100% - 6px) no-repeat,
            repeating-linear-gradient(90deg, var(--border-strong) 0 calc(1ch - 2px), transparent calc(1ch - 2px) 1ch) 4px 3px /
                calc(var(--kp-sig-tm-w) * 1ch) calc(100% - 6px) no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 0 0 / 1px 100% no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 0 0 / 3px 1px no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 0 100% / 3px 1px no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 100% 0 / 1px 100% no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 100% 0 / 3px 1px no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 100% 100% / 3px 1px no-repeat;
    }

    /* A waiting line is the row itself. */
    [data-theme='terminal'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)::before {
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
    }

    /* A block and a circle keep their ground, still, and the row stands at
       their foot. */
    [data-theme='terminal'] :is(.kp-skeleton--block, .kp-skeleton--circle) {
        overflow: clip;
        border-radius: 0;
        background: var(--muted);
        animation: none;
    }

    [data-theme='terminal'] :is(.kp-skeleton--block, .kp-skeleton--circle)::before {
        --kp-sig-tm-w: 24;
        position: absolute;
        inset-block-end: 0;
        inset-inline-start: 0;
        block-size: var(--kp-sig-tm-row);
    }

    /* The busy table's panel, the busy calendar and a busy card or key
       figure carry the row at their foot. */
    [data-theme='terminal'] .kp-datatable__busy-panel,
    [data-theme='terminal'] .kp-calendar--busy-whole > .kp-calendar__busy {
        padding-block-end: calc(var(--kp-space-md, 1rem) + var(--kp-sig-tm-row) + 0.5rem);
    }

    [data-theme='terminal'] .kp-datatable__busy-panel::before,
    [data-theme='terminal'] .kp-calendar--busy-whole > .kp-calendar__busy::before {
        position: absolute;
        inset-block-end: 0.5rem;
        inset-inline: 0;
        margin-inline: auto;
        block-size: var(--kp-sig-tm-row);
    }

    [data-theme='terminal']
        :is(.kp-card[aria-busy='true']:not(:has(.kp-skeleton), [data-kp-label]), .kp-kpi[aria-busy='true']:not(:has(.kp-skeleton))) {
        position: relative;
        padding-block-end: calc(var(--kp-space-md, 1rem) + var(--kp-sig-tm-row) + 0.5rem);
    }

    [data-theme='terminal']
        :is(.kp-card[aria-busy='true']:not(:has(.kp-skeleton), [data-kp-label]), .kp-kpi[aria-busy='true']:not(:has(.kp-skeleton)))::before {
        position: absolute;
        inset-block-end: 0.5rem;
        inset-inline-start: var(--kp-space-md, 1rem);
        block-size: var(--kp-sig-tm-row);
    }

    /* A loading entry carries a short row after its words. */
    [data-theme='terminal'] .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading]::after {
        --kp-sig-tm-w: 6;
        display: inline-block;
        block-size: 0.9em;
        margin-inline-start: 1ch;
        vertical-align: baseline;
    }

    /* A waiting button has no room for a row: the cursor alone, after its
       label, blinking on the slow clock. */
    [data-theme='terminal'] .kp-button[aria-busy='true']::after {
        background-size: 1ch 100%;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='terminal']
            :is(
                .kp-skeleton,
                .kp-datatable__busy-panel,
                .kp-calendar--busy-whole > .kp-calendar__busy,
                .kp-card[aria-busy='true']:not(:has(.kp-skeleton), [data-kp-label]),
                .kp-kpi[aria-busy='true']:not(:has(.kp-skeleton))
            )::before,
        [data-theme='terminal'] .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading]::after {
            animation:
                kp-sig-terminal-tm-fill var(--kp-sig-tm-slow) linear infinite alternate backwards,
                kp-sig-terminal-tm-head var(--kp-sig-tm-slow) steps(1, jump-end) infinite;
        }

        /* The lines of a skeleton stand one printed line apart. */
        [data-theme='terminal'] .kp-skeleton:nth-child(2)::before {
            animation-delay: var(--kp-sig-tm-line), 0ms;
        }

        [data-theme='terminal'] .kp-skeleton:nth-child(3)::before {
            animation-delay: calc(2 * var(--kp-sig-tm-line)), 0ms;
        }

        [data-theme='terminal'] .kp-button[aria-busy='true']::after {
            animation: kp-caret var(--kp-sig-tm-slow) steps(1) infinite;
        }
    }

    /* ── A change blinks [G9; Kenny, 2026-10-07: "three rapid blinks, bright
       and dim"]. js/update.js writes the new value at once and marks it
       `[data-kp-updating='blink']` while this plays: the ink goes between the
       bright phosphor and the dim phosphor three times in 900 ms, hard,
       never hidden, and ends on its own ink. A spark's line blinks the same
       way (its box carries the mark, the svg its colour). ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='terminal'] {
            --kp-update: blink;
        }

        [data-theme='terminal'] [data-kp-updating='blink']:not(:has(> svg)) {
            animation: kp-sig-terminal-update-blink var(--kp-sig-tm-change) steps(1, jump-end);
        }

        [data-theme='terminal'] [data-kp-updating='blink']:has(> svg) > svg {
            animation: kp-sig-terminal-update-blink-line var(--kp-sig-tm-change) steps(1, jump-end);
        }
    }

    @keyframes kp-sig-terminal-update-blink {
        0%,
        33.333%,
        66.667% {
            color: var(--kp-hot);
        }

        16.667%,
        50%,
        83.333% {
            color: var(--border-strong);
        }
    }

    @keyframes kp-sig-terminal-update-blink-line {
        0%,
        33.333%,
        66.667% {
            color: var(--primary);
        }

        16.667%,
        50%,
        83.333% {
            color: var(--border-strong);
        }
    }

    /* The writing: a loop lights the row a cell a step and empties it the
       way it filled; the head blinks on the slow clock (lit 500 ms, dark
       500); a typed line is written from its start. */
    @keyframes kp-sig-terminal-tm-fill {
        from {
            --kp-sig-tm-k: 0;
        }

        to {
            --kp-sig-tm-k: 1;
        }
    }

    @keyframes kp-sig-terminal-tm-head {
        0% {
            --kp-sig-tm-head: 1;
        }

        50% {
            --kp-sig-tm-head: 0;
        }
    }

    @keyframes kp-sig-terminal-tm-k {
        from {
            --kp-sig-tm-k: 0;
            visibility: visible;
        }

        to {
            --kp-sig-tm-k: 1;
            visibility: visible;
        }
    }

    @keyframes kp-sig-terminal-meter-tone-w {
        0%,
        33.333%,
        66.667% {
            filter: brightness(1);
        }

        16.667%,
        50%,
        83.333% {
            filter: brightness(0.4);
        }
    }

    @keyframes kp-sig-terminal-meter-tone-d {
        0%,
        33.333%,
        66.667% {
            filter: brightness(1);
        }

        16.667%,
        50%,
        83.333% {
            filter: brightness(0.4);
        }
    }
}
/* ── End of the signature ── */

/* A share, 0 to 1 (a progress bar's, a meter's), is walked to its value on
   two registered copies, one on each mirror of the motion, so that a rise is
   the picture's fall and a fall is that fall turned around; registered so
   the transitions interpolate them. At the top level because Firefox does
   not register an @property inside a layer. */
@property --kp-sig-br-lag {
    syntax: '<number>';
    inherits: true;
    initial-value: 0;
}

@property --kp-sig-br-lead {
    syntax: '<number>';
    inherits: true;
    initial-value: 0;
}

@layer kp.register {
    /* @kp-soft/themes — css/brutalism-register.css
   The brutalism register, 5.0.0 [S48, LIFT_PLAN row 5]: printed matter.
   Scoped to [data-theme='brutalism'] and inert elsewhere; opt-in, imported
   after themes.css. The approved concept demo ("Hard Copy", 2026-09-08)
   is the reference for every value here, and docs/archive/RESEARCH_2026-09.md
   §12 is where each mechanism was measured: Gumroad's lift/drop shadow
   pair and its per-plate ink token, BEIGE FORCE's pixel outline from four
   box-shadows and its relative-colour hover, Future Pharmaceutical's
   seamless -50% marquee and its ink-on-paper selection.

   What this file does, in order: the knobs; the type; the hooks of S45 —
   the headline whose words slam onto their yellow offset, the plate wiped
   in behind a <mark>, the six-pixel bar that rules a heading off, the
   marquee band as divider; the strip as navbar; the plates as buttons
   with the lift and the drop; the wells; the dossier with its stamp and
   its bars; and one answer per component root (TH124). The reveals have
   their rest state here and their motion in js/effects.js; without the
   script every one of them stands at rest.

   The grammar of themes/brutalism/CHARACTER.md (G1-G18, decided by Kenny
   on research/brutalism-character, 2026-10-07 23:44) is applied in two
   places: the plates, hover, focus and press here, in kp.register; the
   motion, the waiting and the tokens of the grammar (--kp-sig-br-*) in
   kp.signature below. A box stands on its hard shadow; pointing inverts
   it, focus lifts it under the two-channel ring, a press drives it onto
   its footprint; what arrives falls onto the footprint from up-left and
   what leaves is lifted off it.

   Colour discipline (DI9): nothing here names a colour; ink builds, yellow
   is the hand, lavender the second sheet, a status is paint under black
   ink and never a line, a shadow or a glow. One ink in two line weights,
   a hard shadow on the ground, no blur, no gradient that is not a flat
   fill or the hazard tape, no transparency. */

    [data-theme='brutalism'] {
        /* The month heatmap's nav goes on two rows below this width: the
           widest month and the three buttons in this type [fix-98]. */
        --kp-calendar-nav-fit: 28.25rem;
        /* The configuration surface [AR43], the demo's values as defaults. */
        --kp-reveal-threshold: 0.6;
        /* Every duration counts the register's 100 ms [G4]. */
        --kp-reveal-stagger: 300ms;
        --kp-redact-stagger: 100ms;
        --kp-classified-delay: 700ms;
        --kp-word-stagger: 100ms;
        --kp-plate-in: 400ms;
        --kp-bar: 600ms;
        --kp-marquee: 42000ms;
        --kp-line: 3px;
        --kp-drop: 6px;
        /* The reveals this theme performs [S45]: js/effects.js reads these
           and leaves a theme that declares none at rest. */
        --kp-reveal-headline: slam;
        --kp-reveal-emphasis: plate;
        --kp-reveal-rule: bar;
        /* The one shadow, and the one lifted a step; the pixel outline. */
        --kp-shadow: var(--kp-drop) var(--kp-drop) 0 0 var(--border-strong);
        --kp-shadow-up: calc(var(--kp-drop) + 2px) calc(var(--kp-drop) + 2px) 0 0 var(--border-strong);
        --kp-pixel:
            calc(-1 * var(--kp-line)) 0 0 0 var(--border-strong), var(--kp-line) 0 0 0 var(--border-strong),
            0 calc(-1 * var(--kp-line)) 0 0 var(--border-strong), 0 var(--kp-line) 0 0 var(--border-strong);
        /* The marquee's hatch: a strip of the plate colour on the ink. One
           tile is --kp-hatch-tile wide and holds exactly one stripe period
           along x: at -45deg a stripe period of tile / sqrt(2) across the
           stripe (28.2843px for 40px) moves the stripe one whole tile along
           the band, so a tile's right edge meets the next tile's left edge
           with no seam. */
        --kp-hatch-tile: 40px;
        --kp-hatch: repeating-linear-gradient(-45deg, var(--secondary) 0 6px, transparent 6px 28.2843px);
        --kp-hatch-alt: repeating-linear-gradient(-45deg, var(--foreground) 0 6px, transparent 6px 28.2843px);
        /* The voice [G15]: prose speaks at 500; every label, figure, date and
           tag is 700 or heavier and never under 12 px. */
        font-weight: 500;
        /* Nothing is translucent [G7, proposal-29]: a busy part says so with
           the lintel (G10), not with a dimmed ink. */
        --kp-busy-opacity: 1;
    }

    /* ── The ring, in the demo's order [S49, A5 of 2026-09-08] ────────────
       The base layer puts the contrast colour outside and the ring colour
       against the element; this theme's approved demo does it the other
       way round, and DI2's promise holds either way — two channels, one
       of which always clears 3:1 on the surface behind it. The broad rule
       sits here, before the register's own component rules, so a control
       that composes its own shadow stack still wins. */
    [data-theme='brutalism'] :focus-visible {
        outline-color: var(--focus-ring);
        box-shadow: 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring-contrast);
    }

    /* Future Pharmaceutical's selection: ink on paper. */
    [data-theme='brutalism'] ::selection {
        background: var(--foreground);
        color: var(--background);
    }

    /* ── Type ──────────────────────────────────────────────────────────── */

    [data-theme='brutalism'] h1,
    [data-theme='brutalism'] h2,
    [data-theme='brutalism'] h3 {
        font-family: var(--theme-font-display);
        font-weight: 400;
        text-transform: uppercase;
        letter-spacing: -0.02em;
    }

    [data-theme='brutalism'] [data-kp-surface] h1 {
        letter-spacing: -0.025em;
        margin-block: 0 0.4em;
        text-wrap: balance;
        overflow-wrap: anywhere;
    }

    /* The headline reveal: every word drops onto its yellow offset, once,
       one after another. The module wraps the words; the register moves
       them. At rest every word carries the offset. */
    [data-theme='brutalism'] [data-kp-reveal='headline'] [data-word] {
        display: inline-block;
        text-shadow: 4px 4px 0 var(--secondary);
    }

    /* Microlabels: BEIGE FORCE's pixel outline — four box-shadows, no
       border at all — on the yellow plate. */
    [data-theme='brutalism'] .microlabel {
        display: inline-block;
        padding: 0.3rem 0.7rem;
        background: var(--secondary);
        color: var(--secondary-foreground);
        font-weight: 700;
        font-size: 0.78rem;
        letter-spacing: 0.18em;
        text-transform: uppercase;
        line-height: 1.2;
        box-shadow: var(--kp-pixel);
    }

    /* ── The hooks [S45]: the mark, the rule, the divider ─────────────── */

    /* The mark: emphasis is a plate wiped in behind the word, closed by
       the one line weight. At rest the plate is there; armed, the word
       stands on the paper until the plate arrives — a size, not a colour
       (KT8). */
    [data-theme='brutalism'] mark {
        background: linear-gradient(var(--secondary), var(--secondary)) left / 100% 100% no-repeat;
        color: var(--secondary-foreground);
        font-weight: 700;
        padding-inline: 0.14em;
        border-bottom: var(--kp-line) solid var(--border-strong);
        white-space: nowrap;
    }

    [data-theme='brutalism'][data-kp-effects] mark:not(.is-cleared) {
        background-size: 0 100%;
        color: var(--foreground);
        border-bottom-color: transparent;
    }

    /* The rule: a six-pixel bar that rules the heading off, left to right,
       once, when the heading enters the viewport. */
    [data-theme='brutalism'] [data-kp-reveal='rule']::after {
        content: '';
        display: block;
        block-size: 6px;
        margin-block-start: 0.7rem;
        background: var(--border-strong);
        transform: scaleX(1);
        transform-origin: left center;
    }

    [data-theme='brutalism'][data-kp-effects] [data-kp-reveal='rule']:not(.is-in)::after {
        transform: scaleX(0);
    }

    /* The divider: Future Pharmaceutical's marquee — a strip twice the
       band's width translated -50%, seamless, one cycle in 42 seconds,
       frozen under reduced motion. A hatch of the plate on the ink, the
       second one the ink on the plate, running the other way. The tile is
       one stripe period, never the band's own width (which is no multiple
       of the period, and left a seam where one tile ended), and the strip's
       half is rounded up to whole tiles so the -50% loop lands on one. */
    [data-theme='brutalism'] [data-kp-divider] {
        display: block;
        position: relative;
        block-size: 46px;
        border-block: var(--kp-line) solid var(--border-strong);
        background: var(--foreground);
        overflow: hidden;
    }

    [data-theme='brutalism'] [data-kp-divider]::before {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        inline-size: calc(2 * round(up, 100%, var(--kp-hatch-tile)));
        background: var(--kp-hatch) 0 0 / var(--kp-hatch-tile) 100% repeat-x;
    }

    [data-theme='brutalism'] [data-kp-divider='alt'] {
        background: var(--secondary);
    }

    [data-theme='brutalism'] [data-kp-divider='alt']::before {
        background: var(--kp-hatch-alt) 0 0 / var(--kp-hatch-tile) 100% repeat-x;
    }

    /* ── The hero: paper, and the dot grid the base layer draws ───────── */

    [data-theme='brutalism'] [data-kp-surface='hero'] {
        position: relative;
        padding-block: 2.2rem 3.4rem;
    }

    [data-theme='brutalism'] [data-kp-surface='hero'] [data-kp-hero-grid] {
        grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
        gap: 2.5rem;
        align-items: end;
    }

    @container (max-width: 56rem) {
        [data-theme='brutalism'] [data-kp-surface='hero'] [data-kp-hero-grid] {
            grid-template-columns: 1fr;
        }
    }

    /* ── The navbar: a strip on paper, ruled off with the one line weight ── */

    [data-theme='brutalism'] .kp-nav-wrap {
        background: var(--background);
        border-bottom: var(--kp-line) solid var(--border-strong);
    }

    [data-theme='brutalism'] .kp-nav {
        background: var(--background);
        padding-block: calc(var(--kp-nav-pad-block, 1.1rem) * var(--kp-nav-pad-scale, 1));
        position: relative;
        /* Its own stacking context for the bar's decorations; the layer is the
         * wrapper's, from the base [scope-48]. */
        isolation: isolate;
    }

    [data-theme='brutalism'] .kp-nav__brand {
        font-family: var(--theme-font-display);
        font-weight: 400;
        font-size: 1.45rem;
        letter-spacing: -0.02em;
        text-transform: uppercase;
        line-height: 1;
        color: var(--foreground);
        text-decoration: none;
    }

    [data-theme='brutalism'] .kp-nav__links {
        gap: 0.35rem;
        align-items: center;
    }

    [data-theme='brutalism'] .kp-nav__link {
        display: block;
        padding-inline: 0.75rem;
        font-weight: 700;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--foreground);
        border: var(--kp-line) solid transparent;
        border-radius: 0;
        background: none;
        text-decoration: none;
    }

    /* Pointing at it inverts it [G8, Kenny 2026-10-07 23:44]; the current
       one and the one with focus are the yellow hand. */
    [data-theme='brutalism'] .kp-nav__link:focus-visible,
    [data-theme='brutalism'] .kp-nav__link[aria-current],
    [data-theme='brutalism'] .kp-nav__links > li:focus-within > .kp-nav__link {
        background: var(--secondary);
        color: var(--secondary-foreground);
        border-color: var(--border-strong);
    }

    [data-theme='brutalism'] .kp-nav__link:hover {
        background: var(--foreground);
        color: var(--secondary);
        border-color: var(--border-strong);
    }

    [data-theme='brutalism'] .kp-nav__link[aria-haspopup]::after {
        content: ' ▾';
    }

    [data-theme='brutalism'] .kp-nav__link--lang {
        margin-inline-start: 0.5rem;
        padding-inline-start: 0.7rem;
        border-inline-start: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
    }

    [data-theme='brutalism'] .kp-nav__link--lang:hover,
    [data-theme='brutalism'] .kp-nav__link--lang:focus-visible {
        border-inline-start-color: var(--border-strong);
    }

    /* The call to action: the ink plate with the yellow ink and the shadow;
       pointed at it inverts (yellow plate, ink words), focus lifts it under
       the ring, a press drives it onto its footprint [G8, G14]. */
    [data-theme='brutalism'] .kp-nav__link--cta {
        background: var(--primary);
        color: var(--primary-foreground);
        border-color: var(--border-strong);
        box-shadow: var(--kp-shadow);
    }

    [data-theme='brutalism'] .kp-nav__link--cta:hover {
        background: var(--primary-foreground);
        color: var(--primary);
    }

    [data-theme='brutalism'] .kp-nav__link--cta:focus-visible {
        translate: -2px -2px;
        box-shadow: var(--kp-shadow-up);
    }

    [data-theme='brutalism'] .kp-nav__link--cta:focus-visible {
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring-contrast),
            var(--kp-shadow-up);
    }

    [data-theme='brutalism'] .kp-nav__link--cta:active {
        background: var(--primary-active);
        color: var(--primary-foreground);
        translate: var(--kp-drop) var(--kp-drop);
        box-shadow: none;
    }

    /* The dropdown snaps: white, the line, the shadow — no fade, no blur. */
    [data-theme='brutalism'] .kp-nav__menu {
        background: var(--popover);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
        padding: 0.3rem 0;
        min-width: 12rem;
    }

    /* Collapsed, the dropdown is a list in the flow, not a panel [gap-12]:
       the rule above dresses the floating panel in kp.register, which
       beats the reset in kp.components, so the reset is restated here. */
    @container kp-nav (max-width: 40rem) {
        [data-theme='brutalism'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__menu {
            min-width: 0;
            padding-inline-start: var(--kp-nav-menu-indent, 1rem);
            border: 0;
            background: transparent;
            box-shadow: none;
        }
    }

    [data-theme='brutalism'] .kp-nav__menu a {
        display: block;
        padding-inline: 0.9rem;
        font-weight: 700;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        color: var(--popover-foreground);
        text-decoration: none;
        border-radius: 0;
    }

    [data-theme='brutalism'] .kp-nav__menu a:focus-visible {
        background: var(--secondary);
        color: var(--secondary-foreground);
    }

    [data-theme='brutalism'] .kp-nav__menu a:hover {
        background: var(--foreground);
        color: var(--secondary);
    }

    /* ── Buttons: a plate, the line, the shadow; inverted, lifted, driven in ──
       Pointing at a plate inverts it: the ink takes the plate and the plate
       becomes the ink, nothing moves and the shadow stays on the ground
       [G8, Kenny 2026-10-07 23:44, "hover = invert"]. Focus lifts the box
       off its footprint under the two-channel ring [G14]. A press drives it
       onto its footprint, the shadow's own 6 px, in 1 unit on the fall
       [G14]. A plate steps with --kp-plate and --kp-plate-ink, so every
       variant inverts its own pair. */
    [data-theme='brutalism'] .kp-button {
        --kp-plate: var(--secondary);
        --kp-plate-ink: var(--secondary-foreground);
        font-weight: 700;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--kp-plate-ink);
        background: var(--kp-plate);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
    }

    /* The size the demo drew, and the two the package owes beside it
       [S49, A4 + TH111's amendment]: one height for all three, and the
       type and the padding are what tell them apart. */
    [data-theme='brutalism'] .kp-button:not(.kp-button--sm):not(.kp-button--lg) {
        font-size: 0.9rem;
        padding-inline: 1.5rem;
    }

    [data-theme='brutalism'] .kp-button--sm {
        font-size: 0.78rem;
        padding-inline: 1rem;
    }

    [data-theme='brutalism'] .kp-button--lg {
        font-size: 1.05rem;
        padding-inline: 2rem;
    }

    /* Pointed at: inverted. */
    [data-theme='brutalism'] .kp-button:not(:active, :disabled):hover {
        color: var(--kp-plate);
        background: var(--kp-plate-ink);
        border-color: var(--border-strong);
        translate: none;
        box-shadow: var(--kp-shadow);
    }

    /* Focused: lifted off its footprint, the two channels the base layer
       composes (the outline in the paper, the inner ring in the ink) kept in
       front of the shadow (DI2, AR30). */
    [data-theme='brutalism'] .kp-button:not(:active, :disabled):focus-visible {
        border-color: var(--border-strong);
        translate: -2px -2px;
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring-contrast),
            var(--kp-shadow-up);
    }

    [data-theme='brutalism'] [data-kp-surface='hero'] .kp-row > .kp-button {
        min-width: min(11rem, 100%);
    }

    [data-theme='brutalism'] .kp-button--primary {
        --kp-plate: var(--primary);
        --kp-plate-ink: var(--primary-foreground);
    }

    [data-theme='brutalism'] .kp-button--destructive {
        --kp-plate: var(--destructive);
        --kp-plate-ink: var(--destructive-foreground);
    }

    /* Ghost: no plate, no line, no shadow, until the pointer is on it; then
       it is the inverted slab. */
    [data-theme='brutalism'] .kp-button--ghost {
        --kp-plate: transparent;
        --kp-plate-ink: var(--foreground);
        border-color: transparent;
        box-shadow: none;
    }

    [data-theme='brutalism'] .kp-button--ghost:not(:active, :disabled):hover {
        color: var(--secondary);
        background: var(--foreground);
    }

    [data-theme='brutalism'] .kp-button--ghost:not(:active, :disabled):focus-visible {
        background: transparent;
    }

    [data-theme='brutalism'] .kp-button:disabled {
        background: var(--muted);
        color: var(--muted-foreground);
        translate: none;
        box-shadow: var(--kp-shadow);
    }

    /* Small parts are small slabs [G7]: a 2 px line on a 3 px shadow, and
       they take the same three gestures at their own size. */
    [data-theme='brutalism'] .kp-icon-button {
        border: 2px solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
        color: var(--foreground);
        box-shadow: 3px 3px 0 0 var(--border-strong);
    }

    /* On a toast the close button sits on the toast's own plate, in the
       toast's ink: a plate of its own under the error toast's dark ink read
       1.01:1 (nostromo-notes, 2026-10-04). */
    [data-theme='brutalism'] .kp-toast .kp-icon-button {
        background: transparent;
        border-color: transparent;
        box-shadow: none;
        color: inherit;
    }

    /* On an alert the close button sits on the alert's own plate, in the
       alert's ink, the way it does on a toast [fix-95]. */
    [data-theme='brutalism'] .kp-alert .kp-icon-button {
        background: transparent;
        border-color: transparent;
        box-shadow: none;
        color: inherit;
    }

    /* A button inside a toast or an alert is brutalism's own [G17]: pointed
       at it is the inverted slab, whatever plate it stands on. */
    [data-theme='brutalism'] .kp-icon-button:not(:active, :disabled):hover,
    [data-theme='brutalism'] :is(.kp-toast, .kp-alert) :is(.kp-icon-button, .kp-button--ghost):not(:active, :disabled):hover {
        background: var(--foreground);
        border-color: var(--border-strong);
        color: var(--secondary);
        box-shadow: 3px 3px 0 0 var(--border-strong);
    }

    [data-theme='brutalism'] .kp-icon-button:not(:active, :disabled):focus-visible {
        translate: -2px -2px;
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring-contrast),
            5px 5px 0 0 var(--border-strong);
    }

    [data-theme='brutalism'] .kp-icon-button:active:not(:disabled) {
        background: var(--secondary-active);
        color: var(--secondary-foreground);
        translate: 3px 3px;
        box-shadow: none;
    }

    /* ── Fields: white wells with the line and the shadow ─────────────── */

    [data-theme='brutalism'] .kp-field__label {
        font-weight: 700;
        letter-spacing: 0.14em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-field__input,
    [data-theme='brutalism'] .kp-datatable__search,
    [data-theme='brutalism'] .kp-combobox__input,
    [data-theme='brutalism'] .kp-palette__input {
        background: var(--card);
        color: var(--card-foreground);
        border: var(--kp-line) solid var(--input);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
        padding-inline: 0.8rem;
    }

    /* The field and the combobox take their height from the package
       [scope-80]; the search box and the palette keep their own. */
    [data-theme='brutalism'] .kp-datatable__search,
    [data-theme='brutalism'] .kp-palette__input {
        padding-block: calc(var(--kp-space-sm) * 1.3);
    }

    /* Focus fills the well with the plate: the ring stays outside it. */
    [data-theme='brutalism'] .kp-field__input:focus-visible,
    [data-theme='brutalism'] .kp-datatable__search:focus-visible,
    [data-theme='brutalism'] .kp-combobox__input:focus-visible,
    [data-theme='brutalism'] .kp-palette__input:focus-visible {
        background: var(--secondary);
        color: var(--secondary-foreground);
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring-contrast),
            var(--kp-shadow);
    }

    [data-theme='brutalism'] select.kp-field__input::picker-icon {
        color: var(--foreground);
    }

    [data-theme='brutalism'] .kp-field__help {
        color: var(--muted-foreground);
    }

    /* A failed part is taped off [G13]: the line and the shadow stay the
       ink, and the error is printed on the failure's plate beneath it. */
    [data-theme='brutalism'] .kp-field--invalid .kp-field__input {
        border-color: var(--border-strong);
        box-shadow: var(--kp-shadow);
    }

    [data-theme='brutalism'] .kp-field__error {
        display: block;
        align-self: start;
        inline-size: fit-content;
        padding-inline: 0.5rem;
        border: 2px solid var(--border-strong);
        background: var(--destructive);
        color: var(--destructive-foreground);
        font-weight: 700;
    }

    [data-theme='brutalism'] .kp-field__error::before {
        content: '!! ';
    }

    /* The checkbox: a small box with its own shadow; checked is the ink
       with a yellow square. */
    [data-theme='brutalism'] .kp-field__check {
        place-items: center;
    }

    [data-theme='brutalism'] .kp-field__check:checked {
        border-color: var(--border-strong);
    }

    [data-theme='brutalism'] .kp-field__check:checked::before {
        content: '';
        inline-size: 0.5rem;
        block-size: 0.5rem;
        background: var(--primary-foreground);
    }

    [data-theme='brutalism'] .kp-fieldset {
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
    }

    [data-theme='brutalism'] .kp-switch__input {
        border: var(--kp-line) solid var(--border-strong);
    }

    [data-theme='brutalism'] .kp-form__summary {
        background: var(--card);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
    }

    /* ── Cards and the dossier ────────────────────────────────────────── */

    [data-theme='brutalism'] .kp-card {
        background: var(--card);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
    }

    [data-theme='brutalism'] .kp-card[data-kp-reveal='emphasis'] {
        position: relative;
    }

    /* The stamp: a signal plate with the pixel outline, tilted. */
    [data-theme='brutalism'] .kp-card[data-kp-label]::before {
        content: attr(data-kp-label);
        position: absolute;
        inset-block-start: 0.9rem;
        inset-inline-end: 1.1rem;
        rotate: -7deg;
        background: var(--fx-signal);
        color: var(--fx-signal-foreground);
        font-family: var(--theme-font-display);
        font-size: 0.8rem;
        letter-spacing: 0.14em;
        text-transform: uppercase;
        padding: 0.3rem 0.55rem;
        box-shadow: var(--kp-pixel);
    }

    /* The stamp changes when the file opens, as the demo's does [S49, A11]. */
    [data-theme='brutalism'] .kp-card[data-kp-open][data-kp-label-open]::before {
        content: attr(data-kp-label-open);
        background: var(--success);
        color: var(--success-foreground);
    }

    /* The redactions: black bars that slide off one after another, the
       way a pen is dragged off a page. */
    [data-theme='brutalism'] .kp-card[data-kp-reveal='emphasis'] mark {
        position: relative;
        background: none;
        color: var(--card-foreground);
        font-weight: 400;
        padding: 0;
        border-bottom: 0;
    }

    [data-theme='brutalism'] .kp-card[data-kp-reveal='emphasis'] mark::after {
        content: '';
        position: absolute;
        inset: -0.12em -0.2em;
        background: var(--foreground);
        transform: scaleX(0);
        transform-origin: right center;
        pointer-events: none;
    }

    [data-theme='brutalism'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared) {
        color: transparent;
    }

    [data-theme='brutalism'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared)::after {
        transform: scaleX(1);
    }

    /* Panels: white, the line, the shadow; nothing floats, nothing fades. */
    [data-theme='brutalism'] .kp-dialog,
    [data-theme='brutalism'] .kp-popover,
    [data-theme='brutalism'] .kp-menu,
    [data-theme='brutalism'] .kp-toast,
    [data-theme='brutalism'] .kp-tooltip,
    [data-theme='brutalism'] .kp-confirm,
    [data-theme='brutalism'] .kp-datepicker__panel,
    [data-theme='brutalism'] .kp-combobox__list,
    [data-theme='brutalism'] .kp-palette,
    [data-theme='brutalism'] .kp-theme-menu__list {
        background: var(--popover);
        color: var(--popover-foreground);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
    }

    /* The wrapper round the theme picker's icon button is not a card: only its
       dropdown list is. */
    [data-theme='brutalism'] .kp-theme-menu {
        background: none;
        border: 0;
        box-shadow: none;
    }

    [data-theme='brutalism'] .kp-toast {
        letter-spacing: 0.1em;
        text-transform: uppercase;
    }

    /* Severity toasts [scope-60]. The plain toast above is repainted here in
       a later layer than kp.components, which swallowed every variant's
       plate; each is restated on the alert's token pair, as the severity
       badge wears it. A status is paint under black ink [G5]: the plate
       changes, the line stays the ink. */
    [data-theme='brutalism'] .kp-toast--info {
        background: var(--info);
        color: var(--info-foreground);
    }

    [data-theme='brutalism'] .kp-toast--warning {
        background: var(--warning);
        color: var(--warning-foreground);
    }

    [data-theme='brutalism'] .kp-toast--destructive,
    [data-theme='brutalism'] .kp-toast--error {
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    [data-theme='brutalism']
        :is(.kp-toast--success, .kp-toast--info, .kp-toast--warning, .kp-toast--destructive, .kp-toast--error)
        :is(.kp-button--ghost, .kp-icon-button) {
        color: inherit;
    }

    [data-theme='brutalism'] .kp-toasts {
        gap: 0.9rem;
    }

    /* The menu keeps a ring's width of paper inside its frame: with the
       line directly against the items, an item's ink ring fell onto the
       ink line and painted nothing new (AR30's dashboard test). */
    [data-theme='brutalism'] .kp-menu {
        padding: calc(2 * var(--kp-focus-ring-inner-width, 2px));
    }

    /* The items are flat on the menu's own plate, as the demo's dropdown
       was: the line, the shadow and the lift belong to the menu, not to
       each row — a row that carried them drowned its ink ring in the ink
       of its own shadow and the frame (AR30's dashboard test). */
    [data-theme='brutalism'] .kp-menu .kp-menu__item {
        --kp-plate: var(--popover);
        --kp-plate-ink: var(--popover-foreground);
        border: 0;
        box-shadow: none;
        translate: none;
        padding: 0.5rem 0.75rem;
    }

    [data-theme='brutalism'] .kp-menu .kp-menu__item--destructive {
        --kp-plate-ink: var(--destructive);
    }

    /* An entry is brutalism's own element [G17]: pointed at it inverts, with
       focus it is the yellow hand under the inner ring, a press drives it
       onto the active plate. */
    [data-theme='brutalism'] .kp-menu .kp-menu__item:not(:active, [aria-disabled='true']):hover {
        background: var(--foreground);
        color: var(--secondary);
        translate: none;
        box-shadow: none;
    }

    [data-theme='brutalism'] .kp-menu .kp-menu__item--destructive:not(:active, [aria-disabled='true']):hover {
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    [data-theme='brutalism'] .kp-menu .kp-menu__item:not(:active):focus-visible {
        background: var(--secondary);
        color: var(--secondary-foreground);
        translate: none;
        box-shadow: 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring-contrast);
    }

    [data-theme='brutalism'] .kp-menu .kp-menu__item:active:not([aria-disabled='true']) {
        background: var(--secondary-active);
        color: var(--secondary-foreground);
        translate: none;
        box-shadow: none;
    }

    /* The plain alert only [gap-1, Kenny 2026-09-10]. This rule used to
       repaint the ground of EVERY alert, and `kp.register` is a later layer
       than `kp.components`, so it beat `.kp-alert--destructive`'s own plate
       while that variant's ink — `--destructive-foreground`, which is drawn
       to sit ON the plate — stayed. Measured in firefox on 2026-09-12:
       seventeen of the twenty-two themes carried a destructive alert whose
       text was unreadable, grotesk at 1.00 exactly, white on white.

       Kenny saw it in chassis-rs and said to write it down and touch
       nothing; this is the round he asked for it in. Same shape as fix-12,
       one property over: a register overriding half of a pair the base
       layer defines together. */
    [data-theme='brutalism'] .kp-alert:not([class*='kp-alert--']) {
        background: var(--card);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
    }

    [data-theme='brutalism'] .kp-alert[class*='kp-alert--'] {
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
    }

    /* A warning or a failure is taped off [G13]: a band of 45 degree hazard
       stripes along its foot, 0.5 rem, in the tone's paint and the ink. The
       tape means danger and nothing else [G16]. */
    [data-theme='brutalism'] .kp-alert--warning,
    [data-theme='brutalism'] .kp-alert--destructive {
        --kp-sig-br-tone: var(--warning);
        padding-block-end: calc(0.75rem + 0.5rem);
        background-image: repeating-linear-gradient(45deg, var(--kp-sig-br-tone) 0 6px, var(--border-strong) 6px 12px);
        background-position: 0 100%;
        background-size: 100% 0.5rem;
        background-repeat: no-repeat;
    }

    [data-theme='brutalism'] .kp-alert--destructive {
        --kp-sig-br-tone: var(--destructive);
    }

    [data-theme='brutalism'] .kp-alert__label {
        font-family: var(--theme-font-display);
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-grid__tile,
    [data-theme='brutalism'] .kp-split__pane {
        background: var(--card);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
    }

    [data-theme='brutalism'] .kp-grid {
        gap: 1.25rem;
    }

    [data-theme='brutalism'] .kp-split {
        gap: 1rem;
    }

    [data-theme='brutalism'] .kp-split__separator {
        background: var(--border-strong);
        inline-size: var(--kp-line);
    }

    /* Top and bottom [gap-12]: the thickness above is an inline size, so
       a horizontal split takes the same value as a block size. */
    [data-theme='brutalism'] .kp-split[data-kp-orientation='horizontal'] > .kp-split__separator {
        inline-size: auto;
        block-size: var(--kp-line);
    }

    /* The footer: the ink, the paper, the yellow. */
    [data-theme='brutalism'] .kp-footer {
        background: var(--sidebar-background);
        color: var(--sidebar-foreground);
    }

    [data-theme='brutalism'] .kp-footer h4 {
        font-family: var(--theme-font-display);
        font-weight: 400;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        color: var(--sidebar-primary);
    }

    [data-theme='brutalism'] .kp-footer a {
        color: var(--sidebar-foreground);
        font-size: 0.85rem;
        font-weight: 700;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        text-decoration: none;
        border-bottom: var(--kp-line) solid transparent;
    }

    [data-theme='brutalism'] .kp-footer a:hover,
    [data-theme='brutalism'] .kp-footer a:focus-visible {
        color: var(--sidebar-primary);
        border-bottom-color: var(--sidebar-primary);
    }

    [data-theme='brutalism'] .kp-footer .microlabel {
        background: none;
        box-shadow: none;
        padding: 0.8rem 0 0;
        border-top: var(--kp-line) solid var(--sidebar-primary);
        color: var(--sidebar-foreground);
        font-family: var(--theme-font-body);
        font-weight: 700;
        letter-spacing: 0.1em;
        display: block;
    }

    /* ── Badges, tags, status: candy plates with black ink ────────────── */

    [data-theme='brutalism'] .kp-badge,
    [data-theme='brutalism'] .kp-tag {
        border-radius: 0;
        border: 2px solid var(--border-strong);
        box-shadow: 3px 3px 0 0 var(--border-strong);
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-health {
        font-weight: 700;
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-health__dot {
