    }

    [data-theme='brutalism'] .kp-pagination a[aria-current],
    [data-theme='brutalism'] .kp-pagination [aria-current] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: 0;
        box-shadow: 3px 3px 0 0 var(--border-strong);
    }

    [data-theme='brutalism'] .kp-wizard {
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
        box-shadow: var(--kp-shadow);
    }

    [data-theme='brutalism'] .kp-wizard__steps {
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }

    /* ── Pickers and palettes ─────────────────────────────────────────── */

    [data-theme='brutalism'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: 0;
    }

    [data-theme='brutalism'] .kp-datepicker__weekday,
    [data-theme='brutalism'] .kp-datepicker__title {
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-colorpicker__swatch {
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: 3px 3px 0 0 var(--border-strong);
    }

    [data-theme='brutalism'] .kp-colorpicker__value {
        font-family: var(--theme-font-mono);
    }

    [data-theme='brutalism'] .kp-shortcuts__row kbd {
        font-family: var(--theme-font-mono);
        font-weight: 700;
        border: 2px solid var(--border-strong);
        border-radius: 0;
        box-shadow: 3px 3px 0 0 var(--border-strong);
        background: var(--card);
        display: inline-block;
        padding: 0 0.4em;
    }

    [data-theme='brutalism'] .kp-shortcuts__group-label,
    [data-theme='brutalism'] .kp-palette__group-label {
        font-family: var(--theme-font-display);
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-theme-menu__status,
    [data-theme='brutalism'] .kp-palette__status,
    [data-theme='brutalism'] .kp-combobox__status {
        font-family: var(--theme-font-body);
        font-size: max(0.75rem, 0.875em);
        font-weight: 700;
        letter-spacing: 0.1em;
        text-transform: uppercase;
    }

    /* ── The roots the rules above reach only by their parts ──────────── */

    [data-theme='brutalism'] .kp-field {
        gap: calc(var(--kp-space-xs) * 1.2);
    }

    [data-theme='brutalism'] .kp-form {
        gap: var(--kp-space-lg);
    }

    [data-theme='brutalism'] .kp-combobox,
    [data-theme='brutalism'] .kp-datepicker,
    [data-theme='brutalism'] .kp-colorpicker,
    [data-theme='brutalism'] .kp-shortcuts,
    [data-theme='brutalism'] .kp-tabs {
        border-radius: 0;
    }

    /* ── The scrollbar joins the theme ────────────────────────────────── */

    [data-theme='brutalism'] {
        scrollbar-color: var(--border-strong) var(--background);
    }

    /* ── The demo's own pieces [S46] ──────────────────────────────────── */

    [data-theme='brutalism'] .kp-side-note {
        position: absolute;
        inset-inline-end: 0.4rem;
        inset-block-start: 4.5rem;
        writing-mode: vertical-rl;
        font-family: var(--theme-font-body);
        font-size: 0.75rem;
        font-weight: 700;
        letter-spacing: 0.26em;
        text-transform: uppercase;
        color: var(--muted-foreground);
        border-inline-start: var(--kp-line) solid var(--border-strong);
        padding-inline-start: 0.5rem;
    }

    /* The laurels: three plates, each with its own ink (DI4). */
    [data-theme='brutalism'] .kp-laurels {
        gap: 0.9rem;
        font-size: 0.78rem;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-laurels li {
        --kp-plate: var(--secondary);
        --kp-plate-ink: var(--secondary-foreground);
        background: var(--kp-plate);
        color: var(--kp-plate-ink);
        border: var(--kp-line) solid var(--border-strong);
        box-shadow: var(--kp-shadow);
        padding: 0.55rem 0.85rem;
        max-width: 100%;
    }

    [data-theme='brutalism'] .kp-laurels li:nth-child(2) {
        --kp-plate: var(--accent);
        --kp-plate-ink: var(--accent-foreground);
    }

    [data-theme='brutalism'] .kp-laurels li:nth-child(3) {
        --kp-plate: var(--success);
        --kp-plate-ink: var(--success-foreground);
    }

    [data-theme='brutalism'] .kp-laurels b {
        display: block;
        font-family: var(--theme-font-display);
        font-weight: 400;
        font-size: 0.95rem;
        letter-spacing: -0.01em;
        text-transform: none;
    }

    [data-theme='brutalism'] .kp-lede {
        max-width: 36rem;
        font-size: 1.1rem;
    }

    /* The platforms: bordered chips on the muted plate. */
    [data-theme='brutalism'] .kp-platforms {
        margin-block-start: 2rem;
        gap: 0.5rem;
        font-family: var(--theme-font-body);
        font-size: 0.75rem;
        font-weight: 700;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--foreground);
    }

    [data-theme='brutalism'] .kp-platforms span {
        border: var(--kp-line) solid var(--border-strong);
        padding: 0.25rem 0.6rem;
        background: var(--muted);
    }

    /* The spec sheet: the white card, the line, the shadow. */
    [data-theme='brutalism'] .kp-spec {
        background: var(--card);
        color: var(--card-foreground);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
        padding: 1.2rem 1.3rem 1.4rem;
        font-family: var(--theme-font-mono);
        font-size: 0.78rem;
        font-weight: 700;
        line-height: 1.7;
    }

    [data-theme='brutalism'] .kp-spec dt {
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: 0.08em;
    }

    /* The log wears what this register already decided for its other data
 * surface, `.kp-spec` — the same ground, the same edge, the same face
 * [gap-14]. A new component that invents a look of its own is a
 * twenty-third decision nobody made. */
    [data-theme='brutalism'] .kp-log {
        background: var(--card);
        color: var(--card-foreground);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
        font-family: var(--theme-font-mono);
        font-weight: 700;
    }

    [data-theme='brutalism'] .kp-log__level {
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: 0.08em;
    }

    [data-theme='brutalism'] .kp-spec__swatch {
        border: 2px solid var(--border-strong);
        border-radius: 0;
    }

    [data-theme='brutalism'] .kp-spec__font {
        font-family: var(--theme-font-display);
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above are what they get, and the
       marquee stands still. The durations are literal because
       check-motion.mjs computes DI5's rate from them; the matching --kp-*
       knobs are what js/effects.js reads. Position and size only — no
       colour transition anywhere (KT8). */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='brutalism'] [data-kp-reveal='headline'].is-words [data-word] {
            animation: kp-slam 300ms var(--fx-ease) both;
            animation-delay: calc(var(--kp-i, 0) * var(--kp-word-stagger));
        }

        [data-theme='brutalism'] mark {
            transition: background-size 400ms var(--fx-ease);
        }

        [data-theme='brutalism'] [data-kp-reveal='rule'].is-in::after {
            animation: kp-rule-in 600ms var(--fx-ease) 1 both;
        }

        [data-theme='brutalism'] [data-kp-divider]::before {
            animation: kp-marquee 42000ms linear infinite;
        }

        [data-theme='brutalism'] [data-kp-divider='alt']::before {
            animation-direction: reverse;
        }

        [data-theme='brutalism'] .kp-card[data-kp-reveal='emphasis'] mark::after {
            transition: transform 400ms var(--fx-ease);
        }

        [data-theme='brutalism'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2)::after {
            transition-delay: var(--kp-redact-stagger);
        }

        [data-theme='brutalism'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3)::after {
            transition-delay: calc(2 * var(--kp-redact-stagger));
        }

        /* What the demo moves on a hover [S49, A6 of 2026-09-08]: the
           lift, the shadow it lifts away from, and the plate colour. KT8
           held a hover to one step with no colour transition; Kenny chose
           the demo for this theme, and AR30's reader waits out
           --fx-duration after a theme switch rather than reading a ring
           mid-flight. */
        [data-theme='brutalism'] :is(.kp-button, .kp-icon-button, .kp-nav__link--cta) {
            transition:
                translate var(--fx-duration) var(--kp-sig-br-up),
                box-shadow var(--fx-duration) var(--kp-sig-br-up);
        }

        /* What is driven in or lifted into focus falls: one unit on the
           fall curve, stopping dead [G1, G14]; released, it is lifted on
           the same curve played back. */
        [data-theme='brutalism'] :is(.kp-button, .kp-icon-button, .kp-nav__link--cta):is(:active, :focus-visible) {
            transition-timing-function: var(--kp-sig-br-fall);
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* Every keyframe here has its row in TIMINGS (js/effects.js); kp-rule-in
       is the base layer's. The slam moves a word onto its offset once; the
       marquee translates a strip -50%, seamlessly, and never changes
       luminance. */
    @keyframes kp-slam {
        from {
            transform: translate(-9px, -9px);
            text-shadow: 0 0 0 var(--secondary);
        }

        to {
            transform: none;
            text-shadow: 4px 4px 0 var(--secondary);
        }
    }

    @keyframes kp-marquee {
        from {
            transform: translateX(0);
        }

        to {
            transform: translateX(-50%);
        }
    }

    /* Stamped beside the wordmark, in the ink [S49, A3]. */
    [data-theme='brutalism'] .kp-nav__brand-tag {
        color: var(--foreground);
        font-weight: 700;
        letter-spacing: 0.14em;
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — ink on paper inverted, the fastest pass but its own hatch band. */
    [data-theme='brutalism'] .kp-marquee {
        background: var(--foreground);
        color: var(--background);
        border-block: 3px solid var(--foreground);
        font-weight: 700;
        text-transform: uppercase;
        --kp-marquee: 20000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    /* A mega menu's group headings speak in the caption's voice [scope-48]. */
    [data-theme='brutalism'] .kp-nav__menu[data-kp-menu-label]::before,
    [data-theme='brutalism'] .kp-nav__menu--wide .kp-nav__menu-heading {
        background: var(--foreground);
        color: var(--background);
        font-weight: 700;
        letter-spacing: 0.02em;
        border-block-end: 0;
    }

    /* ── The side navigation [feat-nav-3] ────────────────────────────
       Not a panel but a column of slabs, each with its own hard shadow.
       The current one does not tint: it slides into its shadow and the
       shadow goes out from under it [approved by Kenny, 2026-09-11]. */
    [data-theme='brutalism'] .kp-sidenav {
        --kp-sidenav-surface: transparent;
        --kp-sidenav-gap: 0.4rem;
        border: none;
    }

    [data-theme='brutalism'] .kp-sidenav__header {
        background: var(--foreground);
        color: var(--background);
        border: 2px solid var(--foreground);
    }

    [data-theme='brutalism'] .kp-sidenav__title {
        letter-spacing: 0.18em;
        text-transform: uppercase;
        color: inherit;
    }

    [data-theme='brutalism'] .kp-sidenav__link,
    [data-theme='brutalism'] .kp-sidenav__category-toggle {
        border: 2px solid var(--foreground);
        background: var(--background);
        padding-inline: 0.75rem;
        font-weight: 700;
        text-transform: uppercase;
        border-radius: 0;
        box-shadow: 3px 3px 0 var(--foreground);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='brutalism'] .kp-sidenav__link,
        [data-theme='brutalism'] .kp-sidenav__category-toggle {
            transition:
                translate var(--fx-duration, 100ms) var(--fx-ease, ease),
                box-shadow var(--fx-duration, 100ms) var(--fx-ease, ease);
        }
    }

    /* Pointed at: inverted, the shadow staying on the ground [G8]. */
    [data-theme='brutalism'] .kp-sidenav__link:not([aria-current='page']):hover {
        background: var(--foreground);
        color: var(--secondary);
    }

    [data-theme='brutalism'] .kp-sidenav__link:not([aria-current='page']):focus-visible {
        translate: -2px -2px;
        box-shadow: 5px 5px 0 var(--foreground);
    }

    [data-theme='brutalism'] .kp-sidenav__link[aria-current='page'] {
        background: var(--secondary);
        color: var(--secondary-foreground);
        translate: 3px 3px;
        box-shadow: 0 0 0 var(--foreground);
    }

    /* ── Back to top, and a picture [feat-page-1, feat-media-1] ──────
       Slabs. The control sits on its shadow and moves into it when
       pressed; the frame has the same border and never rounds. */
    [data-theme='brutalism'] .kp-to-top {
        border: 2px solid var(--foreground);
        border-radius: 0;
        box-shadow: 3px 3px 0 var(--foreground);
    }

    [data-theme='brutalism'] .kp-to-top:active {
        translate: 3px 3px;
        box-shadow: 0 0 0 var(--foreground);
    }

    [data-theme='brutalism'] .kp-media {
        border: 3px solid var(--foreground);
        border-radius: 0;
        box-shadow: 6px 6px 0 var(--foreground);
    }

    [data-theme='brutalism'] .kp-media-figure > figcaption {
        text-transform: uppercase;
        font-weight: 700;
        letter-spacing: 0.06em;
        font-size: 0.75rem;
    }

    /* The figure carries the caption's voice, so the decision sits with
       the picture rather than with the words under it. */
    [data-theme='brutalism'] .kp-media-figure {
        color: var(--foreground);
        text-align: start;
    }

    /* ── The thing names itself [scope-12, approved 2026-09-11] ────────
       Brutalism labels its own construction: services on the outside,
       functions painted on the wall. So a control says what it IS when
       you touch it, in a small block-letter tag beside it.

       Kenny's two conditions, 2026-09-11: it reaches many elements rather
       than only buttons, and the words are English by default and
       replaceable. `--kp-label` is that door — a page or a single element
       sets it and the tag says whatever it was given. The defaults below
       are the fallbacks in that same declaration, which is why there is
       no string here a consumer cannot reach. */
    [data-theme='brutalism'] .kp-button,
    [data-theme='brutalism'] .kp-field__input,
    [data-theme='brutalism'] .kp-card,
    [data-theme='brutalism'] .kp-alert,
    [data-theme='brutalism'] .kp-badge {
        position: relative;
    }

    /* The side navigation says where it sits, and this tag may not argue
       with it [fix-42]. A register wins over the base layer whatever its
       specificity, so `position: relative` here took the `position: fixed`
       an `over` or `push` panel gets from css/components.css away with it
       and put the closed panel back in the flow, standing on the page
       before it was opened — Kenny, 2026-09-16, brutalism's over-the-page
       menu: "Hier staat het menu al meer dan volledig op de pagina voor ik
       het open. Het moet normaal toch 'uit het zicht' zijn?" Measured on
       catalogue/navigation.html#sidenav-over in firefox: the closed panel's
       right edge stood 621px onto the page where every other theme has it
       at 0. Those two modes are positioned already, and a positioned box is
       all the tag needs; only the `side` panel, a flex item of the page's
       own layout, has to be given one. */
    [data-theme='brutalism'] .kp-sidenav:not([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']) {
        position: relative;
    }

    [data-theme='brutalism'] .kp-button::after,
    [data-theme='brutalism'] .kp-field__input::after,
    [data-theme='brutalism'] .kp-card::after,
    [data-theme='brutalism'] .kp-alert::after,
    [data-theme='brutalism'] .kp-badge::after,
    [data-theme='brutalism'] .kp-sidenav::after {
        position: absolute;
        inset-block-end: calc(100% + 0.3rem);
        inset-inline-start: 0;
        font-family: var(--theme-font-body);
        font-size: 0.75rem;
        font-weight: 700;
        letter-spacing: 0.14em;
        line-height: 1.2;
        white-space: nowrap;
        background: var(--foreground);
        color: var(--background);
        padding: 0.1rem 0.35rem;
        opacity: 0;
        pointer-events: none;
    }

    [data-theme='brutalism'] .kp-button::after {
        content: var(--kp-label, 'BUTTON');
    }

    [data-theme='brutalism'] .kp-field__input::after {
        content: var(--kp-label, 'FIELD');
    }

    [data-theme='brutalism'] .kp-card::after {
        content: var(--kp-label, 'CARD');
    }

    [data-theme='brutalism'] .kp-alert::after {
        content: var(--kp-label, 'ALERT');
    }

    [data-theme='brutalism'] .kp-badge::after {
        content: var(--kp-label, 'BADGE');
    }

    [data-theme='brutalism'] .kp-sidenav::after {
        content: var(--kp-label, 'NAV');
    }

    [data-theme='brutalism'] .kp-button:hover::after,
    [data-theme='brutalism'] .kp-button:focus-visible::after,
    [data-theme='brutalism'] .kp-field__input:hover::after,
    [data-theme='brutalism'] .kp-field__input:focus::after,
    [data-theme='brutalism'] .kp-card:hover::after,
    [data-theme='brutalism'] .kp-alert:hover::after,
    [data-theme='brutalism'] .kp-badge:hover::after,
    [data-theme='brutalism'] .kp-sidenav:hover::after {
        opacity: 1;
    }

    /* ── The pressed state the register had been cancelling [fix-12] ───
       `kp.register` sits after `kp.components`, and a layer beats a state:
       a register writing `.kp-button:hover { background: ... }` outranks
       the base layer's `.kp-button:active`, so pressing the button changed
       nothing. Kenny found it on Shade (dark), 2026-09-11 — "als ik gewoon
       blijf klikken op de knop zelf, dan gebeurt er precies niks" — and
       fifteen of the twenty-five registers had it.

       These restate the base layer's own pressed values, token for token,
       and drive the box onto its footprint, the shadow's own offset [G14,
       Kenny 2026-10-07 23:44, "press = ground"; the base layer's 4 px left
       the box 2 px short of a 6 px shadow]. */

    [data-theme='brutalism'] .kp-button:active:not(:disabled) {
        color: var(--kp-plate-ink);
        background: var(--secondary-active);
        translate: var(--kp-drop) var(--kp-drop);
        box-shadow: none;
    }

    [data-theme='brutalism'] .kp-button--primary:active:not(:disabled) {
        background: var(--primary-active);
    }

    [data-theme='brutalism'] .kp-button--destructive:active:not(:disabled) {
        background: var(--destructive-active);
    }

    [data-theme='brutalism'] .kp-button--ghost:active:not(:disabled) {
        color: var(--foreground);
        background: var(--secondary-active);
    }

    /* ── Read-only fields [gap-11] ────────────────────────────────────── */

    /* A read-only field is a value on a record, not a box to type in. This
       register sets the field's border and ground in kp.register, which
       beats the read-only look in kp.components, so read-only painted like
       an editable field. The state is answered here, on top of the rest
       look, which stays as it was. */
    [data-theme='brutalism'] .kp-field__input[readonly] {
        border-style: dashed;
        background-color: var(--muted);
    }

    /* ── The palette's trigger in the bar [scope-48, scope-80] ─────────── */

    /* In the voice of this register's own nav links (Kenny, 2026-09-14,
       search-voice "Per thema"): heavy spaced capitals in a thick frame that
       is invisible until pointed at, when the frame and the secondary slab
       appear. The link's typeface, case, spacing, shape and pointer answer
       are restated here, because the trigger is a button beside the list
       rather than a link in it. The underline a plain link carries is not:
       it says "this is a link", and the trigger is not one. */
    [data-theme='brutalism'] .kp-nav__search .kp-nav__search-trigger {
        padding-inline: 0.75rem;
        font-weight: 700;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        border: var(--kp-line) solid transparent;
        border-radius: 0;
        background: none;
        color: var(--foreground);
    }

    [data-theme='brutalism'] .kp-nav__search .kp-nav__search-trigger:focus-visible {
        background: var(--secondary);
        color: var(--secondary-foreground);
        border-color: var(--border-strong);
    }

    [data-theme='brutalism'] .kp-nav__search .kp-nav__search-trigger:hover {
        background: var(--foreground);
        color: var(--secondary);
        border-color: var(--border-strong);
    }

    /* ── The alarm [scope-94] ──────────────────────────────────────────────
       A stamp slammed onto the page: a red slab with a thick black border and a hard offset shadow, set at an angle, black hazard bars on the cream ground. Every colour is one of this theme's tokens. The
       button keeps this register's shape and takes the alarm's paint, on
       selectors long enough to outrank this register's own button states;
       the dialog takes no focus ring, because in the auto mode the whole
       screen is what has focus. */
    [data-theme='brutalism'] .kp-alarm {
        --kp-alarm-ground: hsl(from var(--background) h s l / 0.94);
        --kp-alarm-ink: var(--destructive-foreground);
        --kp-alarm-soft: var(--destructive-foreground);
        --kp-alarm-split: var(--foreground);
        --kp-alarm-on-ink: var(--destructive);
        --kp-alarm-glow: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-halo: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-scan: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-vignette: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-stripe: var(--foreground);
        --kp-alarm-frame: 4px solid var(--foreground);
        --kp-alarm-panel-ground: var(--destructive);
        --kp-alarm-panel-border: 4px solid var(--foreground);
        --kp-alarm-panel-shadow: 10px 10px 0 var(--foreground);
        --kp-alarm-panel-padding: clamp(0.9rem, 2.6cqi, 2.25rem);
        --kp-alarm-title-tracking: -0.02em;
        /* One step smaller, everywhere [Kenny, 2026-09-16]. His rejection of
           the auto alarm: "De tekst wordt afgebroken omdat het te groot is om
           in het kader te passen. Het hele element en subelementen mogen wat
           minder groot zijn." Measured in firefox on the raised alarm with
           the catalogue's own words, "Intrusion detected": at 1280x800 the
           headline asked the slab for 983 px of content box and got 884, so
           99 px of it was cut off by the plate; at 864x450 — the CSS viewport
           of his 2.222 zoom — the panel stood 109 px taller than the alarm's
           own box, and because the alarm centres its panel the overflow goes
           BOTH ways: the code line sat 45 px above the frame and the top of
           the headline 30 px above it, out of reach of the scroll. The
           headline drops from the package's 12cqi to 8cqi with a 5.5rem
           ceiling, the bars, the padding, the line and the shadow come down
           with it, and the plate narrows from 56rem to 44rem so the words
           have somewhere to wrap. The slab, the tilt and Archivo Black in
           capitals are untouched: this is the same stamp, one step smaller. */
        /* And back up a notch [Kenny, 2026-09-16, second look]: "nu is het
           te klein, zie gewoon dat de rode kader net in het vak past". The
           headline and the plate take the room the frame leaves, with the
           fit test holding the overflow at zero in all 22 themes. */
        --kp-alarm-title-size: clamp(2rem, 10cqi, 7rem);
        --kp-alarm-bar: 0.85rem;
    }

    [data-theme='brutalism'] .kp-alarm:focus-visible {
        outline: none;
    }

    [data-theme='brutalism'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack,
    [data-theme='brutalism'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:hover:not(:disabled),
    [data-theme='brutalism'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:active:not(:disabled) {
        border-color: var(--kp-alarm-ink);
        background: var(--kp-alarm-ink);
        color: var(--kp-alarm-on-ink);
        text-shadow: none;
    }

    [data-theme='brutalism'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:is(:hover, :focus-visible):not(:disabled):not(:active) {
        background: var(--kp-alarm-on-ink);
        color: var(--kp-alarm-ink);
    }

    [data-theme='brutalism'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep,
    [data-theme='brutalism'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep:is(:hover, :focus-visible):not(:disabled) {
        border-color: currentColor;
        background: transparent;
        color: inherit;
        text-shadow: none;
    }

    [data-theme='brutalism'] .kp-alarm__panel {
        inline-size: min(100%, 52rem);
        rotate: -2deg;
    }

    /* The sub-elements come down with the plate [Kenny, 2026-09-16]: the code
       line, the reason and the button are the package's sizes minus a step,
       so the whole stamp shrinks together rather than the headline alone. The
       button keeps a width a thumb can find. */
    [data-theme='brutalism'] .kp-alarm__code {
        font-size: clamp(0.62rem, 1.1cqi, 0.82rem);
    }

    [data-theme='brutalism'] .kp-alarm__detail {
        font-size: clamp(0.78rem, 1.5cqi, 1.05rem);
        line-height: 1.4;
    }

    [data-theme='brutalism'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack {
        min-inline-size: 11rem;
    }

    /* A submenu item's mark [Kenny, 2026-09-20]: a blunt filled square, undecorated. */
    [data-theme='brutalism'] .kp-sidenav__submenu .kp-sidenav__link {
        --kp-sidenav-submenu-mark: '▪';
    }
}

/* ── Signature [scope-140] ─────────────────────────────────────────────── */
/* brutalism's approved signature (Kenny, 2026-10-03, three review rounds): the
   progress bar and the ten elements (spinner, skeleton, switch, check and
   radio, toast, dialog, tooltip, wizard steps, empty state, link hover),
   ported once from research/progress-signature/themes/brutalism.css and research/signature-elements/themes/brutalism.css
   and maintained here from now on. In kp.signature, which css/themes.css
   orders after kp.register, so it draws over the register exactly as the
   approved demos did, whatever the weight of a register selector.

   Since 2026-10-07 23:44 the layer speaks the grammar Kenny decided on
   research/brutalism-character (themes/brutalism/CHARACTER.md, G1-G18):
   everything that happens is something weight does. What arrives is dropped
   onto its footprint from up-left and stops dead; what leaves is lifted off
   it; what is pointed at is inverted; what waits is a lintel hoisted in
   hard lifts; a new value is slammed onto its yellow offset; a warning is
   taped off. The tokens below are the grammar's, once; every rule reads
   them and names no number of its own. */
@layer kp.signature {
    [data-theme='brutalism'] {
        --kp-sig-br-drop: var(--kp-drop, 6px);
        /* G1: gravity. What comes falls on the meter's own Thrown on curve
           (it leaves at rest and lands at full speed); what goes is lifted
           on the same curve played back (1 - f(1 - t), so a leave is its
           arrival, frame for frame). */
        --kp-sig-br-fall: cubic-bezier(0.6, 0, 0.9, 0.5);
        --kp-sig-br-up: cubic-bezier(0.1, 0.5, 0.4, 1);
        /* G4: durations count the register's 100 ms (--fx-duration). Contact
           is 1 unit; a fall, an arrival and a leave 3; the dialog, the big
           slab, 15; a loop 12; the progress bar's walk 8 and its loop 24.
           Literals, because js/motion.js reads them as strings. */
        --kp-sig-br-time: 300ms;
        --kp-sig-br-dialog: 1500ms;
        --kp-sig-br-loop: 1200ms;
        --kp-sig-br-bar-time: 800ms;
        --kp-sig-br-bar-loop: 2400ms;
        /* js/motion.js: a close is its open turned around, so its time is the
           dialog's; a box eases to a new size in a fall. */
        --kp-close-max: var(--kp-sig-br-dialog);
        --kp-size-max: var(--kp-sig-br-time);
        /* G3, G12: how far a part is held up-left off its footprint, by size:
           a plate falls from 1.5 rem, the big slab from 2.5 rem, a small
           part from 0.75 rem, a row or a card lifted off from 1 rem. */
        --kp-sig-br-h-plate: 1.5rem;
        --kp-sig-br-h-slab: 2.5rem;
        --kp-sig-br-h-part: 0.75rem;
        --kp-sig-br-h-leave: 1rem;
        /* G10: the lintel, three gradient layers (the beam, two cables) on a
           picture twice the well's height; position-x 50%, 21%, 79%. */
        --kp-sig-br-cable: max(2px, 0.16rem);
        --kp-sig-br-lintel:
            linear-gradient(to bottom, transparent calc(100% - max(3px, 11%)), var(--border-strong) 0),
            linear-gradient(var(--border-strong), var(--border-strong)), linear-gradient(var(--border-strong), var(--border-strong));
        --kp-sig-br-lintel-size: 76% 200%, var(--kp-sig-br-cable) 200%, var(--kp-sig-br-cable) 200%;
    }

    /* ── The progress bar: Ruled and labelled, a lot slower [G10; Kenny,
       2026-10-07 23:44, research/brutalism-character "progress = ruled-slowest"].
       Ink ticks on the empty track, paper ticks cut through the ink fill,
       tenth by tenth; the yellow head is the tip and prints the share in
       Archivo Black. A share walks to its value in ten hard steps of 80 ms
       (a rise on `steps(10, jump-end)`, a fall on its mirror `jump-start`,
       so a shrink is the growth reversed); busy, the tip hops tick to tick
       in ten hard steps of the 2400 ms loop and prints three dots. ── */
    [data-theme='brutalism'] .kp-progressbar {
        --kp-progressbar-height: calc(1.375rem * var(--kp-progressbar-scale, 1));
        --br-line: var(--kp-line, 3px);
        --br-drop: calc(4px * var(--kp-progressbar-scale, 1));
        --br-ink: var(--border-strong);
        --br-u: calc(1px * var(--kp-progressbar-scale, 1));
        --br-fs: calc(0.85rem * var(--kp-progressbar-scale, 1));
        --br-hw: calc(3.7 * var(--br-fs) + 2 * var(--br-line));
        /* Two copies of the value walk to it, one on each mirror of the steps;
           the share is the lower of them: a rise follows the one that lags, a
           fall the one that leads. */
        --kp-sig-br-lag: var(--kp-value, 0);
        --kp-sig-br-lead: var(--kp-value, 0);
        --kp-sig-br-share: min(var(--kp-sig-br-lag), var(--kp-sig-br-lead));
    }

    [data-theme='brutalism'] .kp-progressbar__track {
        inset: 0 var(--br-drop) var(--br-drop) 0;
        border: var(--br-line) solid var(--br-ink);
        border-radius: 0;
        background:
            repeating-linear-gradient(90deg, transparent 0 calc(10% - 2 * var(--br-u)), var(--br-ink) calc(10% - 2 * var(--br-u)) 10%) 0 100% /
                100% 40% no-repeat,
            var(--card);
        box-shadow: var(--br-drop) var(--br-drop) 0 0 var(--br-ink);
    }

    [data-theme='brutalism'] .kp-progressbar__fill {
        background: repeating-linear-gradient(90deg, var(--br-ink) 0 calc(10% - 2 * var(--br-u)), var(--card) calc(10% - 2 * var(--br-u)) 10%);
        clip-path: inset(0 calc((1 - var(--kp-sig-br-share)) * 100%) 0 0);
        transition: none;
    }

    [data-theme='brutalism'] .kp-progressbar__head {
        box-sizing: border-box;
        display: grid;
        place-items: center;
        inline-size: var(--br-hw);
        margin-inline-start: 0;
        counter-reset: kp-sig-br-pct calc(var(--kp-sig-br-share) * 100);
        background: var(--secondary);
        border-inline: var(--br-line) solid var(--br-ink);
        color: var(--secondary-foreground);
        font-family: var(--theme-font-display);
        font-size: var(--br-fs);
        font-weight: 800;
        font-variant-numeric: tabular-nums;
        line-height: 1;
        white-space: nowrap;
        /* The tip rides the share's edge, held inside the track so it is
           never cut at 0 or at 100 %. */
        transform: translateX(max(0px, calc(var(--kp-sig-br-share) * 100cqi - var(--br-hw))));
        transition: none;
    }

    [data-theme='brutalism'] .kp-progressbar__head::after {
        content: counter(kp-sig-br-pct) '%';
    }

    [data-theme='brutalism'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
        inset: 0;
        inline-size: auto;
        clip-path: inset(0 100% 0 0);
        animation: none;
    }

    [data-theme='brutalism'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__head {
        display: grid;
        transform: none;
    }

    [data-theme='brutalism'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__head::after {
        content: '…';
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='brutalism'] .kp-progressbar {
            transition:
                --kp-sig-br-lag var(--kp-sig-br-bar-time) steps(10, jump-end),
                --kp-sig-br-lead var(--kp-sig-br-bar-time) steps(10, jump-start);
        }

        [data-theme='brutalism'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__head {
            animation: kp-progressbar-brutalism-hop var(--kp-sig-br-bar-loop) linear infinite;
        }
    }

    /* The tip hops tick to tick in ten hard steps over two thirds of the
       loop, then is back at the start in one cut. */
    @keyframes kp-progressbar-brutalism-hop {
        0% {
            translate: 0 0;
            animation-timing-function: steps(10, jump-end);
        }

        66.667% {
            translate: calc(100cqi - var(--br-hw)) 0;
            animation-timing-function: steps(1, end);
        }

        83.333%,
        100% {
            translate: 0 0;
        }
    }

    /* ── The spinner: the block tipped over [G11]. The yellow block is lifted
       off its footprint, turned a quarter and set down: lifted on the
       lifting curve, turned, set down on the fall, stopping dead; 12 units. ── */
    [data-theme='brutalism'] .kp-spinner {
        --kp-sig-dur: var(--kp-sig-br-loop);
        position: relative;
        border: 0;
        border-radius: 0;
        background: none;
        animation: none;
    }

    [data-theme='brutalism'] .kp-spinner::before,
    [data-theme='brutalism'] .kp-spinner::after {
        content: '';
        position: absolute;
        inset: 2px 4px 4px 2px;
    }

    [data-theme='brutalism'] .kp-spinner::before {
        background: var(--border-strong);
        translate: 3px 3px;
    }

    [data-theme='brutalism'] .kp-spinner::after {
        border: 2px solid var(--border-strong);
        background: var(--secondary);
    }

    /* ── Loading is the lintel hoisted [G10; Kenny, 2026-10-07 23:44,
       "loading = hoist-lintel"]. While a part waits, the place its reading
       will stand is a well in the ink line, and in it one beam as wide as
       the well, on two cables, is hoisted in four hard lifts, held, let go
       to fall free on the fall curve and left to rest: 12 units, 1200 ms.
       The well is the skeleton itself, a loading meter's track, and a strip
       at the foot of a busy panel, button, card, menu entry or calendar;
       its words stand above it. The lintel is three gradient layers on a
       picture twice the well's height, so a lift is one number: the
       picture's vertical position, 100 % at rest (beam on the floor) to
       161.6 % (the beam 61.6 % of the well up, as the demo's -280 % of a
       22 % beam). Standing still it rests on the floor. ── */
    [data-theme='brutalism'] .kp-skeleton,
    [data-theme='brutalism']
        :is(
            .kp-datatable__busy-panel,
            .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading],
            .kp-button[aria-busy='true'],
            .kp-card[aria-busy='true'],
            .kp-calendar--busy-whole > .kp-calendar__busy
        )::before,
    [data-theme='brutalism'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        background-color: var(--card);
        background-image: var(--kp-sig-br-lintel);
        background-size: var(--kp-sig-br-lintel-size);
        background-position-x: 50%, 21%, 79%;
        background-position-y: 100%;
        background-repeat: no-repeat;
    }

    /* The skeleton lines: a well of one line's height on a 3 px footprint,
       two units apart. */
