       dead; a quarter turn is the same block, so the loop is seamless. */
    @keyframes kp-sig-brutalism-tip {
        0% {
            transform: none;
            animation-timing-function: var(--kp-sig-br-up);
        }

        25% {
            transform: translate(-3px, -3px);
            animation-timing-function: linear;
        }

        60% {
            transform: translate(-3px, -3px) rotate(90deg);
