    @keyframes kp-sig-brutalism-leave-slab {
        from {
            translate: 0 0;
            box-shadow: var(--kp-sig-br-sh) var(--kp-sig-br-sh) 0 0 var(--border-strong);
        }

        to {
            translate: calc(-1 * var(--kp-sig-br-h)) calc(-1 * var(--kp-sig-br-h));
            box-shadow: calc(var(--kp-sig-br-sh) + var(--kp-sig-br-h)) calc(var(--kp-sig-br-sh) + var(--kp-sig-br-h)) 0 0 var(--border-strong);
            visibility: hidden;
        }
