    [data-theme='pastel'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack,
    [data-theme='pastel'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:is(:hover, :focus-visible):not(:disabled),
    [data-theme='pastel'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:active:not(:disabled) {
        border-color: var(--primary);
        background: var(--primary);
        color: var(--primary-foreground);
        font-family: var(--theme-font-body);
