        text-transform: none;
        text-shadow: none;
    }

    [data-theme='pastel'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep,
    [data-theme='pastel'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep:is(:hover, :focus-visible):not(:disabled) {
