    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-alarm:not([data-kp-alarm-motion='still']),
        [data-theme='pastel'] .kp-alarm:not([data-kp-alarm-motion='still'])::after,
        [data-theme='pastel'] .kp-alarm:not([data-kp-alarm-motion='still']) :is(.kp-alarm__panel, .kp-alarm__title, .kp-alarm__detail) {
