        /* ── pastel: a balloon let go: it floats up with a little tilt ── */
        /* Opening is closing turned around (Kenny's pick on research/open-reverse,
           2026-10-05): js/motion.js opens the dialog as its close played backwards,
           in the close's time, and lets what arrives play this leave backwards. */
        [data-theme='pastel'] {
            --kp-open: reverse-close;
        }

        [data-theme='pastel'] [data-kp-leaving] {
            animation: kp-sig-pastel-leave 520ms cubic-bezier(0.4, 0, 1, 1) forwards;
        }

        @keyframes kp-sig-pastel-leave {
            to {
                transform: translateY(-28px) rotate(-5deg);
                opacity: 0;
            }
        }
    }

    /* ── The meter with a mark, this theme's way [picked by Kenny on
       research/character-meter, round 3, 2026-10-05: shape 1, while
       loading 1, how the share arrives 3, when the tone changes 1,
       the mark past the end 2]. The package's own markup and states
       (setMeter(), js/kpi.js): the track on the meter, the share on ::before,
       the sign past the end or the loading picture on ::after, the mark
       `.kp-meter__mark`. Every animation and transition under
       prefers-reduced-motion: no-preference; still frames otherwise. ── */

    /* The shared part: room past the end, loading without the pulse, the mark
       centred on its width, the package's signs cleared for the shape's own.
       Under :where() so each picked rule below wins as it did in the demo. */
    :where([data-theme='pastel']) :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-room: 0.625rem;
        box-sizing: border-box;
    }

    :where([data-theme='pastel']) .kp-meter--inline {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-sig-meter-room));
    }

    /* Each character draws its own loading picture instead of the pulse. */
    :where([data-theme='pastel']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: clip;
        animation: none;
    }

    :where([data-theme='pastel']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    /* The mark is centred on its share, whatever its width. */
    :where([data-theme='pastel']) .kp-meter__mark {
        --kp-sig-meter-mw: 2px;
        box-sizing: border-box;
        inline-size: var(--kp-sig-meter-mw);
        inset-inline-start: calc(clamp(0, var(--kp-mark, 0), 1) * 100% - var(--kp-sig-meter-mw) / 2);
    }

    :where([data-theme='pastel']) .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - 0.75rem);
    }

    /* The sign past the end, cleared of the package's ▸ for each character
       to draw its own. */
    :where([data-theme='pastel']) :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '';
        position: absolute;
        inset: auto;
        translate: none;
        color: inherit;
        font-size: 0.75rem;
        line-height: 1;
        text-shadow: none;
        white-space: nowrap;
        pointer-events: none;
    }

    /* A mark past the end keeps the package's sign inside the bar's end, in
       each character's own glyph and ink. */
    :where([data-theme='pastel']) .kp-meter__mark[data-kp-over]::after {
        content: var(--kp-sig-meter-mo-sign, '▸');
        color: var(--kp-sig-meter-mo-ink, var(--foreground));
        font-family: var(--kp-sig-meter-mo-font, inherit);
        text-shadow:
            0 0 1px var(--kp-sig-meter-mo-halo, var(--card)),
            0 0 2px var(--kp-sig-meter-mo-halo, var(--card));
    }

    /* ── shape: option 1 ── */

    /* ── pastel · washi tape ──────────────────────────────────────── */
    [data-theme='pastel'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-meter-height: 0.625rem;
        --kp-sig-meter-room: 0.75rem;
        --kp-sig-meter-mo-ink: var(--primary);
        border-radius: 999px;
        background:
            radial-gradient(circle, hsl(from var(--border-strong) h s l / 0.4) 0 0.75px, transparent 1.25px) 0 0 / 4px 4px,
            var(--muted);
        box-shadow: inset 0 0 0 1px hsl(from var(--border-strong) h s l / 0.5);
    }

    /* Plum tape with white stripes, the sky second pass off register under
       it, the far end torn. */
    [data-theme='pastel'] :is(.kp-meter, .kp-kpi__meter)::before {
        inset-block: 1px;
        border-radius: 999px 0 0 999px;
        background:
            repeating-linear-gradient(-45deg, hsl(from var(--card) h s l / 0.3) 0 2px, transparent 2px 5px) 0 0 / calc(100% - 2px) calc(100% - 2px)
                no-repeat,
            linear-gradient(var(--kp-meter-fill-colour), var(--kp-meter-fill-colour)) 0 0 / calc(100% - 2px) calc(100% - 2px) no-repeat,
            var(--fx-overprint);
        clip-path: polygon(0 0, calc(100% - 3px) 0, 100% 20%, calc(100% - 3px) 40%, 100% 60%, calc(100% - 3px) 80%, 100% 100%, 0 100%);
    }

    /* A round sticker on a pin. */
    [data-theme='pastel'] .kp-meter__mark {
        inset-block: -2px;
        border-radius: 1px;
        background: var(--foreground);
        box-shadow: 0 0 0 1px var(--card);
    }

    [data-theme='pastel'] .kp-meter__mark::before {
        content: '';
        position: absolute;
        inset-block-end: calc(100% - 1px);
        inset-inline-start: 50%;
        inline-size: 9px;
        block-size: 9px;
        translate: -50% 0;
        border-radius: 50%;
        background: var(--card);
        box-shadow:
            inset 0 0 0 2px var(--primary),
            1px 1px 0 var(--primary);
    }

    /* The tape runs over and its corner curls. */
    [data-theme='pastel'] :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        inset-inline-start: calc(100% + 1px);
        inset-block: 1px;
        inline-size: 0.5rem;
        background: linear-gradient(225deg, transparent 0 32%, var(--fx-overprint) 32% 50%, var(--kp-meter-fill-colour) 50%);
    }

    /* ── while loading: option 1 ── */

    /* A pale tape drifts along. */
    [data-theme='pastel'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        inset-block: 1px;
        inset-inline: -14.1421px 0;
        background: repeating-linear-gradient(-45deg, hsl(from var(--primary) h s l / 0.3) 0 2px, transparent 2px 10px);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
            animation: kp-sig-pastel-meter-drift 1600ms linear infinite;
        }
    }

    /* ── how the share arrives: option 3 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] :is(.kp-meter, .kp-kpi__meter)::before {
            animation: kp-sig-pastel-meter-drop-o 600ms cubic-bezier(0.3, 1.5, 0.5, 1) backwards;
            transition: inline-size 600ms cubic-bezier(0.3, 1.5, 0.5, 1);
        }
    }

    /* ── when the tone changes: option 1 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='warning']::before {
            animation-name: kp-sig-pastel-meter-drop-w;
        }

        [data-theme='pastel'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='destructive']::before {
            animation-name: kp-sig-pastel-meter-drop-d;
        }
    }

    /* ── the mark past the end: option 2 ── */

    [data-theme='pastel'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-mo-sign: '♥';
    }

    [data-theme='pastel'] .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - var(--kp-sig-meter-mw) - 1px);
        rotate: 24deg;
        transform-origin: 50% 100%;
    }

    [data-theme='pastel'] .kp-meter__mark[data-kp-over]::after {
        inset-inline-start: calc(100% + 3px);
        rotate: -24deg;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-meter__mark {
            transition:
                inset-inline-start 700ms cubic-bezier(0.3, 1.7, 0.5, 1),
                rotate 700ms cubic-bezier(0.3, 1.7, 0.5, 1);
        }
    }

    @keyframes kp-sig-pastel-meter-drift {
        0% {
            translate: 0 0;
        }

        100% {
            translate: 14.1421px 0;
        }
    }

    @keyframes kp-sig-pastel-meter-drop-d {
        0% {
            translate: 0 -160%;
        }

        100% {
            translate: 0 0;
        }
    }

    @keyframes kp-sig-pastel-meter-drop-o {
        0% {
            translate: 0 -160%;
        }

        100% {
            translate: 0 0;
        }
    }

    @keyframes kp-sig-pastel-meter-drop-w {
        0% {
            translate: 0 -160%;
        }

        100% {
