    [data-theme='forest'] .kp-field__check[type='checkbox']:checked::before {
        content: '';
        inline-size: 0.62rem;
        block-size: 0.32rem;
        border-inline-start: 2px solid var(--primary-foreground);
        border-block-end: 2px solid var(--primary-foreground);
