    [data-theme='forest'] .kp-tooltip::before {
        content: '';
        position: absolute;
        inset-block-end: 100%;
        inset-inline-start: 1rem;
        inline-size: 10px;
        block-size: 6px;
        background: var(--primary);
        clip-path: polygon(50% 0, 100% 100%, 0 100%);
    }

    [data-theme='forest'] .kp-wizard__steps {
        gap: 0.6rem 0;
    }

    [data-theme='forest'] .kp-wizard__steps li {
        gap: 0.45rem;
    }

    [data-theme='forest'] .kp-wizard__steps li:not(:last-child)::after {
        content: '';
        inline-size: 1.4rem;
        block-size: 2px;
        margin-inline: 0.3rem;
        background: repeating-linear-gradient(90deg, hsl(from var(--accent-foreground) h s l / 0.55) 0 4px, transparent 4px 7px);
    }

    [data-theme='forest'] .kp-wizard__steps li[data-state='done']::after {
