    }

    [data-theme='forest'] .kp-wizard__steps li::before {
        inline-size: 1.6rem;
        block-size: 1.6rem;
        border: 1px solid var(--border-strong);
        background: var(--card);
        box-sizing: border-box;
    }

    [data-theme='forest'] .kp-wizard__steps li[data-state='done']::before {
