        clip-path: inset(0 var(--kp-fo-margin) 0 var(--kp-fo-margin));
    }

    [data-theme='forest']
        :is(
            .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block),
            .kp-meter[data-kp-loading],
            .kp-kpi__meter[data-kp-loading],
            .kp-datatable__busy-panel,
            .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading],
            .kp-button[aria-busy='true'],
            .kp-card[aria-busy='true'],
            .kp-calendar--busy-whole > .kp-calendar__busy
        )::after {
        background: var(--primary);
        mask: var(--kp-fo-trees) 50% 0 / calc(var(--kp-fo-pitch) * 7) 100% repeat-x;
        clip-path: inset(0 calc(100% - var(--kp-fo-edge)) 0 var(--kp-fo-margin));
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest']
            :is(
                .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block),
                .kp-meter[data-kp-loading],
                .kp-kpi__meter[data-kp-loading],
                .kp-datatable__busy-panel,
                .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading],
                .kp-button[aria-busy='true'],
                .kp-card[aria-busy='true'],
                .kp-calendar--busy-whole > .kp-calendar__busy
            ) {
            animation: kp-progressbar-forest-breath 6600ms linear infinite;
        }

        /* Lines of a skeleton stand 400 ms apart. */
        [data-theme='forest'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block):nth-child(2) {
            animation-delay: calc(-5 * var(--kp-sig-fo-stagger));
        }

        [data-theme='forest'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block):nth-child(3) {
            animation-delay: calc(-10 * var(--kp-sig-fo-stagger));
        }
    }

    /* Standing still, the strip is the bar's own reduced pose: half the row. */
    @media (prefers-reduced-motion: reduce) {
        [data-theme='forest']
            :is(
                .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block),
                .kp-meter[data-kp-loading],
                .kp-kpi__meter[data-kp-loading],
                .kp-datatable__busy-panel,
                .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading],
