            .kp-split,
            .kp-grid__tile,
            .kp-upload__zone,
            .kp-upload__file,
            .kp-reorder [data-kp-item],
            .kp-fieldset,
            .kp-datatable,
            .kp-wizard,
            .kp-datatable__busy-panel,
            .kp-calendar--busy-whole > .kp-calendar__busy,
            .kp-chart__plot,
            .kp-chart__state,
            .kp-chart__tip
        ) {
        border-radius: var(--kp-sig-fo-plate);
    }

    [data-theme='forest']
        :is(
            .kp-button,
            .kp-icon-button,
            .kp-badge,
            .kp-tag,
            .kp-field__input,
            .kp-combobox__input,
            .kp-datatable__search,
            .kp-menu__item,
            .kp-combobox__option,
            .kp-palette__option,
            .kp-nav__toggle,
            .kp-nav__search-trigger,
            .kp-skip-link,
            .kp-kpi__delta,
            .kp-kpi__link,
            .kp-chart__release,
            .kp-chart__delta[data-kp-direction],
            .kp-tooltip,
            .kp-help kbd,
            .kp-shortcuts__row kbd,
            .kp-field__check:not([type='radio'])
        ),
    [data-theme='forest'] .kp-card[data-kp-label]::before {
        border-radius: var(--kp-sig-fo-part);
    }

    [data-theme='forest'] .kp-switch {
        --kp-switch-radius: var(--kp-sig-fo-part);
    }

    /* ── Paper for plates, wood for instruments [G7; Kenny, 2026-10-07: the
       kit]. A plate is kraft card over the faint contour field, as the
       register draws it. What is held, a tag and a plain badge, is light
       wood: grain at 177 degrees, routed in, its words in the plain ink. A
       badge that names a state keeps the plate of its state. The wood the
       meter's gauge is made of is drawn with the meter. ── */
    [data-theme='forest'] :is(.kp-tag, .kp-badge:not([data-status], [class*='kp-badge--'])) {
        border-color: transparent;
        background-color: var(--muted);
        background-image: var(--kp-sig-fo-wood);
        box-shadow: var(--kp-sig-fo-routed);
        color: var(--foreground);
    }

    /* ── Notes are italic [G13; Kenny, 2026-10-07: type = notes]: what a
       ranger writes beside the figures, in the body face. Figures and titles
       stand upright; the mono face stays for identifiers, timestamps and log
       lines. The change on a tile is a field note: the arrows are the
       note's own (↑ and ↓). ── */
    [data-theme='forest']
        :is(.kp-kpi__delta, .kp-kpi__label, .kp-kpi__note, .kp-page-header__description, .kp-field__help, .kp-empty__body, .kp-chart__tick) {
        font-style: italic;
    }

    [data-theme='forest'] .kp-kpi__delta[data-kp-direction='up']::before {
        content: '↑\00a0';
    }

    [data-theme='forest'] .kp-kpi__delta[data-kp-direction='down']::before {
        content: '↓\00a0';
    }
}
