/* ── Signature [scope-140] ─────────────────────────────────────────────── */
/* deco's approved signature (Kenny, 2026-10-03, three review rounds): the
   progress bar and the ten elements (spinner, skeleton, switch, check and
   radio, toast, dialog, tooltip, wizard steps, empty state, link hover),
   ported once from research/progress-signature/themes/deco.css and research/signature-elements/themes/deco.css
   and maintained here from now on. In kp.signature, which css/themes.css
   orders after kp.register, so it draws over the register exactly as the
   approved demos did, whatever the weight of a register selector. */
@layer kp.signature {
    /* The link signature is for links in running text; a link in a navigation,
       a menu, a breadcrumb (a nav) or the footer keeps its own component's look
       (scope-93: no link colour in a navigation). */
    [data-theme='deco'] .kp-progressbar {
        --kp-progressbar-height: calc(1.125rem * var(--kp-progressbar-scale, 1));
        --dc-rib: calc(4px * var(--kp-progressbar-scale, 1));
        --dc-rib-pitch: calc(5px * var(--kp-progressbar-scale, 1));
        --dc-gold: var(--primary);
        --dc-flute: color-mix(in oklab, var(--primary) 72%, var(--background));
        --dc-tip: calc(0.45rem * var(--kp-progressbar-scale, 1));
        --dc-jewel: calc(0.4rem * var(--kp-progressbar-scale, 1));
        --dc-chevron: calc(0.8rem * var(--kp-progressbar-scale, 1));
    }

    [data-theme='deco'] .kp-progressbar__track {
        border: 3px double var(--border-strong);
        border-radius: 0;
        background: var(--background);
    }

    [data-theme='deco'] .kp-progressbar__fill {
        --dc-at: calc(var(--kp-value) * 100%);
        inset: 1px;
        background:
            linear-gradient(90deg, var(--dc-gold) 0 var(--dc-rib), var(--dc-flute) var(--dc-rib)) 0 0 / var(--dc-rib-pitch) 100% repeat-x,
            var(--dc-gold);
        clip-path: polygon(
            0 0,
            max(0px, calc(var(--dc-at) - var(--dc-tip))) 0,
            var(--dc-at) 50%,
            max(0px, calc(var(--dc-at) - var(--dc-tip))) 100%,
            0 100%,
            min(calc(var(--dc-tip) * 0.6), calc(var(--dc-at) * 0.5)) 50%
        );
        transition: clip-path 320ms var(--fx-ease, cubic-bezier(0.4, 0, 0.2, 1));
    }

    [data-theme='deco'] .kp-progressbar__head {
        inline-size: 0;
        transition: transform 320ms var(--fx-ease, cubic-bezier(0.4, 0, 0.2, 1));
    }

    [data-theme='deco'] .kp-progressbar__head::before {
        content: '';
        position: absolute;
        inset-block-start: 50%;
        inset-inline-start: calc(-1 * var(--dc-tip) - var(--dc-jewel) * 0.9);
        inline-size: var(--dc-jewel);
        block-size: var(--dc-jewel);
        background: var(--accent);
        box-shadow:
