            linear-gradient(to top left, transparent calc(50% - 1.5px), var(--dc-gold) calc(50% - 1.5px) calc(50% + 1px), transparent calc(50% + 1px))
                left bottom / var(--dc-chevron) 50% repeat-x;
    }

    @media (prefers-reduced-motion: no-preference) {
