        text-decoration-color: hsl(from var(--primary) h s l / 0.7);
        text-underline-offset: 0.25em;
    }

    [data-theme='deco'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a):hover {
        text-decoration-line: underline overline;
        text-decoration-color: var(--primary);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='deco'] .kp-spinner::before {
            animation: kp-sig-deco-deco-turn var(--kp-sig-dur) linear infinite;
        }

        [data-theme='deco'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)::before {
            animation: kp-sig-deco-deco-open var(--kp-sig-dur) var(--fx-ease) infinite;
        }

        [data-theme='deco'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block):nth-child(2)::before {
