            transform-origin: 50% 100%;
            animation: kp-sig-deco-deco-fan var(--kp-sig-dur) var(--fx-ease) backwards;
        }

        [data-theme='deco'] .kp-tooltip {
            animation: kp-sig-deco-deco-centre var(--kp-sig-dur) var(--fx-ease) backwards;
        }
    }

    @keyframes kp-sig-deco-deco-turn {
        to {
            transform: rotate(360deg);
        }
    }

    @keyframes kp-sig-deco-deco-open {
        0% {
            opacity: 1;
            transform: scaleX(0);
        }

        40%,
        75% {
            opacity: 1;
            transform: none;
        }

        100% {
            opacity: 0;
            transform: none;
        }
    }

    @keyframes kp-sig-deco-deco-unfold {
        from {
            clip-path: inset(50% 0);
        }

        to {
            clip-path: inset(0);
        }
    }

    @keyframes kp-sig-deco-deco-grow {
        from {
            transform: scale(0) rotate(-90deg);
        }
    }

    @keyframes kp-sig-deco-deco-centre {
        from {
            clip-path: inset(-12px 50%);
        }

        to {
            clip-path: inset(-12px 0);
        }
    }

    @keyframes kp-sig-deco-deco-sunrise {
        from {
            opacity: 0;
            transform: scaleY(0.82);
        }

        40% {
            opacity: 1;
        }
    }

    @keyframes kp-sig-deco-deco-fan {
        from {
            opacity: 0;
            transform: scale(0.15, 0.4);
        }

        35% {
            opacity: 0;
            transform: scale(0.15, 0.4);
        }
    }

    @keyframes kp-progressbar-deco-ascent {
        from {
            transform: translateX(0);
        }
        to {
            transform: translateX(var(--dc-chevron));
        }
    }

    /* Leaving, this theme's way [scope-142; picked by Kenny on research/size-motion,
       2026-10-04]. js/motion.js marks what leaves `[data-kp-leaving]`, closes its space during
       the exit, and in a row of leaves starts the next one halfway through this one. */
    @media (prefers-reduced-motion: no-preference) {
        /* ── deco: it closes like a fan, folding to its centre ── */
        /* Opening is closing turned around (Kenny's pick on research/open-reverse,
           2026-10-05): js/motion.js opens the dialog as its close played backwards,
           in the close's time, and lets what arrives play this leave backwards. */
        [data-theme='deco'] {
            --kp-open: reverse-close;
        }

        [data-theme='deco'] [data-kp-leaving] {
            animation: kp-sig-deco-leave 480ms cubic-bezier(0.4, 0, 0.2, 1) forwards;
        }

        @keyframes kp-sig-deco-leave {
            to {
                opacity: 0;
                transform: scaleX(0);
            }
        }
    }

    /* ── The meter with a mark, this theme's way [picked by Kenny on
       research/character-meter, round 3, 2026-10-05: shape 1, while
       loading 3, how the share arrives 2, when the tone changes 3,
       the mark past the end 3]. The package's own markup and states
       (setMeter(), js/kpi.js): the track on the meter, the share on ::before,
       the sign past the end or the loading picture on ::after, the mark
       `.kp-meter__mark`. Every animation and transition under
       prefers-reduced-motion: no-preference; still frames otherwise. ── */

    /* The shared part: room past the end, loading without the pulse, the mark
       centred on its width, the package's signs cleared for the shape's own.
       Under :where() so each picked rule below wins as it did in the demo. */
    :where([data-theme='deco']) :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-room: 0.625rem;
        box-sizing: border-box;
    }

    :where([data-theme='deco']) .kp-meter--inline {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-sig-meter-room));
    }

    /* Each character draws its own loading picture instead of the pulse. */
    :where([data-theme='deco']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: clip;
        animation: none;
    }

    :where([data-theme='deco']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    /* The mark is centred on its share, whatever its width. */
    :where([data-theme='deco']) .kp-meter__mark {
        --kp-sig-meter-mw: 2px;
        box-sizing: border-box;
        inline-size: var(--kp-sig-meter-mw);
