        }
    }

    @keyframes kp-sig-light-light-orbit {
        from {
            transform: rotate(0);
        }

        to {
            transform: rotate(1turn);
        }
    }

    @keyframes kp-sig-light-light-open-x {
        from {
            clip-path: inset(0 100% 0 0 round 999px);
        }

        to {
            clip-path: inset(0 0 0 0 round 999px);
        }
    }

    @keyframes kp-sig-light-light-tick {
        from {
            clip-path: inset(0 100% 0 0 round 2px);
        }

        to {
            clip-path: inset(0 0 0 0 round 2px);
        }
    }

    @keyframes kp-sig-light-light-bead {
        from {
            transform: scale(0);
        }
    }

    @keyframes kp-sig-light-light-window {
        from {
            opacity: 0;
            transform: translateY(6px);
            clip-path: inset(40% 30% round var(--radius));
        }

        40% {
            opacity: 1;
        }

        to {
            transform: none;
            clip-path: inset(-3rem round var(--radius));
        }
    }

    @keyframes kp-sig-light-light-float {
        from {
            opacity: 0;
            transform: translateY(4px) scale(0.96);
        }
    }

    /* Growing and shrinking, this theme's way [scope-142; approved by Kenny
       on research/size-motion, 2026-10-04]. js/motion.js marks a gliding box
       `[data-kp-resizing]` and what arrives in it `[data-kp-arriving]`. */
    @media (prefers-reduced-motion: no-preference) {
        /* ── light: daylight. The box brightens as it opens up, and new
           content blooms in out of the glare. ───────────────────────────── */
        [data-theme='light'] [data-kp-resizing] {
            filter: brightness(1.04) drop-shadow(0 0 14px hsl(from var(--primary) h s l / 0.28));
        }

        [data-theme='light'] [data-kp-arriving] {
            animation: kp-sig-light-size-bloom 420ms cubic-bezier(0.16, 1, 0.3, 1) backwards;
        }

        @keyframes kp-sig-light-size-bloom {
            from {
                opacity: 0;
                filter: blur(4px) brightness(1.4);
            }
        }
    }

    /* Leaving, this theme's way [scope-142; picked by Kenny on research/size-motion,
       2026-10-04]. js/motion.js marks what leaves `[data-kp-leaving]`, closes its space during
       the exit, and in a row of leaves starts the next one halfway through this one. */
    @media (prefers-reduced-motion: no-preference) {
        /* ── light: it rises into the light and is gone in the glare ── */
        /* Opening is closing turned around (Kenny's pick on research/open-reverse,
           2026-10-05): js/motion.js opens the dialog as its close played backwards,
           in the close's time, and lets what arrives play this leave backwards. */
        [data-theme='light'] {
            --kp-open: reverse-close;
        }

        [data-theme='light'] [data-kp-leaving] {
            animation: kp-sig-light-leave 420ms ease-in forwards;
        }

        @keyframes kp-sig-light-leave {
            to {
                opacity: 0;
                transform: translateY(-8px);
                filter: blur(5px) brightness(1.6);
            }
        }
    }

    /* ── The meter with a mark, this theme's way [picked by Kenny on
       research/character-meter, round 3, 2026-10-05: shape 1, while
       loading 1, how the share arrives 2, when the tone changes 2,
       the mark past the end 2]. The package's own markup and states
       (setMeter(), js/kpi.js): the track on the meter, the share on ::before,
       the sign past the end or the loading picture on ::after, the mark
       `.kp-meter__mark`. Every animation and transition under
       prefers-reduced-motion: no-preference; still frames otherwise. ── */

    /* The shared part: room past the end, loading without the pulse, the mark
       centred on its width, the package's signs cleared for the shape's own.
       Under :where() so each picked rule below wins as it did in the demo. */
    :where([data-theme='light']) :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-room: 0.625rem;
        box-sizing: border-box;
    }

    :where([data-theme='light']) .kp-meter--inline {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-sig-meter-room));
    }

    /* Each character draws its own loading picture instead of the pulse. */
    :where([data-theme='light']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: clip;
        animation: none;
    }

    :where([data-theme='light']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    /* The mark is centred on its share, whatever its width. */
    :where([data-theme='light']) .kp-meter__mark {
        --kp-sig-meter-mw: 2px;
        box-sizing: border-box;
        inline-size: var(--kp-sig-meter-mw);
        inset-inline-start: calc(clamp(0, var(--kp-mark, 0), 1) * 100% - var(--kp-sig-meter-mw) / 2);
    }

    :where([data-theme='light']) .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - 0.75rem);
    }

    /* The sign past the end, cleared of the package's ▸ for each character
       to draw its own. */
    :where([data-theme='light']) :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '';
        position: absolute;
        inset: auto;
        translate: none;
        color: inherit;
        font-size: 0.75rem;
        line-height: 1;
        text-shadow: none;
        white-space: nowrap;
        pointer-events: none;
    }

    /* A mark past the end keeps the package's sign inside the bar's end, in
       each character's own glyph and ink. */
    :where([data-theme='light']) .kp-meter__mark[data-kp-over]::after {
        content: var(--kp-sig-meter-mo-sign, '▸');
        color: var(--kp-sig-meter-mo-ink, var(--foreground));
        font-family: var(--kp-sig-meter-mo-font, inherit);
        text-shadow:
            0 0 1px var(--kp-sig-meter-mo-halo, var(--card)),
            0 0 2px var(--kp-sig-meter-mo-halo, var(--card));
    }

    /* ── shape: option 1 ── */

    /* ── light · daylight ─────────────────────────────────────────── */
    [data-theme='light'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-meter-height: 0.375rem;
        --kp-sig-meter-room: 1rem;
        border-radius: 999px;
        background: var(--muted);
        box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--border-strong) 40%, transparent);
    }

    /* The share brightens towards its end, where the sun is on it. */
    [data-theme='light'] :is(.kp-meter, .kp-kpi__meter)::before {
        border-radius: 999px;
        background:
            linear-gradient(to bottom, hsl(from var(--card) h s l / 0.35) 0 1px, transparent 1px),
            linear-gradient(
                90deg,
                var(--kp-meter-fill-colour) calc(100% - 1.5rem),
                color-mix(in oklab, var(--kp-meter-fill-colour) 62%, var(--fx-signal)) 100%
            );
    }

    /* The gnomon and its short shadow. */
    [data-theme='light'] .kp-meter__mark {
        inset-block: -4px;
        border-radius: 1px;
        background: var(--foreground);
        box-shadow:
            0 0 0 1px var(--card),
            3px 2px 3px hsl(from var(--foreground) h s l / 0.3);
    }

    /* The light spills out past the end in a glint. */
    [data-theme='light'] :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '✦';
        display: grid;
        place-items: center;
        inset-inline-start: calc(100% - 0.125rem);
        inset-block: -0.4375rem;
        inline-size: 1.125rem;
        border-radius: 50%;
        background: radial-gradient(closest-side, hsl(from var(--fx-signal) h s l / 0.4), transparent);
        color: var(--fx-signal);
        font-size: 0.75rem;
    }

    /* ── while loading: option 1 ── */

    [data-theme='light'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        inset-inline-end: auto;
        inline-size: 35%;
        background: linear-gradient(90deg, transparent, hsl(from var(--fx-signal) h s l / 0.45), transparent);
        translate: -100% 0;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
            animation: kp-sig-light-meter-day 3000ms ease-in-out infinite;
        }
    }

    @media (prefers-reduced-motion: reduce) {
        [data-theme='light'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
            translate: 90% 0;
        }
    }

    /* ── how the share arrives: option 2 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] :is(.kp-meter, .kp-kpi__meter)::before {
            animation: kp-sig-light-meter-grow-o 700ms cubic-bezier(0.2, 0.7, 0.2, 1) backwards;
            transition: inline-size 700ms cubic-bezier(0.2, 0.7, 0.2, 1);
            transform-origin: 0 50%;
        }
    }

    /* ── when the tone changes: option 2 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] :is(.kp-meter, .kp-kpi__meter):not([data-kp-loading], [data-kp-tone]) {
            animation: kp-sig-light-meter-bump-o 260ms ease-out;
        }

        [data-theme='light'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='warning']:not([data-kp-loading]) {
            animation: kp-sig-light-meter-bump-w 260ms ease-out;
        }

        [data-theme='light'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='destructive']:not([data-kp-loading]) {
            animation: kp-sig-light-meter-bump-d 260ms ease-out;
        }
    }

    /* ── the mark past the end: option 2 ── */

    [data-theme='light'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-mo-sign: '›';
    }

    [data-theme='light'] .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - var(--kp-sig-meter-mw) - 1px);
        rotate: 24deg;
        transform-origin: 50% 100%;
    }

    [data-theme='light'] .kp-meter__mark[data-kp-over]::after {
        inset-inline-start: calc(100% + 3px);
        rotate: -24deg;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] .kp-meter__mark {
            transition:
                inset-inline-start 600ms ease-in-out,
                rotate 600ms ease-in-out;
        }
    }

    @keyframes kp-sig-light-meter-day {
        0% {
            translate: -100% 0;
        }

        100% {
            translate: 290% 0;
        }
    }

    @keyframes kp-sig-light-meter-bump-d {
        0% {
            scale: 1;
        }

        40% {
            scale: 1.04 1.3;
        }

        100% {
            scale: 1;
        }
    }

    @keyframes kp-sig-light-meter-bump-o {
        0% {
            scale: 1;
        }

        40% {
            scale: 1.04 1.3;
        }

        100% {
            scale: 1;
        }
    }

    @keyframes kp-sig-light-meter-bump-w {
        0% {
            scale: 1;
        }

        40% {
            scale: 1.04 1.3;
        }

        100% {
            scale: 1;
        }
    }

    @keyframes kp-sig-light-meter-grow-o {
        0% {
            scale: 0 1;
        }

        100% {
            scale: 1 1;
        }
    }
}
/* ── End of the signature ── */

/* The red plate's polar position round the black ink: --kp-sig-gr-a is its
   angle (it only ever grows: screen y points down, so a growing angle is
   clockwise, in either text direction) and --kp-sig-gr-q its distance (1 the
   far point, 0 in register, where it is behind the ink and so not seen).
   Registered so the keyframes interpolate them; at the top level because
   Firefox does not register an @property inside a layer. */
@property --kp-sig-gr-a {
    syntax: '<angle>';
    inherits: false;
    initial-value: 0deg;
}

@property --kp-sig-gr-q {
    syntax: '<number>';
    inherits: false;
    initial-value: 0;
}

@layer kp.register {
    /* @kp-soft/themes — css/grotesk-register.css
   The grotesk register, 5.0.0 [S48, LIFT_PLAN row 12]: the International
   Typographic Style. Scoped to [data-theme='grotesk'] and inert
   elsewhere; opt-in, imported after themes.css. The approved concept
   demo ("Twelve Columns", 2026-09-08) is the reference for every value
   here, and its own inline research citations (Grilli Type, Hiroto Sato,
   PDR, Dead North) are where each mechanism was measured.

   Cyberpunk and phantom paint a place; grotesk paints a system. What this
   file does, in order: the knobs and the texture-adjacent tokens; the
   type; the hooks of S45 — the headline that comes into optical focus,
   the redaction bars a dossier's marks answer, the rule that draws under
   a heading, the double rule as a razor tear; the fourteen-column
   navbar; the asymmetric hero; the buttons, fields, windows; and one
   answer per component root (TH124). The reveals have their rest state
   here and their motion in js/effects.js; without the script every one
   of them stands at rest.

   Colour discipline (DI9): nothing here names a colour. The signal red
   is the only hue this register ever paints, and it is never used as a
   large fill — a rule, a hairline, a stamp, a label, never a plate the
   size of a button (the anatomy's rule: "one red, and it is text-safe").

   Nothing here flickers or loops: every gesture is one-shot — the
   headline's blur+brightness resolve, the rule's draw-in, the dossier's
   stepped cut, the button's colour swap, the dialog's open — and every
   one is guarded (DI7). The base layer's pre-round-six h1/h2 accent (a
   static red square before a heading, css/_rules.css) is suppressed
   inside a surface here: the approved demo's headings carry no such
   mark, and S49 asks for the demo's own appearance where the two
   conflict — see the anatomy's closing section. */

    [data-theme='grotesk'] {
        /* The month heatmap's nav goes on two rows below this width: the
           widest month and the three buttons in this type [fix-98]. */
        --kp-calendar-nav-fit: 22.5rem;
        /* The configuration surface [AR43], the demo's values as defaults. */
        --kp-reveal-threshold: 0.6;
        --kp-reveal-stagger: 240ms;
        --kp-classified-delay: 240ms;
        --kp-redact-stagger: 120ms;
        --kp-sharpen-blur: 14px;
        --kp-sharpen-bright: 0.35;
        --kp-rule-draw: 360ms;
        --kp-rule-delay: 600ms;
        --kp-redact-cut: 240ms;
        /* The reveals this theme performs [S45]: js/effects.js reads these
           and leaves a theme that declares none at rest. */
        --kp-reveal-headline: sharpen;
        --kp-reveal-emphasis: redact;
        --kp-reveal-rule: draw;
        --kp-mono: var(--theme-font-mono);
        /* The double rule as the razor tear [PDR, cross-cutting]: a
           one-pixel signal hairline exactly centred between two black
           rules. col-w stands in for the demo's --col-w (measure / 12),
           read off the twelve-column texture this theme already owns. */
        --kp-col-w: calc(100% / 12);
    }

    /* ── Type ──────────────────────────────────────────────────────────── */

    [data-theme='grotesk'] h1,
    [data-theme='grotesk'] h2,
    [data-theme='grotesk'] h3 {
        font-family: var(--theme-font-display);
        letter-spacing: -0.015em;
    }

    /* The base layer's red square before every h1/h2 (css/_rules.css) is
       Müller-Brockmann's mark and predates this round's demo, which shows
       no such glyph on a surface heading — S49's own worked case: the
       demo wins, and the appearance is kept here rather than by editing
       the shared base file. Outside a surface (docs, showcase) the mark
       still stands: only the demo's own elements are exempted. */
    [data-theme='grotesk'] [data-kp-surface] h1::before,
    [data-theme='grotesk'] [data-kp-surface] h2::before {
        content: none;
    }

    /* Microlabels: mono, uppercase, the signal colour — the demo's
       .microlabel is the one place outside the rule/mark that carries the
       red. */
    [data-theme='grotesk'] .microlabel {
        font-family: var(--kp-mono);
        font-size: 0.72rem;
        letter-spacing: 0.16em;
        text-transform: uppercase;
        color: var(--primary);
    }

    /* ── The hooks [S45]: the headline, the mark, the rule, the divider ── */

    /* The headline reveal: Hiroto Sato's blur+brightness resolve [B §4],
       a one-shot optical arrival rather than a typographic one (no
       decipher, no type-in — those belong to terminal and phantom). At
       rest (armed but before the class arrives, or without the script)
       the headline is simply its text; while .is-sharpening the filter
       sweeps from dim and unfocused to full, once. */
    [data-theme='grotesk'][data-kp-effects] [data-kp-reveal='headline'].is-sharpening {
        filter: blur(var(--kp-sharpen-blur)) brightness(var(--kp-sharpen-bright));
    }

    /* The rule: Grilli's own two-speed timing has no equivalent for a
       drawn rule, so this reuses the base layer's kp-rule-in keyframe
       (shared by formal, blueprint, deco, academia) at the demo's own
       360ms/600ms-delay/linear (units of 120 ms) — a caesura in the grid,
       not a new mechanism. */
    [data-theme='grotesk'] [data-kp-reveal='rule'] {
        position: relative;
        padding-block-end: 0.5rem;
    }

    [data-theme='grotesk'] [data-kp-reveal='rule']::after {
        content: '';
        position: absolute;
        inset-block-end: 0;
        inset-inline-start: 0;
        block-size: 3px;
        inline-size: 3.5rem;
        background: var(--primary);
        transform: scaleX(1);
        transform-origin: left;
    }

    [data-theme='grotesk'][data-kp-effects] [data-kp-reveal='rule']:not(.is-in)::after {
        transform: scaleX(0);
    }

    /* The mark: two answers, by context. The lede's are loose marks — the
       demo's .kp-lede mark is a static colour change, no reveal, no cut
       — so the general rule below never conditions on .is-cleared; the
       words simply read in signal, at rest and mid-session alike. The
       dossier's marks are Dead North's stepped, staggered redaction: an
       ink bar over the word until the trigger opens the file, then a
       three-step monotone cut, staggered ~90ms apart — a cut, not a
       fade, to match the anatomy's refusal of anything soft. */
    [data-theme='grotesk'] mark {
        background: none;
        color: var(--primary);
        font-weight: 700;
        padding: 0;
    }

    /* The bar is the phrase's own background, cloned onto every line the
       phrase takes, so a phrase that wraps is covered line by line [fix-33,
       scope-93]; a bar on an absolutely positioned ::after covered none of
       it. It reaches 0.05em above and below the words and 0.15em past each
       end as padding, room the words around it make, so no bar reaches past
       the line it sits on, and it is cut toward the phrase's end, as the scaled bar was. */
    [data-theme='grotesk'] .kp-card[data-kp-reveal='emphasis'] mark {
        position: relative;
        z-index: 0;
        color: var(--card-foreground);
        font-weight: 400;
        background: linear-gradient(var(--foreground), var(--foreground)) right center / 0% 100% no-repeat;
        padding: 0.05em 0.15em;
        box-decoration-break: clone;
        -webkit-box-decoration-break: clone;
    }

    [data-theme='grotesk'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared) {
        color: transparent;
        background-size: 100% 100%;
    }

    /* The divider: the double rule as razor tear [PDR, cross-cutting]: two
       black rules the width of the page with a one-pixel signal hairline
       exactly centred between them. The alt divider takes the same
       one-column caesura the demo's --col-w margin gives its second
       tear, expressed against the twelve-column texture this theme
       already declares (css/_rules.css). */
    [data-theme='grotesk'] [data-kp-divider] {
        position: relative;
        block-size: 1.35rem;
        border-block-start: 3px solid var(--foreground);
        border-block-end: 3px solid var(--foreground);
    }

    [data-theme='grotesk'] [data-kp-divider]::after {
        content: '';
        position: absolute;
        inset-inline: 0;
        inset-block-start: 50%;
        block-size: 1px;
        background: var(--primary);
        transform: translateY(-0.5px);
    }

    [data-theme='grotesk'] [data-kp-divider='alt'] {
        margin-inline-start: var(--kp-col-w);
    }

    /* ── The hero: the asymmetric column split [D grotesk R1] ──────────── */

    [data-theme='grotesk'] [data-kp-surface='hero'] {
        position: relative;
        padding-block: 3rem 3.5rem;
    }

    [data-theme='grotesk'] [data-kp-surface='hero'] [data-kp-hero-grid] {
        grid-template-columns: minmax(0, 3fr) minmax(0, 1fr);
        gap: 2.5rem;
        align-items: start;
    }

    @container (max-width: 58rem) {
        [data-theme='grotesk'] [data-kp-surface='hero'] [data-kp-hero-grid] {
            grid-template-columns: 1fr;
        }
    }

    /* The vertical margin note: the demo's own 2fr column, here the
       theme's side-note element, held in the margin in the mono face. */
    [data-theme='grotesk'] .kp-side-note {
        position: absolute;
        inset-block-start: 2.5rem;
        inset-inline-end: 0.5rem;
        writing-mode: vertical-rl;
        transform: rotate(180deg);
        font-family: var(--kp-mono);
        font-size: 0.72rem;
        letter-spacing: 0.14em;
        color: var(--muted-foreground);
        border-inline-start: 1px solid var(--border);
        padding-inline-start: 0.6rem;
    }

    @container (max-width: 58rem) {
        [data-theme='grotesk'] .kp-side-note {
            position: static;
            writing-mode: horizontal-tb;
            transform: none;
            border-inline-start: 0;
            border-block-start: 1px solid var(--border);
            padding-inline-start: 0;
            padding-block-start: 0.5rem;
            margin-block-end: 1rem;
        }
    }

    /* ── The navbar: Grilli's fourteen-column header track ─────────────── */

    [data-theme='grotesk'] .kp-nav-wrap {
        border-block-end: 3px solid var(--foreground);
    }

    [data-theme='grotesk'] .kp-nav {
        display: grid;
        grid-template-columns: repeat(14, 1fr);
        align-items: center;
        column-gap: 0.5rem;
        background: var(--background);
        border-block-end: 0;
    }

    @container kp-nav (max-width: 40rem) {
        [data-theme='grotesk'] .kp-nav {
            grid-template-columns: 1fr;
            row-gap: 0.75rem;
        }

        [data-theme='grotesk'] .kp-nav__brand,
        [data-theme='grotesk'] .kp-nav__links {
            grid-column: 1;
        }

        [data-theme='grotesk'] .kp-nav__links {
            flex-direction: column;
            align-items: flex-start;
            flex-wrap: nowrap;
            justify-content: flex-start;
        }
    }

    [data-theme='grotesk'] .kp-nav__brand {
        grid-column: 1 / 4;
        font-family: var(--theme-font-display);
        font-weight: 900;
        font-size: 1.15rem;
        letter-spacing: -0.01em;
        text-transform: uppercase;
        color: var(--foreground);
        white-space: nowrap;
    }

    /* The file code beside the wordmark [S49, A3]: signal mono, quiet. */
    [data-theme='grotesk'] .kp-nav__brand-tag {
        color: var(--primary);
        font-style: normal;
    }

    [data-theme='grotesk'] .kp-nav__links {
        grid-column: 4 / 15;
        justify-content: flex-end;
        gap: 1.5rem;
    }

    /* Grilli's two-speed link [D grotesk R1, measured]: .1s in, .15s out —
       "faster in than out". */
    [data-theme='grotesk'] .kp-nav__link {
        color: var(--muted-foreground);
        font-weight: 600;
        letter-spacing: 0.01em;
        background: none;
        border-radius: 0;
        transition-property: color;
        transition-duration: 0.1s;
        transition-timing-function: ease-out;
    }

    [data-theme='grotesk'] .kp-nav__link:hover,
    [data-theme='grotesk'] .kp-nav__link:focus-visible,
    [data-theme='grotesk'] .kp-nav__link[aria-current],
    [data-theme='grotesk'] .kp-nav__links > li:focus-within > .kp-nav__link {
        color: var(--foreground);
        background: none;
        box-shadow: none;
        transition-duration: 0.15s;
    }

    /* The keyboard keeps its ring [fix-38, DI2]: `box-shadow: none` above
       took the inner half off a focused link too, and the outer half is the
       page's own ground, so a Tab showed only the rule under the word. */
    [data-theme='grotesk'] .kp-nav__links > li > .kp-nav__link:focus-visible {
        box-shadow: 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring);
    }

    [data-theme='grotesk'] .kp-nav__link--lang {
        text-transform: uppercase;
    }

    [data-theme='grotesk'] .kp-nav__link--cta {
        color: var(--background);
        background: var(--foreground);
        padding-inline: 0.9rem;
        font-weight: 700;
    }

    [data-theme='grotesk'] .kp-nav__link--cta:hover,
    [data-theme='grotesk'] .kp-nav__link--cta:focus-visible {
        color: var(--background);
        background: var(--primary);
    }

    [data-theme='grotesk'] .kp-nav__link--cta:focus-visible {
        outline-color: var(--background);
    }

    /* The dropdown [KT14]: black-ruled, no shadow, the wash on a hovered
       item — opened and looked at before this register was called done. */
    [data-theme='grotesk'] .kp-nav__menu {
        background: var(--popover);
        border: 2px solid var(--foreground);
        border-radius: 0;
        box-shadow: none;
        padding-block: 0.4rem;
    }

    /* Collapsed, the dropdown is a list in the flow, not a panel [gap-12]:
       the rule above dresses the floating panel in kp.register, which
       beats the reset in kp.components, so the reset is restated here. */
    @container kp-nav (max-width: 40rem) {
        [data-theme='grotesk'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__menu {
            min-width: 0;
            padding-inline-start: var(--kp-nav-menu-indent, 1rem);
            border: 0;
            background: transparent;
            box-shadow: none;
        }
    }

    [data-theme='grotesk'] .kp-nav__menu a {
        color: var(--popover-foreground);
    }

    [data-theme='grotesk'] .kp-nav__menu a:hover,
    [data-theme='grotesk'] .kp-nav__menu a:focus-visible {
        background: var(--muted);
        color: var(--popover-foreground);
    }

    /* ── Buttons: right angles, a 2px ink line. Hovered, a red bar on the
       foot; focused, DI2's two-channel ring and the red plate falling in
       (the signature layer); pressed, the rule thickens [Kenny, 2026-10-07
       on research/grotesk-character: hover = a bar on the edge thickens,
       focus = the ring and the plate, press = the rule thickens, his
       scope-12, "I don't like the grey background it gives": a pressed part
       is never grey]. The bar and the ring are two custom properties laid
       in one box-shadow, so a hovered button that is also focused keeps both
       whatever the specificity of either rule. ──── */

    [data-theme='grotesk'] .kp-button {
        font-weight: 700;
        border: 2px solid var(--foreground);
        border-radius: 0;
        background: var(--background);
        color: var(--foreground);
    }

    [data-theme='grotesk'] :is(.kp-button, .kp-icon-button) {
        --kp-sig-gr-foot: 0 0 0 0 transparent;
        --kp-sig-gr-ring: 0 0 0 0 transparent;
        box-shadow: var(--kp-sig-gr-foot), var(--kp-sig-gr-ring);
    }

    [data-theme='grotesk'] .kp-button--primary {
        background: var(--primary);
        border-color: var(--primary);
        color: var(--primary-foreground);
    }

    [data-theme='grotesk'] .kp-button--destructive {
        background: var(--destructive);
        border-color: var(--destructive);
        color: var(--destructive-foreground);
    }

    /* The hover: a 3 px red bar along the foot, drawn inside the line (nothing
       moves, nothing beside it shifts), the ground the page's own. On a red
       face the bar is the ink, which the red face can show. The base layer's
       grey hover ground is painted over. */
    [data-theme='grotesk'] .kp-button:hover:not(:disabled) {
        background: var(--background);
    }

    [data-theme='grotesk'] .kp-button--primary:hover:not(:disabled) {
        background: var(--primary);
        border-color: var(--primary);
    }

    [data-theme='grotesk'] .kp-button--destructive:hover:not(:disabled) {
        background: var(--destructive);
        border-color: var(--destructive);
    }

    [data-theme='grotesk'] :is(.kp-button, .kp-icon-button):hover:not(:disabled, :active) {
        --kp-sig-gr-foot: inset 0 -3px 0 0 var(--primary);
    }

    [data-theme='grotesk'] :is(.kp-button--primary, .kp-button--destructive):hover:not(:disabled, :active) {
        --kp-sig-gr-foot: inset 0 -3px 0 0 var(--foreground);
    }

    /* The press, never grey [Kenny, 2026-10-07, over the grey face he had
       approved on 2026-09-14]: the paper face stays and the baseline under
       the words thickens (below, "The baseline"), and a red face deepens its
       red. Written out for every variant so the pressed state is this
       register's decision on the page [fix-12]. */
    [data-theme='grotesk'] .kp-button:active:not(:disabled) {
        background: var(--background);
        color: var(--foreground);
    }

    [data-theme='grotesk'] .kp-button--primary:active:not(:disabled) {
        background: var(--primary-active);
        border-color: var(--primary-active);
        color: var(--primary-foreground);
    }

    [data-theme='grotesk'] .kp-button--destructive:active:not(:disabled) {
        background: var(--destructive-active);
        border-color: var(--destructive-active);
        color: var(--destructive-foreground);
    }

    [data-theme='grotesk'] .kp-button--ghost {
        background: none;
        border-color: var(--border);
        color: var(--foreground);
    }

    [data-theme='grotesk'] .kp-button--ghost:hover,
    [data-theme='grotesk'] .kp-button--ghost:focus-visible,
    [data-theme='grotesk'] .kp-button--ghost:active:not(:disabled) {
        border-color: var(--foreground);
        background: none;
    }

    [data-theme='grotesk'] :is(.kp-button, .kp-icon-button):focus-visible {
        --kp-sig-gr-ring: 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring);
    }

    /* A filled button's outer ring can sit against a busy neighbour — a
       popover's own ink border, an adjacent menu item's ink text — close
       enough that the painted-pixel measurement (not only the declared
       CSS) cannot always tell the ring from what was already there (W4's
       dashboard test). The inset layer is the same two channels, drawn
       where nothing else in this theme ever paints ink: inside a filled
       button's own face. */
    [data-theme='grotesk'] .kp-button--primary:focus-visible,
    [data-theme='grotesk'] .kp-button--destructive:focus-visible {
        --kp-sig-gr-ring: 0 0 0 2px var(--focus-ring-contrast), 0 0 0 4px var(--focus-ring), inset 0 0 0 2px var(--focus-ring);
    }

    /* The demo's call-to-action row: wide buttons, as in the reference. A
       pager's or a menu's button keeps its own width (DI11 at 320px). */
    [data-theme='grotesk'] [data-kp-surface='hero'] .kp-row > .kp-button {
        min-width: min(12rem, 100%);
    }

    [data-theme='grotesk'] .kp-icon-button {
        border: 2px solid var(--border);
        border-radius: 0;
    }

    /* On an alert the close button sits on the alert's own plate, in the
       alert's ink, the way it does on a toast [fix-95]. */
    [data-theme='grotesk'] .kp-alert .kp-icon-button {
        background: transparent;
        border-color: transparent;
        color: inherit;
    }

    [data-theme='grotesk'] .kp-icon-button:hover:not(:disabled) {
        border-color: var(--foreground);
        background: var(--background);
    }

    /* ── Fields: the ruled well ───────────────────────────────────────── */

    [data-theme='grotesk'] .kp-field__label {
        font-weight: 700;
    }

    [data-theme='grotesk'] .kp-field__input {
        border: 2px solid var(--foreground);
        border-radius: 0;
        background: var(--background);
    }

    [data-theme='grotesk'] .kp-field__input:focus-visible {
        outline: none;
        border-color: var(--primary);
        box-shadow: 0 0 0 2px var(--focus-ring-contrast);
    }

    [data-theme='grotesk'] select.kp-field__input::picker-icon {
        color: var(--primary);
    }

    [data-theme='grotesk'] .kp-field__help {
        font-family: var(--kp-mono);
        color: var(--muted-foreground);
    }

    [data-theme='grotesk'] .kp-field--invalid .kp-field__input {
        border-color: var(--destructive);
    }

    [data-theme='grotesk'] .kp-field__error {
        font-family: var(--kp-mono);
        color: var(--destructive);
    }

    [data-theme='grotesk'] .kp-field__check:checked {
        background: var(--foreground);
        border-color: var(--foreground);
    }

    [data-theme='grotesk'] .kp-field__check:focus-visible {
        outline: none;
        box-shadow: 0 0 0 2px var(--focus-ring-contrast);
    }

    [data-theme='grotesk'] .kp-fieldset {
        border: 2px solid var(--border);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-switch__input:focus-visible {
        box-shadow: 0 0 0 2px var(--focus-ring-contrast);
    }

    [data-theme='grotesk'] .kp-form__summary {
        border-inline-start: 4px solid var(--primary);
        background: var(--muted);
        border-radius: 0;
    }

    /* ── Windows: dialog, popover, menu, toast, tooltip and the rest ────── */

    [data-theme='grotesk'] .kp-dialog,
    [data-theme='grotesk'] .kp-popover,
    [data-theme='grotesk'] .kp-menu,
    [data-theme='grotesk'] .kp-toast,
    [data-theme='grotesk'] .kp-tooltip,
    [data-theme='grotesk'] .kp-confirm,
    [data-theme='grotesk'] .kp-datepicker__panel,
    [data-theme='grotesk'] .kp-combobox__list,
    [data-theme='grotesk'] .kp-palette,
    [data-theme='grotesk'] .kp-theme-menu__list {
        background: var(--popover);
        border: 3px solid var(--foreground);
        border-radius: 0;
        box-shadow: none;
    }

    /* The wrapper round the theme picker's icon button is not a card: only its
       dropdown list is. */
    [data-theme='grotesk'] .kp-theme-menu {
        background: none;
        border: 0;
        box-shadow: none;
    }

    /* Severity toasts [scope-60]. The plain toast above is repainted here in
       a later layer than kp.components, which swallowed every variant's
       plate; each is restated on the alert's token pair, as the severity
       badge wears it. */
    [data-theme='grotesk'] .kp-toast--success {
        background: var(--success);
        color: var(--success-foreground);
        border-color: var(--success);
    }

    [data-theme='grotesk'] .kp-toast--info {
        background: var(--info);
        color: var(--info-foreground);
        border-color: var(--info);
    }

    [data-theme='grotesk'] .kp-toast--warning {
        background: var(--warning);
        color: var(--warning-foreground);
        border-color: var(--warning);
    }

    [data-theme='grotesk'] .kp-toast--destructive,
    [data-theme='grotesk'] .kp-toast--error {
        background: var(--destructive);
        color: var(--destructive-foreground);
        border-color: var(--destructive);
    }

    [data-theme='grotesk']
        :is(.kp-toast--success, .kp-toast--info, .kp-toast--warning, .kp-toast--destructive, .kp-toast--error)
        :is(.kp-button--ghost, .kp-icon-button) {
        color: inherit;
    }

    /* A button hovered on a toast takes a shade of the toast's own plate
       (--kp-toast-button-hover, set in kp.components), not this theme's page hover (Kenny's second nostromo pass,
       2026-09-13). Restated here because this layer repaints the hover; the
       :not()s match the length of this register's own button hover, which
       would otherwise win on specificity. */
    [data-theme='grotesk']
        .kp-toast
        :is(.kp-button--ghost, .kp-icon-button):hover:not(:disabled):not(:active):not(.kp-button--mirror):not(.kp-button--primary):not(
            .kp-button--destructive
        ) {
        background: var(--kp-toast-button-hover);
        color: inherit;
    }

    [data-theme='grotesk'] .kp-toasts {
        gap: 0.6rem;
    }

    /* A menu entry hovered gets a red bar along its top edge [hover = a bar on
       the edge], drawn inside the entry so nothing moves. */
    [data-theme='grotesk'] .kp-menu__item:hover {
        background: var(--popover);
        box-shadow: inset 0 2px 0 0 var(--primary);
    }

    /* The keyboard highlight: the wash, the ink keeps its own colour. */
    [data-theme='grotesk'] .kp-combobox__option[aria-selected='true'],
    [data-theme='grotesk'] .kp-palette__option[aria-selected='true'] {
        background: var(--muted);
    }

    /* The plain alert only [gap-1, Kenny 2026-09-10]. This rule used to
       repaint the ground of EVERY alert, and `kp.register` is a later layer
       than `kp.components`, so it beat `.kp-alert--destructive`'s own plate
       while that variant's ink — `--destructive-foreground`, which is drawn
       to sit ON the plate — stayed. Measured in firefox on 2026-09-12:
       seventeen of the twenty-two themes carried a destructive alert whose
       text was unreadable, grotesk at 1.00 exactly, white on white.

       Kenny saw it in chassis-rs and said to write it down and touch
       nothing; this is the round he asked for it in. Same shape as fix-12,
       one property over: a register overriding half of a pair the base
       layer defines together. */
    [data-theme='grotesk'] .kp-alert:not([class*='kp-alert--']) {
        background: var(--background);
        border: 2px solid var(--border);
        border-inline-start: 6px solid var(--accent);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-alert--destructive {
        border-inline-start-color: var(--destructive);
    }

    [data-theme='grotesk'] .kp-alert--warning {
        border-inline-start-color: var(--warning);
    }

    [data-theme='grotesk'] .kp-alert--success {
        border-inline-start-color: var(--success);
    }

    [data-theme='grotesk'] .kp-alert__label {
        font-family: var(--theme-font-display);
        font-weight: 700;
    }

    [data-theme='grotesk'] .kp-grid__tile,
    [data-theme='grotesk'] .kp-split__pane {
        background: var(--background);
        border: 2px solid var(--border);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-split__separator {
        background: var(--foreground);
        inline-size: 2px;
    }

    /* Top and bottom [gap-12]: the thickness above is an inline size, so
       a horizontal split takes the same value as a block size. */
    [data-theme='grotesk'] .kp-split[data-kp-orientation='horizontal'] > .kp-split__separator {
        inline-size: auto;
        block-size: 2px;
    }

    [data-theme='grotesk'] .kp-footer {
        background: var(--background);
        color: var(--muted-foreground);
    }

    [data-theme='grotesk'] .kp-footer h4 {
        font-family: var(--theme-font-display);
        font-weight: 800;
    }

    [data-theme='grotesk'] .kp-footer a {
        color: var(--muted-foreground);
        text-decoration: none;
        font-size: 0.88rem;
        transition-property: color;
        transition-duration: 0.1s;
        transition-timing-function: ease-out;
    }

    [data-theme='grotesk'] .kp-footer a:hover,
    [data-theme='grotesk'] .kp-footer a:focus-visible {
        color: var(--foreground);
        transition-duration: 0.15s;
    }

    /* ── The dossier stamp [S49, A11]: axis-aligned, right angles ───────── */

    [data-theme='grotesk'] .kp-card[data-kp-reveal='emphasis'] {
        position: relative;
    }

    [data-theme='grotesk'] .kp-card[data-kp-label]::before {
        content: attr(data-kp-label);
        position: absolute;
        inset-block-start: 0.7rem;
        inset-inline-end: 1.1rem;
        font-family: var(--kp-mono);
        font-size: 0.68rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--info);
        border: 1px solid var(--info);
        padding: 0.2rem 0.5rem;
    }

    /* The stamp changes when the file opens, as the demo's does [S49, A11]. */
    [data-theme='grotesk'] .kp-card[data-kp-open][data-kp-label-open]::before {
        content: attr(data-kp-label-open);
        color: var(--success);
        border-color: var(--success);
    }

    /* ── Badges, tags, status ────────────────────────────────────────── */

    /* The voice [Kenny, 2026-10-07 on research/grotesk-character: Archivo heavy
       and tight for titles and figures, Inter for the rest, in sentence case]:
       a badge and a tag speak Inter 700, no tracking, no capitals; the mono
       is for what a machine wrote. */
    [data-theme='grotesk'] .kp-badge,
    [data-theme='grotesk'] .kp-tag {
        border-radius: 0;
        font-family: var(--theme-font-body);
        font-weight: 700;
        letter-spacing: 0;
        text-transform: none;
    }

    /* The badge's type size is the package's [scope-87]; the tag keeps this register's. */
    [data-theme='grotesk'] .kp-tag {
        font-size: 0.75rem;
    }

    [data-theme='grotesk'] .kp-health__dot {
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-health {
        font-family: var(--kp-mono);
        font-size: 0.8rem;
    }

    [data-theme='grotesk'] .kp-skeleton {
        background: repeating-linear-gradient(90deg, var(--muted) 0 8px, var(--background) 8px 16px);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-spinner {
        border-color: var(--border);
        border-top-color: var(--primary);
    }

    [data-theme='grotesk'] .kp-error {
        font-family: var(--kp-mono);
        color: var(--destructive);
    }

    /* ── Text shapes: identifiers in the mono face ────────────────────── */

    [data-theme='grotesk'] .kp-id,
    [data-theme='grotesk'] .kp-url,
    [data-theme='grotesk'] .kp-numeric,
    [data-theme='grotesk'] .kp-timestamp,
    [data-theme='grotesk'] .kp-masked,
    [data-theme='grotesk'] .kp-copyable,
    [data-theme='grotesk'] .kp-truncate,
    [data-theme='grotesk'] .kp-cell-break,
    [data-theme='grotesk'] .kp-cell-truncate {
        font-family: var(--kp-mono);
        letter-spacing: 0.02em;
    }

    [data-theme='grotesk'] .kp-timestamp,
    [data-theme='grotesk'] .kp-id {
        color: var(--muted-foreground);
    }

    [data-theme='grotesk'] .kp-copyable__button {
        border: 2px solid var(--border);
        border-radius: 0;
    }

    /* The copy button's two states win over this register's own button
       rules [gap-12]: those paint in kp.register, which beats the states
       in kp.components, so copied lost its success plate and a refused
       copy looked idle. Restated token for token. */
    [data-theme='grotesk'] .kp-copyable .kp-copyable__button[data-kp-copied] {
        border-color: var(--success);
        color: var(--success-foreground);
        background: var(--success);
    }

    [data-theme='grotesk'] .kp-copyable .kp-copyable__button[data-kp-copy-failed] {
        border-color: var(--destructive);
        border-style: dashed;
        color: var(--destructive);
    }

    /* ── Data ─────────────────────────────────────────────────────────── */

    [data-theme='grotesk'] .kp-table {
        border-collapse: separate;
        border-spacing: 0;
    }

    [data-theme='grotesk'] .kp-table th {
        font-family: var(--theme-font-display);
        font-weight: 800;
        font-size: 0.9rem;
        letter-spacing: 0.02em;
        border-block-end: 3px solid var(--foreground);
    }

    [data-theme='grotesk'] .kp-table td {
        border-block-end: 1px solid var(--border);
    }

    [data-theme='grotesk'] .kp-table tbody tr:hover {
        background: var(--muted);
    }

    [data-theme='grotesk'] .kp-datatable {
        border: 2px solid var(--border);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-datatable__bar {
        border-block-end: 2px solid var(--border);
    }

    [data-theme='grotesk'] .kp-datatable__sort[aria-sort] {
        color: var(--primary);
    }

    [data-theme='grotesk'] .kp-datatable__status,
    [data-theme='grotesk'] .kp-datatable__page {
        font-family: var(--kp-mono);
        font-size: 0.75rem;
    }

    [data-theme='grotesk'] .kp-diff {
        border: 2px solid var(--border);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-diff__line {
        font-family: var(--kp-mono);
    }

    [data-theme='grotesk'] .kp-timeline {
        border-inline-start: 3px solid var(--foreground);
    }

    [data-theme='grotesk'] .kp-timeline__marker {
        background: var(--primary);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-timeline__when {
        font-family: var(--kp-mono);
        color: var(--muted-foreground);
        font-size: 0.75rem;
    }

    [data-theme='grotesk'] .kp-tree {
        font-family: var(--kp-mono);
    }

    /* The accordion [gap-12]: the display face its tabs are set in. */
    [data-theme='grotesk'] .kp-accordion__summary {
        font-family: var(--theme-font-display);
        font-weight: 700;
    }

    [data-theme='grotesk'] .kp-accordion__summary::marker {
        color: var(--primary);
    }

    [data-theme='grotesk'] .kp-accordion__item[open] > .kp-accordion__summary {
        color: var(--primary);
    }

    [data-theme='grotesk'] .kp-reorder {
        border: 2px solid var(--border);
        border-radius: 0;
    }

    /* ── Navigation and steps ─────────────────────────────────────────── */

    [data-theme='grotesk'] .kp-tab {
        font-family: var(--theme-font-display);
        font-weight: 700;
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-tab[aria-selected='true'] {
        color: var(--primary);
        box-shadow: inset 0 -3px 0 var(--primary);
    }

    [data-theme='grotesk'] .kp-tabs__list {
        border-block-end: 2px solid var(--border);
    }

    [data-theme='grotesk'] .kp-breadcrumb,
    [data-theme='grotesk'] .kp-pagination {
        font-family: var(--kp-mono);
    }

    [data-theme='grotesk'] .kp-pagination a[aria-current],
    [data-theme='grotesk'] .kp-pagination [aria-current] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-wizard__steps {
        font-family: var(--theme-font-display);
        font-weight: 700;
    }

    [data-theme='grotesk'] .kp-wizard {
        border: 2px solid var(--border);
        border-radius: 0;
    }

    /* ── Pickers and palettes ─────────────────────────────────────────── */

    [data-theme='grotesk'] .kp-combobox__input,
    [data-theme='grotesk'] .kp-palette__input,
    [data-theme='grotesk'] .kp-datatable__search {
        border: 2px solid var(--foreground);
        border-radius: 0;
        background: var(--background);
    }

    [data-theme='grotesk'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-datepicker__weekday,
    [data-theme='grotesk'] .kp-datepicker__title {
        font-family: var(--theme-font-display);
        font-weight: 700;
    }

    [data-theme='grotesk'] .kp-colorpicker__swatch {
        border: 1px solid var(--border);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-colorpicker__value {
        font-family: var(--kp-mono);
    }

    [data-theme='grotesk'] .kp-shortcuts__row kbd {
        font-family: var(--kp-mono);
        border: 1px solid var(--foreground);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-shortcuts__group-label,
    [data-theme='grotesk'] .kp-palette__group-label {
        font-family: var(--theme-font-display);
        font-weight: 700;
    }

    [data-theme='grotesk'] .kp-theme-menu__status,
    [data-theme='grotesk'] .kp-palette__status,
    [data-theme='grotesk'] .kp-combobox__status {
        font-family: var(--kp-mono);
        font-size: 0.75rem;
    }

    /* ── The roots the rules above reach only by their parts ──────────── */

    [data-theme='grotesk'] .kp-combobox,
    [data-theme='grotesk'] .kp-datepicker,
    [data-theme='grotesk'] .kp-colorpicker,
    [data-theme='grotesk'] .kp-shortcuts,
    [data-theme='grotesk'] .kp-tabs {
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-field {
        gap: calc(var(--kp-space-xs) * 1.4);
    }

    [data-theme='grotesk'] .kp-form {
        gap: var(--kp-space-lg);
    }

    [data-theme='grotesk'] .kp-grid {
        gap: 1rem;
    }

    [data-theme='grotesk'] .kp-split {
        gap: 0;
    }

    /* ── The demo's own pieces [S46] ──────────────────────────────────── */

    [data-theme='grotesk'] .kp-laurels {
        font-size: 0.85rem;
        color: var(--muted-foreground);
    }

    [data-theme='grotesk'] .kp-laurels b {
        display: block;
        color: var(--foreground);
        font-size: 0.95rem;
    }

    [data-theme='grotesk'] .kp-lede {
        max-width: 42rem;
    }

    [data-theme='grotesk'] .kp-platforms {
        font-family: var(--kp-mono);
        font-size: 0.78rem;
        color: var(--muted-foreground);
        letter-spacing: 0.03em;
    }

    /* The spec sheet: a black-ruled card, mono type for the values. */
    [data-theme='grotesk'] .kp-spec {
        border: 2px solid var(--foreground);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-spec dt {
        font-family: var(--kp-mono);
        font-size: 0.72rem;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    /* The log wears what this register already decided for its other data
 * surface, `.kp-spec` — the same ground, the same edge, the same face
 * [gap-14]. A new component that invents a look of its own is a
 * twenty-third decision nobody made. */
    [data-theme='grotesk'] .kp-log {
        border: 2px solid var(--foreground);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-log__level {
        font-family: var(--kp-mono);
        font-size: 0.72rem;
        text-transform: uppercase;
        --kp-log-level-ink: var(--muted-foreground);
    }

    [data-theme='grotesk'] .kp-spec dd {
        font-family: var(--kp-mono);
        font-size: 0.82rem;
    }

    [data-theme='grotesk'] .kp-spec__swatch {
        border: 1px solid var(--foreground);
    }

    [data-theme='grotesk'] .kp-spec__font {
        font-family: var(--theme-font-body);
    }

    /* ── The scrollbar joins the theme ────────────────────────────────── */

    [data-theme='grotesk'] {
        scrollbar-color: var(--foreground) var(--background);
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above are what they get. The
       durations are literal because check-motion.mjs computes DI5's rate
       from them; the matching --kp-* knobs are what js/effects.js reads. */
    @media (prefers-reduced-motion: no-preference) {
        /* (a) The headline's blur+brightness resolve: 600ms (five units), one-shot. */
        [data-theme='grotesk'][data-kp-effects] [data-kp-reveal='headline'].is-sharpening {
            animation: kp-sharpen-in 600ms linear forwards;
        }

        /* (c) The section rule draw-in: 360ms, delayed 600ms so it follows
           the headline settling — the demo's own reading. */
        [data-theme='grotesk'] [data-kp-reveal='rule']::after {
            transition: transform var(--kp-rule-draw) linear var(--kp-rule-delay);
        }

        /* (d) The redaction: a monotone three-step cut, staggered ~90ms. */
        /* The text switches from transparent to ink in no time, once the
           bar has finished cutting away (KT8: no mid-transition colour). */
        [data-theme='grotesk'] .kp-card[data-kp-reveal='emphasis'] mark {
            transition:
                background-size var(--kp-redact-cut) steps(3, end),
                color 0s linear var(--kp-redact-cut);
        }

        [data-theme='grotesk'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2) {
            transition-delay: var(--kp-redact-stagger), var(--kp-redact-cut);
        }

        [data-theme='grotesk'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3) {
            transition-delay: calc(2 * var(--kp-redact-stagger)), var(--kp-redact-cut);
        }

        /* (b) The nav/footer link and (e) the button mirror-invert: colour
           only, the theme's own two-speed and fx-duration/fx-ease. */
        [data-theme='grotesk'] .kp-nav__link,
        [data-theme='grotesk'] .kp-footer a {
            transition-property: color;
        }

        [data-theme='grotesk'] .kp-button {
            transition:
                background-color var(--fx-duration) var(--fx-ease),
                color var(--fx-duration) var(--fx-ease),
                border-color var(--fx-duration) var(--fx-ease);
        }

        /* (f) The confirmation dialog: Kenny's rule of 2026-09-08 (a native
           <dialog>, never a button that relabels itself), the theme's own
           fx-duration/fx-ease (120ms, linear: on time — written as
           literals here, not var(--fx-duration), because check-motion.mjs
           computes DI5's rate from the animation's own declared duration),
           opacity+transform on the panel only. */
        [data-theme='grotesk'] .kp-dialog[open] {
            animation: kp-dialog-in 120ms linear;
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* Every keyframe here has its row in TIMINGS (js/effects.js). */
    @keyframes kp-sharpen-in {
        to {
            filter: blur(0) brightness(1);
        }
    }

    /* (f) The dialog: opacity+transform on the panel only, once. */
    @keyframes kp-dialog-in {
        0% {
            opacity: 0;
            transform: translateY(6px);
        }

        100% {
            opacity: 1;
            transform: none;
        }
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — heavy rules above and below, half-bold. */
    [data-theme='grotesk'] .kp-marquee {
        border-block: 2px solid var(--foreground);
        font-weight: 600;
        letter-spacing: -0.01em;
        --kp-marquee: 30000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    /* A mega menu's group headings speak in the caption's voice [scope-48]. */
    [data-theme='grotesk'] .kp-nav__menu[data-kp-menu-label]::before,
    [data-theme='grotesk'] .kp-nav__menu--wide .kp-nav__menu-heading {
        color: var(--primary);
        font-weight: 600;
        letter-spacing: 0.02em;
        border-block-end: 2px solid var(--foreground);
    }

    /* ── The side navigation [feat-nav-3] ────────────────────────────
       Kenny said this one can be better. Its whole idea is the grid, so
       the column shows it: every row on a baseline, and the one you are
       on set in the heavy weight this theme otherwise keeps for headings
       — the type carries the state rather than a colour. */
    [data-theme='grotesk'] .kp-sidenav {
        --kp-sidenav-surface: var(--card);
        --kp-sidenav-gap: 0;
        --kp-sidenav-list-pad: 0;
        border-inline-end: 1px solid var(--border-strong);
    }

    [data-theme='grotesk'] .kp-sidenav__title {
        letter-spacing: 0.16em;
        text-transform: uppercase;
        border-block-end: 1px solid var(--border);
    }

    [data-theme='grotesk'] .kp-sidenav__link,
    [data-theme='grotesk'] .kp-sidenav__category-toggle {
        border-radius: 0;
        border-block-end: 1px solid var(--border);
        padding-inline: 0.9rem;
    }

    [data-theme='grotesk'] .kp-sidenav__link[aria-current='page'] {
        background: none;
        color: var(--foreground);
        font-weight: 800;
        letter-spacing: -0.01em;
    }

    /* ── Back to top, and a picture [feat-page-1, feat-media-1] ──────
       The grid: square corners, a caption on the baseline, and nothing
       that is not a rule. */
    [data-theme='grotesk'] .kp-to-top {
        border-radius: 0;
        border: 1px solid var(--border-strong);
    }

    [data-theme='grotesk'] .kp-media {
        border: 1px solid var(--border-strong);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-media-figure > figcaption {
        border-block-start: 1px solid var(--border);
        padding-block-start: 0.4rem;
        letter-spacing: 0.02em;
    }

    /* The figure carries the caption's voice, so the decision sits with
       the picture rather than with the words under it. */
    [data-theme='grotesk'] .kp-media-figure {
        color: var(--foreground);
    }

    /* ── The pressed state the register had been cancelling [fix-12] ───
       `kp.register` sits after `kp.components`, and a layer beats a state:
       a register writing `.kp-button:hover { background: ... }` outranks
       the base layer's `.kp-button:active`, so pressing the button changed
       nothing. Kenny found it on Shade (dark), 2026-09-11 — "als ik gewoon
       blijf klikken op de knop zelf, dan gebeurt er precies niks".
       Grotesk's pressed states are written out with the buttons above
       (paper, never the base layer's grey; a red face deepens its red), so
       what a press paints is this register's own decision. */

    /* ── The baseline appears [scope-12, approved 2026-09-12] ──────────
       Grotesk is Swiss typography, and the instrument of Swiss typography
       is the line the letters stand on. Touching a control draws that
       line — not the control's bottom edge, the TYPE's baseline — from
       the leading edge out past the word, in the theme's one red. The
       letters end up standing ON it and the descenders cross it, which is
       what a baseline rule does.

       It says what the theme is about rather than decorating it, and it
       never covers the letters, so there is no contrast question. The
       press thickens the rule into the deeper red, downward, so its top
       edge stays exactly on the baseline.

       This replaces a first proposal that snapped `letter-spacing` from 0
       to 0.12em: about 13.8px of extra label width on an eight-character
       word, which grew the control and shifted everything beside it —
       Kenny's rejection of 2026-09-11. Nothing here changes the box. The
       rule is an absolutely positioned child, so it is out of flow even
       inside `.kp-button__label`'s inline-flex.

       `--kp-baseline-drop` is MEASURED, not guessed. Firefox, 2026-09-12,
       from the label's own font metrics: Inter 700 at 16px in a 19.20px
       line box reports ascent 16.00 and descent 4.00, so the baseline sits
       (19.20 − 20.00) / 2 + 4.00 = 3.60px above the box bottom — 0.225em.
       The first attempt measured it with a zero-width inline probe and got
       9.60px, because `.kp-button__label` is an inline-flex container and
       a probe inside it becomes a flex item, where `vertical-align` does
       nothing at all. */
    [data-theme='grotesk'] .kp-button__label,
    [data-theme='grotesk'] .kp-nav__link,
    [data-theme='grotesk'] .kp-sidenav__link {
        position: relative;
    }

    [data-theme='grotesk'] .kp-button__label::after,
    [data-theme='grotesk'] .kp-nav__link::after,
    [data-theme='grotesk'] .kp-sidenav__link::after {
        content: '';
        position: absolute;
        inset-inline: calc(-1 * var(--kp-baseline-reach, 0.5rem));
        /* The rule's TOP edge on the baseline, so the letters stand on it. */
        inset-block-end: calc(var(--kp-baseline-drop, 0.225em) - var(--kp-baseline-weight, 2px));
        block-size: var(--kp-baseline-weight, 2px);
        background: var(--kp-baseline-colour, var(--primary));
        scale: 0 1;
        transform-origin: left center;
        pointer-events: none;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] .kp-button__label::after,
        [data-theme='grotesk'] .kp-nav__link::after,
        [data-theme='grotesk'] .kp-sidenav__link::after {
            transition: scale var(--fx-duration, 220ms) var(--fx-ease, ease);
        }
    }

    [data-theme='grotesk'] .kp-nav__link:hover::after,
    [data-theme='grotesk'] .kp-nav__link:focus-visible::after,
    [data-theme='grotesk'] .kp-sidenav__link:hover::after,
    [data-theme='grotesk'] .kp-sidenav__link:focus-visible::after {
        scale: 1 1;
    }

    /* The press thickens the rule [Kenny, 2026-10-07: "the rule thickens", his
       scope-12]: at once and for as long as it is held, the baseline under a
       button's words is out, 4 px, in the deeper red; a nav link's was out
       already (it is drawn by hovering) and only thickens. Nothing here is in
       the transition list, so a click shorter than 120 ms still shows — the
       reading that fixed Shade (light) and Shade (dark). */
    [data-theme='grotesk'] .kp-button:active:not(:disabled) .kp-button__label::after {
        scale: 1 1;
        transition: none;
    }

    [data-theme='grotesk'] .kp-button:active:not(:disabled) .kp-button__label,
    [data-theme='grotesk'] .kp-nav__link:active,
    [data-theme='grotesk'] .kp-sidenav__link:active {
        --kp-baseline-weight: var(--kp-baseline-weight-pressed, 4px);
        --kp-baseline-colour: var(--primary-active);
    }

    /* ── Read-only fields [gap-11] ────────────────────────────────────── */

    /* A read-only field is a value on a record, not a box to type in. This
       register sets the field's border and ground in kp.register, which
       beats the read-only look in kp.components, so read-only painted like
       an editable field. The state is answered here, on top of the rest
       look, which stays as it was. */
    [data-theme='grotesk'] .kp-field__input[readonly] {
        border-style: dashed;
        background-color: var(--muted);
    }

    /* ── The palette's trigger in the bar [scope-48, scope-80] ─────────── */

    /* In the voice of this register's own nav links (Kenny, 2026-09-14,
       search-voice "Per thema"): bold muted words that take the full ink
       when pointed at, while the baseline rule this register draws under its
       links grows out from the start. The link's typeface, case, spacing,
       shape and pointer answer are restated here, because the trigger is a
       button beside the list rather than a link in it. The underline a plain
       link carries is not: it says "this is a link", and the trigger is not
       one. */
    [data-theme='grotesk'] .kp-nav__search .kp-nav__search-trigger {
        position: relative;
        padding-inline: 0;
        font-weight: 600;
        letter-spacing: 0.01em;
        white-space: nowrap;
        border: 0;
        border-radius: 0;
        background: none;
        color: var(--muted-foreground);
    }

    [data-theme='grotesk'] .kp-nav__search .kp-nav__search-trigger:hover,
    [data-theme='grotesk'] .kp-nav__search .kp-nav__search-trigger:focus-visible {
        color: var(--foreground);
    }

    [data-theme='grotesk'] .kp-nav__search .kp-nav__search-trigger::after {
        content: '';
        position: absolute;
        inset-inline: calc(-1 * var(--kp-baseline-reach, 0.5rem));
        inset-block-end: calc(var(--kp-baseline-drop, 0.225em) - var(--kp-baseline-weight, 2px));
        block-size: var(--kp-baseline-weight, 2px);
        background: var(--kp-baseline-colour, var(--primary));
        scale: 0 1;
        transform-origin: left center;
        pointer-events: none;
    }

    [data-theme='grotesk'] .kp-nav__search .kp-nav__search-trigger:hover::after,
    [data-theme='grotesk'] .kp-nav__search .kp-nav__search-trigger:focus-visible::after {
        scale: 1 1;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] .kp-nav__search .kp-nav__search-trigger::after {
            transition: scale var(--fx-duration, 220ms) var(--fx-ease, ease);
        }
    }

    /* ── The alarm [scope-94] ──────────────────────────────────────────────
       A poster, not a screen: the whole window is its red, the headline enormous in white with tight spacing, set flush left, with no frame and no bars. Every colour is one of this theme's tokens. The
       button keeps this register's shape and takes the alarm's paint, on
       selectors long enough to outrank this register's own button states;
       the dialog takes no focus ring, because in the auto mode the whole
       screen is what has focus. */
    [data-theme='grotesk'] .kp-alarm {
        --kp-alarm-ground: var(--destructive);
        --kp-alarm-ink: var(--destructive-foreground);
        --kp-alarm-soft: var(--destructive-foreground);
        --kp-alarm-split: var(--foreground);
        --kp-alarm-on-ink: var(--destructive);
        --kp-alarm-glow: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-halo: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-scan: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-vignette: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-bar: 0rem;
        --kp-alarm-frame: 0 solid;
        /* Smaller than the poster it was: at 864x450 the headline pushed
           20px past the frame [scope-108]. */
        --kp-alarm-title-size: clamp(2rem, 10cqi, 8rem);
        --kp-alarm-title-tracking: -0.04em;
    }

    [data-theme='grotesk'] .kp-alarm:focus-visible {
        outline: none;
    }

    [data-theme='grotesk'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack,
    [data-theme='grotesk'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:hover:not(:disabled),
    [data-theme='grotesk'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:active:not(:disabled) {
        border-color: var(--kp-alarm-ink);
        background: var(--kp-alarm-ink);
        color: var(--kp-alarm-on-ink);
        text-shadow: none;
    }

    [data-theme='grotesk'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:is(:hover, :focus-visible):not(:disabled):not(:active) {
        background: var(--kp-alarm-on-ink);
        color: var(--kp-alarm-ink);
    }

    [data-theme='grotesk'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep,
    [data-theme='grotesk'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep:is(:hover, :focus-visible):not(:disabled) {
        border-color: currentColor;
        background: transparent;
        color: inherit;
        text-shadow: none;
    }

    [data-theme='grotesk'] .kp-alarm__panel {
        justify-items: start;
        text-align: start;
    }

    /* A submenu item's mark [Kenny, 2026-09-20]: an em dash: typography, not ornament. */
    [data-theme='grotesk'] .kp-sidenav__submenu .kp-sidenav__link {
        --kp-sidenav-submenu-mark: '—';
    }

    /* ── A plate is a column under its rule [G7; Kenny, 2026-10-07 on
       research/grotesk-character: surface = a column under its rule, no box].
       A card, a key figure, the busy panel and the page header are white
       paper with no frame: a 3 px ink rule along the top says where it starts
       and the words stand flush left on the column. The grid's hairlines
       stay under data and on the page (the twelve columns). What floats over
       the page (dialog, popover, menu, toast, tooltip) keeps its 3 px ink
       frame above, so it stands off what is under it. No shadow, no blur, no
       tint, nothing translucent: the plate has no paper of its own, so the
       red plate behind it (the signature layer) shows only its ink. ── */
    [data-theme='grotesk'] :is(.kp-card, .kp-kpi, .kp-datatable__busy-panel, .kp-page-header) {
        border: 0;
        border-block-start: 3px solid var(--foreground);
        border-radius: 0;
        background: transparent;
        box-shadow: none;
    }

    [data-theme='grotesk'] :is(.kp-card, .kp-kpi) {
        padding: 0.5rem 0 0.65rem;
    }

    [data-theme='grotesk'] .kp-page-header {
        padding-block: 0.6rem 0.7rem;
    }

    /* A key figure or a card that is a link or a toggle: hovered, its rule
       turns red and thickens to 7 px (the rule is 3, the red goes 4 deeper
       inside it, so the words stay where they are) and it takes a 4 % wash of
       the red [hover = a bar on the edge thickens]. A filter that is on keeps
       its pressed colours (the package's). */
    [data-theme='grotesk'] :is(a.kp-kpi, .kp-kpi--toggle, .kp-kpi--trend):hover {
        border-block-start-color: var(--primary);
        background: color-mix(in oklab, var(--primary) 4%, var(--card));
        box-shadow: inset 0 4px 0 0 var(--primary);
    }

    /* ── A warning is indexed [G13; Kenny, 2026-10-07: tone = indexed]. A key
       figure in a tone carries a 6 px bar of the tone down its start edge, like
       a thumb index, and the tone's word, set in bold before its figure, so
       colour is never the only carrier (DI4); the figure itself stays ink on
       paper (the package's plate under the figure is taken off). The words
       are knobs (--kp-sig-gr-word-warning, --kp-sig-gr-word-destructive) so
       a page in another language sets its own. ── */
    [data-theme='grotesk'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) {
        padding-inline-start: 0.9rem;
        border-inline-start: 6px solid var(--kp-sig-gr-tone);
        box-shadow: none;
    }

    [data-theme='grotesk'] .kp-kpi[data-kp-tone='warning'] {
        --kp-sig-gr-tone: var(--warning);
    }

    [data-theme='grotesk'] .kp-kpi[data-kp-tone='destructive'] {
        --kp-sig-gr-tone: var(--destructive);
    }

    [data-theme='grotesk'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value {
        padding-inline: 0;
        background: none;
        color: var(--foreground);
    }

    [data-theme='grotesk'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value::before {
        margin-inline-end: 0.4em;
        font-family: var(--theme-font-body);
        font-size: 0.78rem;
        font-weight: 700;
        letter-spacing: 0;
        vertical-align: 0.35em;
    }

    [data-theme='grotesk'] .kp-kpi[data-kp-tone='warning'] .kp-kpi__value::before {
        content: var(--kp-sig-gr-word-warning, 'Warning');
    }

    [data-theme='grotesk'] .kp-kpi[data-kp-tone='destructive'] .kp-kpi__value::before {
        content: var(--kp-sig-gr-word-destructive, 'Failed');
    }

    /* The change sits on a square plate with the timetable's arrows, ↗ and ↘
       [G13]. A change with a tone keeps the package's status pair. */
    [data-theme='grotesk'] .kp-kpi__delta {
        padding-inline: 0.3em;
        border-radius: 0;
        font-family: var(--theme-font-body);
        font-weight: 700;
    }

    [data-theme='grotesk'] .kp-kpi__delta:not([data-kp-tone]) {
        background: var(--secondary);
        color: var(--secondary-foreground);
    }

    [data-theme='grotesk'] .kp-kpi__delta[data-kp-direction='up']::before {
        content: '↗\00a0';
    }

    [data-theme='grotesk'] .kp-kpi__delta[data-kp-direction='down']::before {
        content: '↘\00a0';
    }
}

/* ── Signature [scope-140] ─────────────────────────────────────────────── */
/* grotesk's approved signature (Kenny, 2026-10-03, three review rounds): the
   progress bar and the ten elements (spinner, skeleton, switch, check and
   radio, toast, dialog, tooltip, wizard steps, empty state, link hover),
   ported once from research/progress-signature/themes/grotesk.css and research/signature-elements/themes/grotesk.css
   and maintained here from now on. In kp.signature, which css/themes.css
   orders after kp.register, so it draws over the register exactly as the
   approved demos did, whatever the weight of a register selector. */
@layer kp.signature {
    /* The link signature is for links in running text; a link in a navigation,
       a menu, a breadcrumb (a nav) or the footer keeps its own component's look
       (scope-93: no link colour in a navigation). */
    [data-theme='grotesk'] .kp-progressbar {
        --kp-progressbar-height: calc(1rem * var(--kp-progressbar-scale, 1));
        --gr-ink: var(--border-strong);
        --gr-red: var(--primary);
        --gr-base: 2px;
        --gr-col: calc(100% / 12);
    }

    [data-theme='grotesk'] .kp-progressbar__track {
        border-radius: 0;
        background:
            linear-gradient(var(--gr-ink), var(--gr-ink)) left bottom / 100% var(--gr-base) no-repeat,
            linear-gradient(color-mix(in oklab, var(--gr-ink) 28%, transparent), color-mix(in oklab, var(--gr-ink) 28%, transparent)) right top / 1px
                100% no-repeat,
            linear-gradient(90deg, color-mix(in oklab, var(--gr-ink) 28%, transparent) 0 1px, transparent 1px) 0 0 / var(--gr-col) 100% repeat-x,
            var(--card);
    }

    [data-theme='grotesk'] .kp-progressbar__fill {
        inset-block-end: var(--gr-base);
        background: var(--gr-red);
        transition: clip-path var(--fx-duration, 120ms) var(--fx-ease, cubic-bezier(0.2, 0, 0, 1));
    }

    [data-theme='grotesk'] .kp-progressbar__head {
        inline-size: 3px;
        background: var(--gr-ink);
        transform: translateX(calc(var(--kp-value) * (100cqi - 3px)));
        transition: transform var(--fx-duration, 120ms) var(--fx-ease, cubic-bezier(0.2, 0, 0, 1));
    }

    /* The busy bar is the slab [bars = the slab; Kenny, 2026-10-07 on
       research/grotesk-character: "one heavy ink bar, its red plate turning
       clockwise behind it"]: a solid ink bar the full width and, behind it,
       the same bar in red, `--kp-sig-gr-r` away, which closes in clockwise
       at an even pace, falls into register (the red goes behind the black)
       and dwells, then opens out again clockwise: 2640 ms. Only the red
       fringe shows until the plates register; nothing in it is thinner than
       3 px. A bar with a share is the red fill on the ruled track, as before.
       Standing still the plate lies a little out of register. */
    [data-theme='grotesk'] .kp-progressbar[data-kp-indeterminate] {
        --kp-sig-gr-r: calc(3px * var(--kp-progressbar-scale, 1));
    }

    [data-theme='grotesk'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__track {
        background: var(--card);
    }

    [data-theme='grotesk'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__track::before {
        content: '';
        position: absolute;
        inset: var(--kp-sig-gr-r);
        background: var(--gr-red);
        --kp-sig-gr-a: 39.8deg;
        --kp-sig-gr-q: 0.78;
        translate: calc(var(--kp-sig-gr-r) * var(--kp-sig-gr-q) * cos(var(--kp-sig-gr-a)))
            calc(var(--kp-sig-gr-r) * var(--kp-sig-gr-q) * sin(var(--kp-sig-gr-a)));
    }

    [data-theme='grotesk'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
        inset: var(--kp-sig-gr-r);
        inline-size: auto;
        clip-path: none;
        animation: none;
        background: var(--gr-ink);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__track::before {
            animation: kp-sig-grotesk-loop var(--kp-sig-gr-loop) linear infinite;
        }
    }

    /* ── The grammar [Kenny, 2026-10-07 on research/grotesk-character: all
       nineteen questions approved; themes/grotesk/CHARACTER.md "Applied"].
       The anchor is Out of register: a second, red plate under the black ink;
       where it stands says what the part is (slipped: arriving, waiting,
       changing; in register, behind the black: there, held). It runs on time:
       an even pace (`--fx-ease` is linear), a dead stop, a dwell, in whole
       units of the register's 120 ms: contact 1 unit, a set 2, a fall 8, a
       loop 22. Written as literals: js/motion.js reads its caps from the root
       and parses their milliseconds. ── */
    [data-theme='grotesk'] {
        --kp-sig-gr-unit: 120ms;
        --kp-sig-gr-set: 240ms;
        --kp-sig-gr-fall: 960ms;
        --kp-sig-gr-loop: 2640ms;
        /* The second plate: the red, and how far it slipped (a part says its own). */
        --kp-sig-gr-plate: var(--primary);
        --kp-sig-gr-r: 6px;
        --kp-sig-gr-draw: var(--kp-rule-draw, 360ms);
        --kp-sig-gr-ease: linear;
        --kp-sig-gr-cols: repeating-linear-gradient(to right, hsl(from var(--foreground) h s l / 0.06) 0 1px, transparent 1px calc(100% / 12));
        /* A close is as long as a fall, a resize is the cut's two units, and
           nothing is dimmed while it waits: the proof says busy (G7). */
        --kp-close-max: var(--kp-sig-gr-fall);
        --kp-size-max: var(--kp-sig-gr-set);
        --kp-busy-opacity: 1;
    }

    /* A part's second plate slips less on a small part and more on a window. */
    [data-theme='grotesk'] :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-kpi__link, .kp-tag, .kp-badge) {
        --kp-sig-gr-r: 4px;
    }

    [data-theme='grotesk'] :is(.kp-dialog, .kp-toast, .kp-tooltip, .kp-popover, .kp-menu) {
        --kp-sig-gr-r: 8px;
    }

    /* A red face's second plate is the ink: its own red would not show. */
    [data-theme='grotesk'] :is(.kp-button--primary, .kp-button--destructive) {
        --kp-sig-gr-plate: var(--foreground);
    }

    /* The spinner is the twin that turns [spinner = the twin turns]: a square
       ink outline (3 px at the least) and, behind it, its red twin, which
       turns clockwise at an even pace and is in register every quarter turn
       (a square looks the same every 90 degrees), where it rests for 3
       units: a quarter turn in 8 units, 2640 ms for half a turn. It never
       stops turning and never turns back. Standing still, the twin lies a
       little turned. On a red face the twin is the ink and the square the
       face's own white. */
    [data-theme='grotesk'] .kp-spinner {
