    [data-theme='grotesk'] .kp-skeleton::after {
        content: '';
        position: absolute;
        inset: 0;
        box-sizing: border-box;
    }

    [data-theme='grotesk'] .kp-skeleton:is(.kp-skeleton--circle, .kp-skeleton--block)::before,
