        }

        65.63% {
            filter: drop-shadow(0 calc(var(--kp-sig-gr-r) * -0.314) 0 var(--kp-sig-gr-plate));
        }

        76.56% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * 0.141) calc(var(--kp-sig-gr-r) * -0.141) 0 var(--kp-sig-gr-plate));
        }

        87.5%,
