        36.36%,
        50% {
            rotate: 90deg;
        }

        86.36%,
        100% {
            rotate: 180deg;
        }
    }

    @keyframes kp-sig-grotesk-gr-cut {
        from {
            clip-path: inset(0 100% 0 0);
        }

        to {
            clip-path: inset(0);
        }
    }

    @keyframes kp-sig-grotesk-gr-disc {
        from {
            transform: scale(0);
        }
    }

    @keyframes kp-sig-grotesk-gr-rule {
        from {
            transform: scaleX(0);
        }

        to {
            transform: scaleX(1);
        }
    }

    /* Growing and shrinking, this theme's way [scope-142; approved by Kenny
       on research/size-motion, 2026-10-04]. js/motion.js marks a gliding box
       `[data-kp-resizing]` and what arrives in it `[data-kp-arriving]`. */
    @media (prefers-reduced-motion: no-preference) {
        /* ── grotesk: the cut. The box jumps in three hard cuts behind a heavy
           rule, and a new line is cut in from the left in three. ────────── */
        [data-theme='grotesk'] {
            --kp-size-ease: steps(3, jump-end);
        }

        [data-theme='grotesk'] [data-kp-resizing] {
            outline: 3px solid var(--foreground);
            outline-offset: 0;
        }

        /* What arrives in a gliding box is printed in black and its red plate falls
           into register on it, as everything that arrives does [direction = the
           plate; Kenny, 2026-10-07]; the box itself still takes its size in the
           three cuts he picked. */
        [data-theme='grotesk'] [data-kp-arriving] {
            animation: kp-sig-grotesk-fall var(--kp-sig-gr-fall) linear backwards;
        }
    }

    /* Leaving, this theme's way [scope-142; Kenny, 2026-10-07 on
       research/grotesk-character: leave = opens out clockwise, then it is gone].
       js/motion.js marks what leaves `[data-kp-leaving]`, closes its space during
       the exit, and in a row of leaves starts the next one halfway through this
       one. The part stands in black; its red plate leaves register and turns one
       full turn clockwise while it opens out to --kp-sig-gr-r (a fall's 8 units,
       960 ms), and the part is gone at the end of the turn. Arriving was the
       fall closing in clockwise, so the plate has turned the same way the whole
       time: the leave is NOT the arrival played backwards. This is the one place
       the rule that a close is its open reversed is broken on purpose, and
       js/motion.js is told so by this register not declaring
       `--kp-open: reverse-close`: what arrives plays its own fall above, not this
       leave backwards (that would turn the plate counter-clockwise). */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] [data-kp-leaving] {
            --kp-sig-gr-a: 0deg;
            --kp-sig-gr-q: 0;
            filter: drop-shadow(
                calc(var(--kp-sig-gr-r) * var(--kp-sig-gr-q) * cos(var(--kp-sig-gr-a)))
                    calc(var(--kp-sig-gr-r) * var(--kp-sig-gr-q) * sin(var(--kp-sig-gr-a))) 0
                    rgb(from var(--kp-sig-gr-plate) r g b / clamp(0, calc(var(--kp-sig-gr-q) * 40), 1))
            );
            animation: kp-sig-grotesk-leave var(--kp-sig-gr-fall) linear forwards;
        }

        @keyframes kp-sig-grotesk-leave {
            0% {
                --kp-sig-gr-a: 0deg;
                --kp-sig-gr-q: 0;
                visibility: visible;
            }

            99.9% {
                --kp-sig-gr-a: 360deg;
                --kp-sig-gr-q: 1;
                visibility: visible;
            }

            100% {
                --kp-sig-gr-a: 360deg;
                --kp-sig-gr-q: 1;
                visibility: hidden;
            }
        }
    }

    /* ── The meter with a mark, this theme's way [picked by Kenny on
       research/character-meter, rounds 3 and 4, 2026-10-05: shape 1,
       while loading 2, how the share arrives 3, when the tone
       changes 3, the mark past the end 2]. The package's own markup
       and states (setMeter(), js/kpi.js): the track on the meter, the share on
       ::before, the sign past the end or the loading picture on ::after, the
       mark `.kp-meter__mark`. Every animation and transition under
       prefers-reduced-motion: no-preference; still frames otherwise. ── */

    /* The shared part: room past the end, loading without the pulse, the mark
       centred on its width, the package's signs cleared for the shape's own.
       Under :where() so each picked rule below wins as it did in the demo. */
    :where([data-theme='grotesk']) :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-room: 0.625rem;
        box-sizing: border-box;
    }

    :where([data-theme='grotesk']) .kp-meter--inline {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-sig-meter-room));
    }

    /* Each character draws its own loading picture instead of the pulse. */
    :where([data-theme='grotesk']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: clip;
        animation: none;
    }

    :where([data-theme='grotesk']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    /* The mark is centred on its share, whatever its width. */
    :where([data-theme='grotesk']) .kp-meter__mark {
        --kp-sig-meter-mw: 2px;
        box-sizing: border-box;
        inline-size: var(--kp-sig-meter-mw);
        inset-inline-start: calc(clamp(0, var(--kp-mark, 0), 1) * 100% - var(--kp-sig-meter-mw) / 2);
    }

    :where([data-theme='grotesk']) .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - 0.75rem);
    }

    /* The sign past the end, cleared of the package's ▸ for each character
       to draw its own. */
    :where([data-theme='grotesk']) :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '';
        position: absolute;
        inset: auto;
        translate: none;
        color: inherit;
        font-size: 0.75rem;
        line-height: 1;
        text-shadow: none;
        white-space: nowrap;
        pointer-events: none;
    }

    /* A mark past the end keeps the package's sign inside the bar's end, in
       each character's own glyph and ink. */
    :where([data-theme='grotesk']) .kp-meter__mark[data-kp-over]::after {
        content: var(--kp-sig-meter-mo-sign, '▸');
        color: var(--kp-sig-meter-mo-ink, var(--foreground));
        font-family: var(--kp-sig-meter-mo-font, inherit);
        text-shadow:
            0 0 1px var(--kp-sig-meter-mo-halo, var(--card)),
            0 0 2px var(--kp-sig-meter-mo-halo, var(--card));
    }

    /* ── shape: option 1 ── */

    /* ── grotesk · 1 · the rule and its cursor (round 4) ──────────────── */

    /* A steel rule: a white strip in a black outline, a long tick every
       tenth and a short one every fiftieth hanging from its top edge, the
       share a red band along its lower half under the ticks, a black
       cursor triangle pointing up from below as the mark, a bold red +
       past the end. */
    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-meter-height: 0.625rem;
        --kp-sig-meter-room: 0.875rem;
        --kp-sig-meter-mo-ink: var(--foreground);
        border-radius: 0;
        background:
            linear-gradient(90deg, var(--foreground) 1px, transparent 1px) 0 0 / 10% 5px repeat-x,
            linear-gradient(90deg, var(--foreground) 1px, transparent 1px) 0 0 / 2% 2px repeat-x,
            var(--card);
        box-shadow: inset 0 0 0 1px var(--foreground);
    }

    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)::before {
        inset-block: 5px 1px;
        border-radius: 0;
    }

    /* The cursor: a black hairline across the rule, a black triangle under it. */
    [data-theme='grotesk'] .kp-meter__mark {
        inset-block: 0 -1px;
        border-radius: 0;
        background: var(--foreground);
        box-shadow: 0 0 0 1px var(--card);
    }

    [data-theme='grotesk'] .kp-meter__mark::before {
        content: '';
        position: absolute;
        inset-block-start: 100%;
        inset-inline-start: 50%;
        inline-size: 8px;
        block-size: 5px;
        translate: -50% 0;
        background: var(--foreground);
        clip-path: polygon(50% 0, 100% 100%, 0 100%);
    }

    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '+';
        inset-inline-start: calc(100% + 2px);
        inset-block-start: 50%;
        translate: 0 -50%;
        color: var(--primary);
        font: 900 1rem/1 var(--theme-font-display, sans-serif);
    }

    /* ── while loading: the meter's proof [loading = out of register; Kenny,
       2026-10-07]. The meter's own drawing is printed in two plates: the
       ruler (a hairline above and below it and a tick every tenth) in ink on
       ::after and, under it, the same ruler in red on ::before, which travels
       the clockwise loop (22 units) behind it. Standing still the red lies a
       little out of register. ── */

    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        --kp-sig-gr-r: 4px;
        background: var(--card);
        box-shadow: none;
        animation: none;
    }

    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::before,
    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        all: unset;
        content: '';
        display: block;
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::before {
        background:
            linear-gradient(var(--primary) 0 0) 0 0 / 100% 1.5px no-repeat,
            linear-gradient(var(--primary) 0 0) 0 100% / 100% 1.5px no-repeat,
            repeating-linear-gradient(90deg, var(--primary) 0 1.5px, transparent 1.5px 10%);
        --kp-sig-gr-a: 39.8deg;
        --kp-sig-gr-q: 0.78;
        translate: calc(var(--kp-sig-gr-r) * var(--kp-sig-gr-q) * cos(var(--kp-sig-gr-a)))
            calc(var(--kp-sig-gr-r) * var(--kp-sig-gr-q) * sin(var(--kp-sig-gr-a)));
    }

    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        background:
            linear-gradient(var(--foreground) 0 0) 0 0 / 100% 1.5px no-repeat,
            linear-gradient(var(--foreground) 0 0) 0 100% / 100% 1.5px no-repeat,
            repeating-linear-gradient(90deg, var(--foreground) 0 1.5px, transparent 1.5px 10%);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::before {
            animation: kp-sig-grotesk-loop var(--kp-sig-gr-loop) linear infinite;
        }
    }

    /* ── how the share arrives: option 3 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)::before {
            animation: kp-sig-grotesk-meter-grow-o 480ms steps(4) backwards;
            transition: inline-size 480ms steps(4);
            transform-origin: 0 50%;
        }
    }

    /* ── when the tone changes: the plate falls back into register [G13: a tone
       never jolts or swells the part; Kenny, 2026-10-07 on
       research/grotesk-character: live = the plate]. A meter that turns to
       warning or destructive is printed again: its red plate falls into
       register on it once, 960 ms; the two tones have a name each, so a change
       from one to the other starts it again. A meter that is loading draws
       its own proof. ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='warning']:not([data-kp-loading]) {
            --kp-sig-gr-r: 4px;
            animation: kp-sig-grotesk-fall var(--kp-sig-gr-fall) linear;
        }

        [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='destructive']:not([data-kp-loading]) {
            --kp-sig-gr-r: 4px;
            animation: kp-sig-grotesk-fall-again var(--kp-sig-gr-fall) linear;
        }
    }

    /* ── the mark past the end: option 2 ── */

    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-mo-sign: '→';
    }

    [data-theme='grotesk'] .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% + 3px);
    }

    [data-theme='grotesk'] .kp-meter__mark[data-kp-over]::after {
        inset-inline-start: calc(100% + 2px);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] .kp-meter__mark {
            transition:
                inset-inline-start 480ms var(--kp-sig-gr-ease),
                rotate 480ms var(--kp-sig-gr-ease);
        }
    }

    @keyframes kp-sig-grotesk-meter-grow-o {
        0% {
            scale: 0 1;
        }

        100% {
            scale: 1 1;
        }
    }
}
/* ── End of the signature ── */

/* The pen's numbers [scope-143, Kenny 2026-10-07 23:41: the tracing pen is the
   anchor of the theme]. Registered at the top level because Firefox does not
   register an @property inside a cascade layer; with no registration every
   keyframe below would flip between its two poses instead of moving.
   --kp-bp-r is the route of a traced outline (0 to 4: a side per unit),
   --kp-bp-rp the reading along a diagonal (0 to 1), --kp-bp-p one stroke
   along a line (0 to 1); --kp-bp-nib is the pen down (1) or up (0),
   --kp-bp-pv, --kp-bp-rv and --kp-bp-tv how much of the pen, of the reading
   (witness lines and pointers) and of the construction line is on the sheet;
   --kp-bp-hv, --kp-bp-dv and --kp-bp-sv how much of the scale, of the
   dimension and of the pointer a hand has set on a control. */
@property --kp-bp-r {
    syntax: '<number>';
    inherits: true;
    initial-value: 0;
}

@property --kp-bp-rp {
    syntax: '<number>';
    inherits: true;
    initial-value: 0;
}

@property --kp-bp-p {
    syntax: '<number>';
    inherits: true;
