}

@property --kp-bp-rv {
    syntax: '<number>';
    inherits: true;
    initial-value: 0;
}

@property --kp-bp-tv {
    syntax: '<number>';
    inherits: true;
    initial-value: 0;
}

@property --kp-bp-hv {
    syntax: '<number>';
    inherits: true;
    initial-value: 0;
