    [data-theme='blueprint'] .kp-kpi[data-kp-tone='destructive'] {
        --kp-bp-tone: var(--kp-bp-bad);
        --kp-bp-at: 0.92;
        --kp-kpi-meter-fill: var(--kp-bp-bad);
    }

    [data-theme='blueprint'] .kp-kpi[data-kp-tone='warning'] {
        --kp-kpi-meter-fill: var(--kp-bp-warn);
    }

    [data-theme='blueprint'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value {
        position: relative;
        padding: 0 0 14px;
        background: transparent;
        color: var(--foreground);
