    [data-theme='blueprint'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value :is(small, .kp-kpi__note) {
        color: var(--muted-foreground);
    }

    [data-theme='blueprint'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value::after {
        content: '';
        position: absolute;
        inset-block-end: 6px;
        inset-inline: 0;
        block-size: 5px;
        background:
            linear-gradient(var(--border-strong), var(--border-strong)) bottom / 100% 1px no-repeat,
            repeating-linear-gradient(90deg, var(--border-strong) 0 1px, transparent 1px 6px) bottom / 100% 4px no-repeat;
    }

    [data-theme='blueprint'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value::before {
        content: '';
        position: absolute;
