    }

    /* The voice [voice, G15]: the lettering names, the sans speaks. Labels, tags,
       table heads, the change, toasts, the tooltip and the dialog's title are the
       draughtsman's lettering: mono capitals sloped 15 degrees (ISO 3098 type B),
       barely tracked. Titles and figures stay upright, in the sans, with tabular
       figures. */
    [data-theme='blueprint'] .microlabel,
    [data-theme='blueprint'] .kp-badge,
    [data-theme='blueprint'] .kp-tag,
    [data-theme='blueprint'] .kp-table th,
    [data-theme='blueprint'] .kp-kpi__label,
    [data-theme='blueprint'] .kp-kpi__delta,
    [data-theme='blueprint'] .kp-toast,
    [data-theme='blueprint'] .kp-tooltip,
    [data-theme='blueprint'] .kp-dialog__title,
