            linear-gradient(hsl(from var(--foreground) h s l / 0.7), hsl(from var(--foreground) h s l / 0.7)) 100% 0 / 1px 100% no-repeat;
    }

    [data-theme='blueprint'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)::after {
        --kp-bp-px: var(--kp-bp-p);
        --kp-bp-py: 1;
        inset: -8px;
        background-image: var(--kp-bp-pen-img), linear-gradient(var(--kp-bp-c-trace), var(--kp-bp-c-trace));
        background-size:
            var(--kp-bp-pen-size),
            calc(var(--kp-bp-p) * (100% - 16px)) 1px;
        background-position:
            var(--kp-bp-pen-pos),
            8px calc(100% - 9px);
    }

    [data-theme='blueprint'] .kp-skeleton--block {
        position: relative;
        border: 0;
        --kp-bp-r: 4;
    }

    [data-theme='blueprint'] .kp-skeleton--block::after {
        --kp-bp-px: calc(clamp(0, var(--kp-bp-r), 1) - clamp(0, var(--kp-bp-r) - 2, 1));
        --kp-bp-py: calc(clamp(0, var(--kp-bp-r) - 1, 1) - clamp(0, var(--kp-bp-r) - 3, 1));
        inset: -8px;
        background-image:
            var(--kp-bp-pen-img), linear-gradient(var(--kp-bp-c-trace), var(--kp-bp-c-trace)),
            linear-gradient(var(--kp-bp-c-trace), var(--kp-bp-c-trace)), linear-gradient(var(--kp-bp-c-trace), var(--kp-bp-c-trace)),
            linear-gradient(var(--kp-bp-c-trace), var(--kp-bp-c-trace));
        background-size:
            var(--kp-bp-pen-size),
            calc(clamp(0, var(--kp-bp-r), 1) * (100% - 16px)) 1px,
            1px calc(clamp(0, var(--kp-bp-r) - 1, 1) * (100% - 16px)),
            calc(clamp(0, var(--kp-bp-r) - 2, 1) * (100% - 16px)) 1px,
            1px calc(clamp(0, var(--kp-bp-r) - 3, 1) * (100% - 16px));
        background-position:
