            repeating-linear-gradient(90deg, var(--border-strong) 0 1px, transparent 1px calc(100% / var(--kp-steps))) center / 100% 56% no-repeat,
            repeating-linear-gradient(90deg, hsl(from var(--border-strong) h s l / 0.55) 0 1px, transparent 1px calc(100% / (var(--kp-steps) * 2)))
