    [data-theme='nostromo'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill::before {
        mask: linear-gradient(90deg, transparent 0 1px, var(--foreground) 1px calc(50% - 1px), transparent 0) 0 0 / calc(200% / var(--kp-steps)) 100%
            repeat-x;
    }

    [data-theme='nostromo'] {
        --kp-sig-no-led: var(--sidebar-primary);
        /* The register's curve; it is shown in whole 80 ms frames
           (--kp-sig-no-f2 … -f8, in kp.register above), never smooth. */
        --kp-sig-no-ease: cubic-bezier(0.2, 0, 0, 1);
        /* Moulded: a highlight along the top edge and a shadow under. */
        --kp-sig-no-raised:
            inset 0 1px 0 hsl(from var(--card) h s calc(l + 8) / 0.9), 0 1px 0 hsl(from var(--foreground) h s l / 0.28),
            0 2px 3px hsl(from var(--foreground) h s l / 0.15);
        /* Pressed in: a shadow inside the top edge, a highlight under. */
        --kp-sig-no-well: inset 0 1px 2px hsl(from var(--foreground) h s l / 0.3), 0 1px 0 hsl(from var(--card) h s calc(l + 8) / 0.8);
        /* A lit LED: a bright lens with a hot centre, in a dark bezel ring. */
        --kp-sig-no-lens: radial-gradient(circle at 40% 35%, var(--primary-foreground) 0 12%, var(--kp-sig-no-led) 30%, var(--accent) 70%);
    }

    /* The tape reel (G11): one turn per loop, 1600 ms, in 20 frames of 80 ms
       (it was 1800 ms, smooth). */
    [data-theme='nostromo'] .kp-spinner {
        --kp-sig-dur: var(--kp-sig-no-loop);
        position: relative;
        border: 0;
        border-radius: 50%;
        /* The tape pack: dark, with a faint wound ring. */
        background: radial-gradient(circle, transparent 0 62%, hsl(from var(--card) h s l / 0.18) 63% 64%, transparent 65%), var(--foreground);
        box-shadow: var(--kp-sig-no-well);
        animation: none;
    }

    [data-theme='nostromo'] .kp-spinner::before {
        content: '';
        position: absolute;
        inset: 18%;
        border-radius: 50%;
        background: repeating-conic-gradient(from -15deg, var(--card) 0 90deg, transparent 90deg 120deg);
        box-shadow: inset 0 1px 0 hsl(from var(--card) h s calc(l + 8) / 0.9);
    }

    [data-theme='nostromo'] .kp-spinner::after {
        --kp-sig-dur: 260ms;
        content: '';
        position: absolute;
        inset: 36%;
        border-radius: 50%;
        background: var(--kp-sig-no-lens);
        box-shadow:
            0 0 0 1.5px var(--foreground),
            0 0 6px hsl(from var(--kp-sig-no-led) h s l / 0.6);
    }

    [data-theme='nostromo'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        --kp-sig-dur: 280ms;
        position: relative;
        overflow: hidden;
        block-size: 0.75rem;
        border-radius: var(--kp-radius-pill, 999px);
        background: hsl(from var(--foreground) h s l / 0.14);
        box-shadow: var(--kp-sig-no-well);
        animation: none;
    }

    [data-theme='nostromo'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)::after {
