    }

    [data-theme='nostromo'] .kp-switch__input::before {
        background:
            repeating-linear-gradient(90deg, hsl(from var(--foreground) h s l / 0.22) 0 1px, transparent 1px 3px) center / 50% 55% no-repeat,
            var(--card);
        box-shadow: var(--kp-sig-no-raised);
    }

    [data-theme='nostromo'] .kp-switch__input:checked {
        border-color: var(--border-strong);
        background:
            radial-gradient(circle at 0.6rem 50%, var(--primary-foreground) 0 0.06rem, var(--kp-sig-no-led) 0.12rem 0.24rem, transparent 0.26rem),
            hsl(from var(--foreground) h s l / 0.1);
