        /* The machined corner: cut, never rounded. Two opposite corners,
           the way a milled part is relieved. */
        --kp-chamfer: var(--fx-notch, 0.55rem);
        --kp-chamfer-panel: 1rem;
        /* How far past its own box the halo reaches, and how far past that
           nothing of it is left [fix-41]. The furthest of the four shadows
           travels its offset plus its blur — 10px + 18px — so 2.5rem is
           past the last pixel of it and short of anything a panel holds. */
        --kp-halo-reach: 2.5rem;
        --kp-halo-field: 100rem;
