        }

        [data-theme='dark'] .kp-field__check:checked::before {
            animation: kp-sig-dark-dark-resolve var(--kp-sig-dur) var(--kp-sig-dark-ease) both;
        }

        [data-theme='dark'] .kp-field__check:checked::after {
            animation: kp-sig-dark-dark-resolve-ghost var(--kp-sig-dur) var(--kp-sig-dark-ease) both;
        }

        [data-theme='dark'] .kp-field__check[type='radio']:checked::before {
            animation-name: kp-sig-dark-dark-dot;
        }

        [data-theme='dark'] .kp-field__check[type='radio']:checked::after {
            animation-name: kp-sig-dark-dark-dot-ghost;
        }

        [data-theme='dark'] .kp-toast {
            animation: kp-sig-dark-dark-settle var(--kp-sig-dur) var(--kp-sig-dark-ease) both;
        }

        [data-theme='dark'] .kp-toast::after,
        [data-theme='dark'] .kp-dialog::after {
            /* backwards, not both: each ends where the rest state is, so a finished
               entrance leaves nothing pinned on the dialog (scope-100 measures it bare). */
            animation: kp-sig-dark-dark-develop var(--kp-sig-dur) ease-out backwards;
        }

        [data-theme='dark'] .kp-dialog {
            animation: kp-sig-dark-dark-settle-in var(--kp-sig-dur) var(--kp-sig-dark-ease) backwards;
        }

        [data-theme='dark'] .kp-tooltip {
            animation: kp-sig-dark-dark-brackets-open var(--kp-sig-dur) var(--kp-sig-dark-ease) backwards;
        }
