    @keyframes kp-sig-dark-dark-turn {
        to {
            transform: rotate(1turn);
        }
    }

    @keyframes kp-sig-dark-dark-ghost-l {
        0%,
        100% {
            opacity: 0;
            transform: none;
        }

        50% {
            opacity: 0.5;
            transform: translateX(-8px);
        }
    }

    @keyframes kp-sig-dark-dark-ghost-r {
        0%,
        100% {
            opacity: 0;
            transform: none;
        }

        50% {
            opacity: 0.5;
            transform: translateX(8px);
        }
    }

    @keyframes kp-sig-dark-dark-resolve {
        from {
            opacity: 0;
            transform: translateX(-4px) translateY(-1px) rotate(-45deg);
        }

        to {
            opacity: 1;
            transform: translateY(-1px) rotate(-45deg);
        }
    }

    @keyframes kp-sig-dark-dark-resolve-ghost {
        from {
            opacity: 0.9;
            transform: translateX(4px) translateY(-1px) rotate(-45deg);
        }

        to {
            opacity: 0;
            transform: translateY(-1px) rotate(-45deg);
        }
    }

    @keyframes kp-sig-dark-dark-dot {
        from {
            opacity: 0;
            transform: translateX(-4px);
        }
    }

    @keyframes kp-sig-dark-dark-dot-ghost {
        from {
