            transform: translateX(4px);
        }

        to {
            opacity: 0;
            transform: none;
        }
    }

    @keyframes kp-sig-dark-dark-settle {
        from {
            opacity: 0;
            transform: translateY(6px);
        }
    }

    @keyframes kp-sig-dark-dark-settle-in {
        from {
            opacity: 0;
            transform: scale(1.02);
        }
    }

    @keyframes kp-sig-dark-dark-develop {
        0% {
            opacity: 0.55;
        }

        100% {
            opacity: 0;
        }
    }

    @keyframes kp-sig-dark-dark-brackets-open {
        from {
            clip-path: polygon(45% 0, 55% 0, 55% 0, 55% 100%, 45% 100%, 45% 100%);
        }

        to {
            clip-path: polygon(0 0, calc(100% - 0.45rem) 0, 100% 0.45rem, 100% 100%, 0.45rem 100%, 0 calc(100% - 0.45rem));
        }
