        --kp-meter-height: 0.5rem;
        --kp-sig-meter-room: 0.625rem;
        --kp-sig-meter-cut: 3px;
        --kp-sig-meter-halo: var(--kp-meter-halo, var(--card));
        border-radius: 0;
        background:
            linear-gradient(
                    135deg,
                    var(--kp-sig-meter-halo) 0 calc(50% - 0.7px),
                    var(--border-strong) calc(50% - 0.7px) calc(50% + 0.7px),
                    transparent 0
                )
                0 0 / var(--kp-sig-meter-cut) var(--kp-sig-meter-cut) no-repeat,
            linear-gradient(
                    -45deg,
                    var(--kp-sig-meter-halo) 0 calc(50% - 0.7px),
                    var(--border-strong) calc(50% - 0.7px) calc(50% + 0.7px),
                    transparent 0
                )
                100% 100% / var(--kp-sig-meter-cut) var(--kp-sig-meter-cut) no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) var(--kp-sig-meter-cut) 0 / calc(100% - var(--kp-sig-meter-cut)) 1px no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 0 100% / calc(100% - var(--kp-sig-meter-cut)) 1px no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 0 var(--kp-sig-meter-cut) / 1px calc(100% - var(--kp-sig-meter-cut)) no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 100% 0 / 1px calc(100% - var(--kp-sig-meter-cut)) no-repeat,
            var(--muted);
    }

    /* Bright machined metal, the oxide film along its top edge laid along
       the whole scale. */
    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)::before {
        inset: 1px;
        inline-size: calc(clamp(0, var(--kp-value, 0), 1) * (100% - 2px));
        border-radius: 0;
        background:
            linear-gradient(90deg, var(--chart-1), var(--chart-2), var(--chart-3), var(--chart-4)) 0 0 /
                calc(100% / clamp(0.01, var(--kp-value, 0), 1)) 2px no-repeat,
            var(--kp-meter-fill-colour);
        clip-path: polygon(
            calc(var(--kp-sig-meter-cut) - 1px) 0,
            100% 0,
            100% calc(100% - var(--kp-sig-meter-cut) + 1px),
            calc(100% - var(--kp-sig-meter-cut) + 1px) 100%,
            0 100%,
            0 calc(var(--kp-sig-meter-cut) - 1px)
        );
    }

    /* A V milled into the edge, a dark cut through the metal. */
    [data-theme='dark'] .kp-meter__mark {
        inset-block: -1px;
        border-radius: 0;
        background: var(--background);
        box-shadow:
            1px 0 0 var(--primary),
            -1px 0 0 var(--primary);
    }

    [data-theme='dark'] .kp-meter__mark::before {
        content: '';
        position: absolute;
        inset-block-end: 100%;
        inset-inline-start: 50%;
        inline-size: 8px;
        block-size: 5px;
        translate: -50% 0;
        background: var(--primary);
        clip-path: polygon(0 0, 100% 0, 50% 100%);
    }

    /* The part runs out of the channel with a chamfered tip. */
    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        inset-inline-start: calc(100% + 2px);
        inset-block: 1px;
        inline-size: 0.4375rem;
        background:
            linear-gradient(90deg, var(--chart-4), var(--chart-1)) 0 0 / 100% 2px no-repeat,
            var(--kp-meter-fill-colour);
        clip-path: polygon(0 0, calc(100% - 3px) 0, 100% 50%, calc(100% - 3px) 100%, 0 100%);
    }

    /* ── while loading: option 2 ── */

    /* Round 4. The oxide film runs: thin bands of the film's colours, the
       way heat tints a polished part, slide along the whole channel. */
    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        all: unset;
        content: '';
        position: absolute;
        inset: 1px;
        pointer-events: none;
        background: linear-gradient(
                90deg,
                hsl(from var(--primary) h s l / 0.35) 0 6px,
                transparent 6px 9px,
                hsl(from var(--accent) h s l / 0.35) 9px 15px,
                transparent 15px 18px
            )
            0 0 / 18px 100% repeat-x;
        --kp-sig-meter-l0: 0 0;
        --kp-sig-meter-l1: 18px 0;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
            animation: kp-sig-dark-meter-pos 900ms linear infinite;
        }
    }

    /* ── how the share arrives: option 3 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)::before {
            animation: kp-sig-dark-meter-press-o 220ms linear backwards;
            transition: inline-size 220ms linear;
            transform-origin: 50% 50%;
        }
    }

    /* ── when the tone changes: option 3 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter):not([data-kp-loading], [data-kp-tone]) {
            animation: kp-sig-dark-meter-bump-o 200ms linear;
        }

        [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='warning']:not([data-kp-loading]) {
            animation: kp-sig-dark-meter-bump-w 200ms linear;
        }

        [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='destructive']:not([data-kp-loading]) {
            animation: kp-sig-dark-meter-bump-d 200ms linear;
        }
    }

    /* ── the mark past the end: option 3 ── */

    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-mo-sign: '▸';
    }

    [data-theme='dark'] .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - var(--kp-sig-meter-mw) - 1px);
        rotate: 24deg;
        transform-origin: 50% 100%;
    }

    [data-theme='dark'] .kp-meter__mark[data-kp-over]::after {
        inset-inline-start: calc(100% + 3px);
        rotate: -24deg;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-meter__mark {
            transition:
                inset-inline-start 300ms linear,
                rotate 300ms linear;
        }
    }

    @keyframes kp-sig-dark-meter-bump-d {
        0% {
            scale: 1;
        }

        40% {
            scale: 1.04 1.3;
        }

        100% {
            scale: 1;
        }
    }

    @keyframes kp-sig-dark-meter-bump-o {
        0% {
            scale: 1;
        }

        40% {
            scale: 1.04 1.3;
        }

        100% {
            scale: 1;
        }
    }

    @keyframes kp-sig-dark-meter-bump-w {
        0% {
            scale: 1;
        }

        40% {
            scale: 1.04 1.3;
        }

        100% {
            scale: 1;
        }
    }

    @keyframes kp-sig-dark-meter-pos {
        0% {
            background-position: var(--kp-sig-meter-l0);
        }

        100% {
            background-position: var(--kp-sig-meter-l1);
        }
    }

    @keyframes kp-sig-dark-meter-press-o {
        0% {
            scale: 1 0;
        }

        100% {
            scale: 1 1;
        }
