    @media (prefers-reduced-motion: no-preference) {
        /* ── sepia: paper. The box unrolls with the curl's shadow under its
           edge, and a new line turns down like a page. ──────────────────── */
        [data-theme='sepia'] [data-kp-resizing] {
            filter: drop-shadow(0 8px 5px hsl(from var(--foreground) h s l / 0.35));
