            from {
                box-shadow: inset 0 0 0 0 var(--foreground);
            }

            40% {
                box-shadow:
                    inset 0 0 12px 6px var(--primary),
                    inset 0 0 2px 2px var(--foreground);
            }

            to {
                box-shadow:
                    inset 0 0 40px 60px var(--foreground),
                    inset 0 0 4px 4px hsl(from var(--foreground) h s calc(l - 10));
            }
        }
    }

    /* ── The meter with a mark, this theme's way [picked by Kenny on
       research/character-meter, round 3, 2026-10-05: shape 1, while
       loading 2, how the share arrives 2, when the tone changes 2,
       the mark past the end 2]. The package's own markup and states
       (setMeter(), js/kpi.js): the track on the meter, the share on ::before,
       the sign past the end or the loading picture on ::after, the mark
       `.kp-meter__mark`. Every animation and transition under
       prefers-reduced-motion: no-preference; still frames otherwise. ── */

    /* The shared part: room past the end, loading without the pulse, the mark
       centred on its width, the package's signs cleared for the shape's own.
       Under :where() so each picked rule below wins as it did in the demo. */
    :where([data-theme='sepia']) :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-room: 0.625rem;
        box-sizing: border-box;
    }

    :where([data-theme='sepia']) .kp-meter--inline {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-sig-meter-room));
    }

    /* Each character draws its own loading picture instead of the pulse. */
    :where([data-theme='sepia']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: clip;
        animation: none;
    }

    :where([data-theme='sepia']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    /* The mark is centred on its share, whatever its width. */
    :where([data-theme='sepia']) .kp-meter__mark {
        --kp-sig-meter-mw: 2px;
        box-sizing: border-box;
        inline-size: var(--kp-sig-meter-mw);
        inset-inline-start: calc(clamp(0, var(--kp-mark, 0), 1) * 100% - var(--kp-sig-meter-mw) / 2);
    }

    :where([data-theme='sepia']) .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - 0.75rem);
    }

    /* The sign past the end, cleared of the package's ▸ for each character
       to draw its own. */
    :where([data-theme='sepia']) :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '';
        position: absolute;
        inset: auto;
        translate: none;
        color: inherit;
        font-size: 0.75rem;
        line-height: 1;
        text-shadow: none;
        white-space: nowrap;
        pointer-events: none;
    }

    /* A mark past the end keeps the package's sign inside the bar's end, in
       each character's own glyph and ink. */
    :where([data-theme='sepia']) .kp-meter__mark[data-kp-over]::after {
        content: var(--kp-sig-meter-mo-sign, '▸');
        color: var(--kp-sig-meter-mo-ink, var(--foreground));
        font-family: var(--kp-sig-meter-mo-font, inherit);
        text-shadow:
            0 0 1px var(--kp-sig-meter-mo-halo, var(--card)),
            0 0 2px var(--kp-sig-meter-mo-halo, var(--card));
    }

    /* ── shape: option 1 ── */

    /* ── sepia · the letterpress impression ───────────────────────── */
    [data-theme='sepia'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-meter-height: 0.5rem;
        --kp-sig-meter-room: 0.75rem;
        --kp-sig-meter-mo-ink: var(--primary);
        border-radius: 1px;
        background: var(--muted);
        box-shadow:
            inset 0 1px 1px hsl(from var(--foreground) h s l / 0.3),
            inset 0 -1px 0 hsl(from var(--card) h s l / 0.9),
            0 0 0 1px hsl(from var(--border-strong) h s l / 0.6);
    }

    /* Inked into the impression, squashed at its edges, speckled. */
    [data-theme='sepia'] :is(.kp-meter, .kp-kpi__meter)::before {
        border-radius: 1px;
        background:
            radial-gradient(circle, hsl(from var(--card) h s l / 0.2) 0 0.5px, transparent 0.9px) 0 0 / 3px 3px,
            var(--kp-meter-fill-colour);
        box-shadow:
            inset 0 1px 0 hsl(from var(--foreground) h s l / 0.4),
            inset 0 -1px 0 hsl(from var(--foreground) h s l / 0.4),
            inset -1px 0 0 hsl(from var(--foreground) h s l / 0.5);
    }

    /* A brass rule with a pilcrow above it. */
    [data-theme='sepia'] .kp-meter__mark {
        --kp-sig-meter-mw: 3px;
        inset-block: -3px;
        border-radius: 0;
        background: var(--card);
        box-shadow: 0 0 0 1px var(--fx-signal);
    }

    [data-theme='sepia'] .kp-meter__mark::before {
        content: '¶';
        position: absolute;
        inset-block-end: calc(100% + 1px);
        inset-inline-start: 50%;
        translate: -50% 0;
        color: var(--primary);
        font: 700 0.625rem/1 var(--theme-font-display, serif);
    }

    /* The ink squeezed out past the end. */
    [data-theme='sepia'] :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        inset-inline-start: 100%;
        inset-block: 0;
        inline-size: 0.5625rem;
        background: linear-gradient(90deg, var(--kp-meter-fill-colour), hsl(from var(--kp-meter-fill-colour) h s l / 0.15));
        clip-path: polygon(0 0, 100% 30%, 100% 70%, 0 100%);
    }

    /* ── while loading: option 2 ── */

    [data-theme='sepia'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        animation: none;
    }

    [data-theme='sepia'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        all: unset;
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
        background: radial-gradient(circle, hsl(from var(--foreground) h s l / 0.5) 1px, transparent 1.5px) 0 50% / 5px 100% repeat-x;
        inset-inline-end: auto;
        inline-size: 100%;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='sepia'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
            animation: kp-sig-sepia-meter-width 2200ms ease-in-out infinite;
        }
    }

    /* ── how the share arrives: option 2 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='sepia'] :is(.kp-meter, .kp-kpi__meter)::before {
            animation: kp-sig-sepia-meter-slant-o 1100ms cubic-bezier(0.4, 0, 0.6, 1) backwards;
            transition: inline-size 1100ms cubic-bezier(0.4, 0, 0.6, 1);
        }
    }

    /* ── when the tone changes: option 2 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='sepia'] :is(.kp-meter, .kp-kpi__meter):not([data-kp-loading], [data-kp-tone]) {
            animation: kp-sig-sepia-meter-knock-o 280ms ease-out;
        }

        [data-theme='sepia'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='warning']:not([data-kp-loading]) {
            animation: kp-sig-sepia-meter-knock-w 280ms ease-out;
        }

        [data-theme='sepia'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='destructive']:not([data-kp-loading]) {
            animation: kp-sig-sepia-meter-knock-d 280ms ease-out;
        }
    }

    /* ── the mark past the end: option 2 ── */

    [data-theme='sepia'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-mo-sign: '¶';
    }

    [data-theme='sepia'] .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - var(--kp-sig-meter-mw) - 1px);
        rotate: 24deg;
        transform-origin: 50% 100%;
    }

    [data-theme='sepia'] .kp-meter__mark[data-kp-over]::after {
        inset-inline-start: calc(100% + 3px);
        rotate: -24deg;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='sepia'] .kp-meter__mark {
            transition:
                inset-inline-start 600ms ease-in-out,
                rotate 600ms ease-in-out;
        }
    }

    @keyframes kp-sig-sepia-meter-knock-d {
        0% {
            translate: 0 0;
        }

        30% {
            translate: 0 -3px;
        }

        60% {
            translate: 0 1px;
        }

        100% {
            translate: 0 0;
        }
    }

    @keyframes kp-sig-sepia-meter-knock-o {
        0% {
            translate: 0 0;
        }

        30% {
            translate: 0 -3px;
        }

        60% {
            translate: 0 1px;
        }

        100% {
            translate: 0 0;
        }
