            clip-path: inset(-30px -30px 0 -30px);
        }
    }

    @keyframes kp-sig-solstice-solstice-dawn {
        from {
            opacity: 0;
            transform: translateY(18px);
        }

        to {
            opacity: 1;
            transform: none;
        }
    }

    @keyframes kp-sig-solstice-solstice-ember {
        from {
            opacity: 0;
            transform: scale(0.94);
        }

