    [data-theme='solstice'] :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(.kp-alarm *):is(a.kp-kpi, .kp-kpi--toggle):not([data-kp-tone]) .kp-kpi__label {
